pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (1..=100) are dead weight. Penalize gaps below a usable
    // threshold with a super-linear blowup.
    let usable_threshold = 30.0f64;
    if (post_residual as f64) < usable_threshold {
        let gap = usable_threshold - post_residual as f64;
        score += gap * gap * 0.9; // quadratic dead-space penalty
    }

    // Reward near-perfect fits (tiny post_residual is excellent, not dead).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // disfavor opening new bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score -= 6.0; // fresh bin has full residual, base already high
        score += pressure * 4.0;
    } else {
        score -= pressure * 1.5;
    }

    // Lookahead (k=2): if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            // next item can't use this gap anyway; dead space is more tolerable
            score += 2.0;
        }
    }

    // Mean-residual coupling: if open bins are already tight on average,
    // prefer placing into this bin rather than fragmenting further.
    if bin_residual != bin_capacity && (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Slight mid-stream tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement chains nicely.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bonus: only one open bin fits, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, allow slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * 3.0;

    // Prefer bins whose residual is near the mean residual (keeps pool uniform).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.3;

    // New-bin candidate: only attractive when current bin residuals are poor fits.
    if bin_residual == bin_capacity {
        let bad_pool = if mean_residual < item_size as f64 { 1.0 } else { 0.0 };
        score = 40.0 - 55.0 * bad_pool - 20.0 * (fitting_bins_count == 0) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to current residual (low waste ratio).
    if bin_residual > 0 {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fit_ratio;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    // (large mean residual spread / many bins) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = (open_bins_count as f64 * mean_residual) / bin_capacity as f64;
        score = bin_capacity as f64 - 40.0 * desperation + 20.0 * progress;
        if post_residual == bin_capacity {
            // default new-bin baseline; keep mildly high so good fits win
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: waste after placement, mildly damped as stream progresses
    let mut score = pr * (1.0 - 0.25 * progress);

    // Non-linear polynomial coupling of post-residual with progress:
    // early stream: prefer tight fits (low post_residual); late stream: tolerate larger residuals
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += 20.0 * poly * (1.0 - progress);

    // Penalize residuals that are small but nonzero (dead space)
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (1.0 - pr / 10.0);
    }

    // Reward perfect fits
    if pr == 0 {
        score -= 15.0;
    }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (ni / cap);
            // extra reward if next item fills residual nicely
            let fill = 1.0 - ((pr - ni) / cap);
            score -= 4.0 * fill * fill;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate: bias toward opening a fresh bin when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / cap);
        score = 10.0 + 0.5 * mean_residual - 2.0 * crowded + 30.0 * progress;
    }

    score
}

