pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: dead space.
            score += 60.0;
        } else if post_residual <= 20 {
            // Only usable by the smallest items; partial dead space.
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to item size.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness * (item_size as f64 / bin_capacity as f64);

    // Last chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from open bins count: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: penalize bins whose residual deviates from mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 15.0; // next item can't use this gap either
    }

    // New-bin candidate: neutral-ish baseline; only attractive when existing fits are terrible.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 12) are wasted capacity. Penalize hard.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 + (12 - post_residual) as f64 * 8.0;
    }
    // "Awkward zone": gaps that only tiny items can use (13..=20).
    if post_residual >= 13 && post_residual <= 20 {
        score += 18.0;
    }

    // Reward tight fits (best-fit core), super-linear.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Perfect closure is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering into many bins when
    // open_bins_count is high, unless the fit is very tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Mean-residual coupling: if this bin's residual is far below average,
    // it is a "leftover" bin; using it for a big item is efficient.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.35;

    // Last-chance bin: strongly prefer filling the only bin that fits,
    // avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item would fit the post-residual, this placement
    // chains nicely; reward. If next item is large and barely misses,
    // slight penalty for stranding capacity.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 10.0;
        }
    }

    // New-bin candidate: neutral-ish baseline, slightly worse than a decent
    // fit but better than creating dead space. Scales with stream progress
    // and existing bin count (prefer consolidation early, allow new bins later).
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 1.5 - progress * 15.0;
        // If no open bin fits well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        if post_residual == 0 { score -= 40.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Dead-space penalty: small unusable gaps (< smallest plausible next item) are costly.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 } else if post_residual < 25 { 35.0 } else { 0.0 };
        score += dead * (post_residual as f64 / 25.0).min(1.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 { score -= 50.0; }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 40.0; }

    // Lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            // leaving a gap smaller than the next item is bad
            score += 15.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer new bin less.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's chosen only when fits are poor.
        score += 55.0;
        score -= 10.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 5.0)));
