    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }
    if fitting_bins_count <= 2 && post_residual > 0 && post_residual < item_size {
        score += 1.0;
    }

    // New-bin candidate: open only when no open bin offers a good fit
    if bin_residual == bin_capacity {
