pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect completion: strongly reward zeroing out a bin.
    if post_residual == 0 {
        score -= 520.0;
    }

    // Dead-space avoidance: unusable slivers are pure waste; penalize non-linearly.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Reward tight fits (quadratic near-perfect packing bonus).
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 25.0 * tightness * tightness;

    // Strong lookahead: exact pairing with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 130.0 * (1.0 - gap as f64 / cap);
        if gap == 0 {
            score -= 220.0;
        } else if gap <= 4 {
            score -= 80.0 + 8.0 * (4 - gap) as f64;
        } else if gap <= 12 {
            score -= 12.0 + 1.2 * (12 - gap) as f64;
        }
        // Two-step anticipation: prefer residuals that also leave room after pairing.
        if gap > 0 && gap < 6 && next_item_size >= gap {
            score += 3.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here: dead space this step.
        let dead = (next_item_size - post_residual) as f64;
        score += 45.0 + 0.15 * post_residual as f64;
        if dead <= 5 {
            score += 6.0 + dead;
        }
    }

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Mean-residual coupling: prefer bins that shrink toward the mean.
    if post_residual > 0 {
        if (post_residual as f64) < mean_residual * 0.8 {
            score -= 35.0;
        } else if (post_residual as f64) > mean_residual * 1.4 {
            score += 18.0;
        }
        // Borrowed from best: small residuals are valuable, keep them attractive.
        if post_residual < 10 {
            score -= 25.0;
        }
    }

    // Open-bin pressure: discourage new bins when many are open, scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.5;

    // New-bin candidate handling: usually bad, but cheaper when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = mean_residual < item_size as f64 * 1.05;
        if poor_fit_everywhere {
            score += 10.0;
        } else {
            score += 60.0;
        }
        if progress > 0.8 {
            score += 40.0 * (progress - 0.8) * 5.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && fitting_bins_count > 0 && open_bins_count > 1 {
            let nr = bin_capacity - next_item_size;
            if nr < 8 {
                score += 25.0;
            }
        }
        if open_bins_count <= 2 {
            score -= 15.0;
        }
        // Opening a new bin that exactly fits the item is excellent.
        if item_size == bin_capacity {
            score -= 300.0;
        }
    }

    // Late-stream sliver sweeping: endgame reuse of tiny residuals.
    if total_items > 0 && step_index > total_items * 3 / 4 && post_residual > 0 && post_residual < 12 && fitting_bins_count > 1 {
        score -= 20.0;
    }

    // Crowding: when many bins fit, slightly penalize tight post-residuals.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Guard against stranded slivers when alternatives exist.
    if post_residual > 0 && post_residual < 10 && fitting_bins_count > 1 && next_item_size > post_residual {
        score += 4.0 + 0.5 * (10 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: unusable slivers are pure waste; penalize non-linearly.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Reward tight fits (quadratic near-perfect packing bonus).
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage new bins when many are open, scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate handling: offset base cost only when fragmentation is high.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 + 0.5 * fragmentation;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.25 {
            score -= 15.0;
        }
        if post_residual as f64 > mean_residual * 1.5 && next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Lookahead: perfect two-item pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            // Two-step lookahead: residual after next item pairs with item itself.
            if gap == next_item_size as u32 {
                score -= 3.0;
            } else if gap > 0 && gap < 10 {
                score -= 2.0 + 0.2 * (10 - gap) as f64;
            }
            // Half-slack trap: leftover barely too small to reuse.
            if slack > 0.0 && slack < next_item_size as f64 && slack * 2.0 > next_item_size as f64 {
                score += 1.5;
            }
            // Dead-space ratio coupling — penalize bins whose post-fit leftover
            // is a large fraction of capacity while many alternatives exist.
            if fitting_bins_count > 2 && post_residual as f64 > cap * 0.45 {
                score += 2.0 + 2.0 * (post_residual as f64 / cap);
            }
            // COMBINED: fine-grained residual coupling with lookahead — reward
            // bins whose post-residual lands in the reusable mid-band (>= 21)
            // when the next item can consume most of it.
            if post_residual >= 21 && next_item_size >= 8 && (post_residual as f64) <= cap * 0.6 {
                let reuse = next_item_size as f64 / post_residual as f64;
                if reuse > 0.5 {
                    score -= 3.0 * reuse;
                }
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Prefer bins below mean residual (keep large residuals for large items).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Crowding: when many bins fit, slightly penalize tight post-residuals to
    // avoid hoarding near-perfect bins needed for exact pairings.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Reward completing this bin when the next item can also fit the leftover.
    if post_residual <= 4 && next_item_size > 0 && next_item_size >= post_residual {
        score -= 6.0;
    }

    // COMBINED: guard against creating stranded slivers that no typical item
    // (>= 10) can ever reuse, scaled by how many alternatives exist.
    if post_residual > 0 && post_residual < 10 && fitting_bins_count > 1 && next_item_size > post_residual {
        score += 4.0 + 0.5 * (10 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item => huge reward
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).exp() * (1.0 - diff / (bin_capacity as f64)).exp();
        // Slight extra reward if next item fits exactly
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a residual that the next item cannot use at all
        if next_item_size > post_residual {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer minimal waste directly
        score += 0.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving residual well below mean means we consolidated space well.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a good fit. Penalize the fresh bin mildly so tight existing fits win.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if open bins are very full on average, a new bin is reasonable
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Late in the stream, tighten packing further (waste matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Small pressure toward fewer open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste-aware, quadratic penalty on post residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: penalize creating residual too small for the next item (dead space),
    // but reward residual that exactly (or nearly) accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 5 {
            score -= 12.0; // chains nicely with next item
        } else if post_residual < next_item_size && post_residual > 0 {
            let dead = post_residual as f64;
            score += 0.35 * dead * (1.0 + (step_index as f64) / (total_items.max(1) as f64));
        }
    }

    // Prefer filling bins with large residuals early (avoid many half-empty bins).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += 3.0 * residual_frac;

    // Slight penalty when many bins are open: encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual deviates positively
    // (fill the emptiest bins first) to reduce fragmentation.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in the stream, be more conservative — favor closing bins
    // out completely rather than leaving slivers.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    // New-bin candidate: make it attractive only when the item is large relative
    // to capacity or no good fit exists elsewhere; otherwise keep it costly.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = 40.0 * item_frac + 20.0 * (1.0 - item_frac);
        // If many bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 12.0;
        }
        // Late stream: opening new bins is more costly (stranded residuals).
        score += 10.0 * progress;
        // If item is huge, new bin is often best.
        if item_size >= 70 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (favor exploring); late, waste is costly.
    let progress_coupling = 1.0 + 1.5 * progress * progress + 0.5 * (1.0 - progress);
    score *= progress_coupling;

    // Dead-space quadratic penalty: residuals too small to fit the smallest
    // plausible items become unusable; penalize quadratically.
    let dead = ((40.0 - post) / 40.0).max(0.0);
    score += 25.0 * dead * dead * (0.5 + progress);

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * (0.6 + 0.4 * progress);
        // Perfect chaining bonus (smooth, not piecewise).
        let fit_quality = 1.0 - (gap / cap).min(1.0);
        score -= 15.0 * fit_quality * fit_quality;
    }

    // Last-chance bin: strongly reward using it (avoid opening a new bin).
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: only attractive when it can absorb future mass,
    // i.e., when existing open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (mean_residual / cap).min(1.0);
        score = 20.0 + 60.0 * (1.0 - crowded) * (1.0 - progress) - 25.0 * crowded * progress;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    // Mild regularization against bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

