        // which already hurts it via the dead-space ladder; give it a bonus
        // proportional to item size (large items deserve fresh bins).
        score -= item_size as f64 * 0.6;
        // If many bins are open and mean residual is small (fragmented),
        // opening fresh is even better.
        if open_bins_count > 3 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // Late in the stream, keep bins consolidated: penalize new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Slight preference for fuller bins among ties (lower post_residual wins already,
    // but tie-break by bin index proxy via mean residual deviation).
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps smaller than the minimum item size are pure waste.
    if post_residual < 10 {
        score += 200.0;
    }

    // Soft penalty: gaps that likely cannot fit the next item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead synergy: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate relative to reuse).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += 45.0 + pressure * 8.0;
    } else {
        score -= pressure * 4.0;
    }

    // Prefer bins tighter than the average residual (best-fit style refinement).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item => huge reward
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).exp() * (1.0 - diff / (bin_capacity as f64)).exp();
        // Slight extra reward if next item fits exactly
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a residual that the next item cannot use at all
        if next_item_size > post_residual {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer minimal waste directly
        score += 0.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving residual well below mean means we consolidated space well.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a good fit. Penalize the fresh bin mildly so tight existing fits win.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if open bins are very full on average, a new bin is reasonable
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Late in the stream, tighten packing further (waste matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Small pressure toward fewer open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 unknown,
    // use a soft threshold around 15) are hard to reuse.
    if post_residual > 0 && post_residual < 15 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // next item fits: mildly good, better the tighter it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 2.0 * (over / (bin_capacity as f64));
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Prefer bins with residual below the mean (converging residuals toward uniformity),
    // which helps future pairings.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, and when many bins are open.
        score += 8.0 * progress + 0.3 * (open_bins_count as f64);
        // But allow a new bin if current item is large and no open bin fits well.
        if (item_size as f64) > 0.7 * (bin_capacity as f64) && fitting_bins_count == 0 {
            score -= 5.0;
        }
    } else {
        // Late stream: reward using existing bins more.
        score -= 3.0 * progress;
    }

    // Mild penalty for very fragmented bin pool relative to item size.
    if (open_bins_count as f64) > 2.0 * mean_residual {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;

    // Base: prefer small post-residual, with quadratic sharpening of tight fits.
    let mut score = pr * (1.0 + 0.8 * fit_norm * (1.0 - fit_norm) + 1.5 * fit_norm * fit_norm);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on tolerate slack; late in the stream punish wasted space more.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * pr;

    // Interaction: post_residual^2 scaled by progress (dead space matters more later).
    score += 0.02 * pr * pr * (0.3 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can still fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            // penalize creating residual just below next item size (dead space)
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * (1.0 - gap) * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // New-bin candidate: penalize opening a new bin unless the fit is truly tight.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (1.0 - fit_norm) * (1.0 - fit_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: bins whose residual falls into
    // "reusable" classes (large, or exactly matching common item sizes) are favored.
    let cap = bin_capacity as f64;

    // Class 1: large residual halves are highly reusable -> reward.
    if post_residual >= bin_capacity / 2 {
        score -= 12.0 * (post_residual as f64 / cap);
    } else if post_residual >= bin_capacity / 4 {
        score -= 4.0;
    } else if post_residual > 0 {
        // Small dead space classes: penalize by how far from a "perfect" fill.
        score += 8.0 * (1.0 - post_residual as f64 / (bin_capacity / 4) as f64);
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Modulo coupling: gap that exactly matches next item (or a harmonic divisor
    // of capacity) is a great fit for the lookahead.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            // Reward leaving room that is a near-multiple class of next item.
            let gap_class = post_residual / next_item_size.max(1);
            if gap_class == 1 {
                score -= 10.0;
            }
            // Penalize wasting gap much larger than needed for next item only
            // if it creates a sub-quarter remainder.
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < bin_capacity / 4 {
                score += 5.0;
            }
        } else {
            // Next item cannot use this bin's gap: mild penalty for tight classes.
            score += 3.0;
        }
    }

    // Integer-division thresholds on item size (harmonic size classes).
    let item_class = item_size / 20; // 0..4
    match item_class {
        0 => score -= 2.0,           // tiny item: easy to place anywhere
        3 | 4 => score -= 5.0,       // large item: placing it now avoids future trouble
        _ => {}
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (residual would remain large) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Don't open new bins when existing bins have plenty of room.
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0;
        }
    }

    // Mild pressure toward consolidating into few bins late in the stream.
    if open_bins_count > 1 {
        score += (open_bins_count as f64).ln() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals too small for the
    // smallest possible item (1..100 unknown range -> treat <10 as dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Penalize dead space that cannot fit the lookahead item either.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward bins whose post_residual still fits the next item (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, allow opening new bins for better residual structure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins open, costly otherwise.
        score -= 8.0 - 4.0 * pressure;
        // Slightly less attractive late in the stream.
        score += (step_index as f64 / total_items.max(1) as f64) * 2.0;
    } else {
        score += pressure * 0.5;
    }

    // Prefer bins tighter than the mean residual (compact fills).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 900.0;
    }
    // Next item fits comfortably in post_residual: moderate reward
    else if next_item_size > 0 && next_item_size < post_residual {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.5;
    }
    // Next item cannot use the residual: penalize dead space
    else if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Prefer bins whose residual is tighter than average (less wasteful)
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Penalize small unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Early in stream: keep residuals large/flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * (1.0 - progress);

    // Slight preference to fill existing bins over opening new ones
    if bin_residual < bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early on, prefer compact packing; later, tolerate spread.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Waste ratio: fraction of bin turned into dead space.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Lookahead: if next item fits in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64).powi(2));
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Global state: many open bins with high mean residual -> encourage filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    if open_bins_count > 2 {
        score -= 8.0 * pressure;
    } else {
        score += 5.0 * (1.0 - pressure);
    }

    // Perfect-fit bonus (tight packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Late stream: discourage opening new bins, keep consolidating.
    score += t * 12.0 * (bin_residual == bin_capacity) as i32 as f64;

    // New-bin candidate should only win when it genuinely looks better.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let p2 = prn * prn;
    let p3 = p2 * prn;

    // Dead-space penalty grows quadratically; amplified late in the stream.
    let dead_penalty = p2 * (0.5 + 1.5 * progress);
    score += dead_penalty * bin_capacity as f64;

    // Cubic term: very tight fits (small post_residual) are strongly rewarded,
    // and the reward deepens as the stream progresses.
    score -= (1.0 - p3) * (1.0 + progress) * 5.0;

    // Interaction: post_residual vs. mean residual — penalize bins whose
    // residual deviates from the fleet mean, scaled by progress.
    let dev = (pr - mean_residual) / bin_capacity as f64;
    score += dev * dev * 10.0 * (0.3 + progress);

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward heavily; if post_residual is too small for next item, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_gap = (pr - nx) / bin_capacity as f64;
            score -= (1.0 - fit_gap) * (2.0 + 3.0 * progress);
        } else {
            score += (nx - pr) / bin_capacity as f64 * 4.0 * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Crowding pressure: many open bins -> prefer filling existing ones.
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += crowd * (2.0 + 4.0 * prn);

    // New-bin candidate: make it mildly unattractive unless it is clearly better.
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_frac = post / cap_f;

    // Perfect-fill reward: post_residual near zero is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Dead-space penalty via harmonic classes: leftover space that cannot
    // accommodate typical small items (classes: 0..10, 10..20, 20..50, 50+)
    if post_residual > 0 && post_residual < 10 {
        score += 120.0; // unusable dead space class
    } else if post_residual < 20 {
        score += 40.0;
    } else if post_residual < 50 {
        score -= 20.0; // still useful mid-range residual
    } else {
        score -= 30.0; // large residual remains flexible
    }

    // Integer division thresholds: how many "unit slots" of the next item fit
    if next_item_size > 0 && post_residual >= next_item_size {
        // lookahead fits: strong reward scaled by leftover after lookahead
        let post2 = post_residual - next_item_size;
        score -= 80.0;
        if post2 == 0 { score -= 200.0; }
        else if post2 < 10 { score += 30.0; }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportionally to how close it was
        score += 25.0;
    }

    // Modulo arithmetic on post_residual: harmonics of small-item sizes
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 15.0; // round harmonic leftover aligns with item grid
        }
        if post_residual % 20 == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate logic: opening a new bin is only good if current bin
    // fit is poor (large post_residual) and many bins are already open
    if bin_residual == bin_capacity {
        // baseline for fresh bin: score is capacity; adjust by stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64;
        score = cap_f - 60.0 * progress - 5.0 * openness;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.3;
        }
        // discourage opening new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 && residual_frac < 0.5 {
            score += 150.0;
        }
    }

    // Mild preference for bins below mean residual (balancing load)
    score += 0.1 * (mean_residual - post).abs() * (post < mean_residual) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. Define "unusable" as post_residual < 10 (min item
    // size) or slightly above typical small sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead gap: nothing can ever go there
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit: zero waste
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // only tiny items fit later; mild penalty
    }

    // Reward tight fits: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins => discourage spreading, prefer new bin
    // only for very good fits; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportional to number of open bins,
        // unless the item is huge and would waste little space.
        score += 8.0 + 2.0 * open_bins_count as f64;
        if item_size >= 60 {
            score -= 12.0;
        }
    } else {
        // Existing bin: mild reward when open bin count is high (consolidate).
        score -= 0.3 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot fit here anyway; slightly less pressure to keep gap
        score += 3.0;
    }

    // Stream progression: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean
    // (i.e., tighter bins) when placing.
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * match_quality;
        // Perfect chain: post_residual == next_item_size exactly
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
    }

    // Compare post_residual against mean residual: prefer leaving typical-sized gaps
    let mr = post_residual as f64 - mean_residual;
    score += 0.15 * mr;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize tight fits that leave tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward filling bins completely (post_residual == 0)
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in stream, opening new bins is cheaper (more future flexibility)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If many open bins already fit the item, opening a new bin is wasteful
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // If next item is large, a fresh bin is valuable for it
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Mild preference for bins tighter than average (better packing density)
    score += 0.1 * (bin_residual as f64 - bin_capacity as f64 / 2.0) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness * tightness;

    // Exact or near-exact closure is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into post_residual, this placement is valuable.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (next_item_size as f64 / post_residual as f64).powi(2));
        } else {
            // Dead space the next item cannot use: penalize.
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last chance: strongly prefer filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins with residual close to the item (minimizes fragmentation).
    let gap = (bin_residual - item_size) as f64;
    score += 0.15 * gap;

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += 3.0 * (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);

    // Time horizon: early on, be conservative about wasting space; late, close bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - tightness);

    // New-bin candidate: only attractive if this bin would otherwise be a bad fit
    // (large dead space) or no open bins exist.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 12.0 + 0.3 * mean_residual - 20.0 * progress;
            // Discourage opening a new bin when the item would fit well somewhere.
            if post_residual + item_size <= 60 {
                score += 25.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = rn * rn * (1.0 - progress) + rn * (0.5 + 0.5 * progress);

    let mut score = r + 40.0 * poly;

    // Reward tight fits smoothly (quadratic in fill ratio)
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 + progress);

    // Penalize creating residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - r).max(0.0) / cap;
        score += 25.0 * gap * gap;
        // Bonus if post_residual still fits next item (smooth)
        let fitn = if r >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 10.0 * fitn * (1.0 - rn);
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Smooth penalty for spreading across many bins
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);

    // New-bin candidate: mildly penalize opening new bins early, allow later
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space: modulo-10 classes ---
    // Leftovers divisible by 10 are "harmonic" (likely reusable by future items
    // whose sizes are also multiples of 10). Penalize non-harmonic leftovers.
    let harm = post_residual % 10;
    score += match harm {
        0 => -8.0,                       // perfectly harmonic leftover
        5 => 3.0,                        // half-harmonic
        _ => 4.0 + harm as f64 * 0.5,    // inharmonic dead space, worse the larger
    };

    // Exact fit is always perfect.
    if post_residual == 0 {
        return -1000.0;
    }

    // --- Integer-division thresholds on post_residual ---
    // Classify leftover into usable bands: >=50 (big), 30-49 (medium), 10-29 (small).
    let band: f64 = if post_residual >= 50 {
        0.0
    } else if post_residual >= 30 {
        5.0
    } else if post_residual >= 10 {
        12.0
    } else {
        25.0
    };
    score += band;

    // --- Harmonic coupling with next item (k=2 lookahead) ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect slot for the next item
        } else if post_residual >= next_item_size {
            // Reward if leftover can still host the next item, scaled by
            // how "cleanly" (harmonically) it swallows it.
            let slack = post_residual - next_item_size;
            let clean = (slack % 10 == 0) as f64 * 10.0;
            score -= 20.0 + clean - slack as f64 * 0.2;
        } else {
            // Leftover too small for next item: penalize proportionally to waste.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Harmonic class match: next item multiple of 10 pairs with 10-divisible leftovers.
        if next_item_size % 10 == 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }
    }

    // --- Last-chance bin: strongly favor using the only fitting bin ---
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // --- Capacity-fraction pressure: prefer filling bins that are already dense ---
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // --- Stream progression: late in the stream, avoid opening new bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above using an existing bin,
        // but relax late in the stream when open bins are fragmented.
        score = 55.0 - progress * 15.0 + (post_residual as f64) * 0.3;
    } else {
        score -= progress * 5.0;
    }

    // Slight bonus for keeping the number of open bins low.
    score += open_bins_count as f64 * 0.4;

    // Mean-residual alignment: if this bin's residual is far above mean, it's fragmented.
    let dev = post_residual as f64 - mean_residual;
    score += dev.abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 6.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // nearly dead gap
    }

    // Reward perfect/near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Prefer bins whose residual is close to item size (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Open-bin pressure: discourage spreading across many bins unless it helps.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item would leave a bad gap elsewhere.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            // keep last-chance bin attractive; new bin slightly worse
            score += 30.0;
        }
        // if next item is large, a fresh bin is valuable
        if next_item_size > 60 {
            score -= 25.0;
        }
    }

    // Lookahead: if post_residual exactly matches next item, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 25.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // concentrates space, which is good for future large items.
    if bin_residual != bin_capacity {
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward perfect/near-perfect match with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match bonus: next item fills this bin completely
        if post_residual == next_item_size {
            score -= 1000.0;
        } else {
            // Penalize residual mismatch with next item size
            score += diff * 1.5;
            // Extra penalty if next item cannot fit into post_residual
            if post_residual < next_item_size {
                score += 40.0;
            }
        }
    }

    // Reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Penalize dead space: residuals too small to hold any plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Discourage opening new bins when good fitting options exist
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64 * 2.0);
        // But allow new bin if current bin would leave a very fragmented residual
        if post_residual < 15 && next_item_size > 0 && post_residual < next_item_size {
            score -= 55.0;
        }
    }

    // Late in stream: prefer filling existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: penalize large post_residual, especially when it becomes dead space.
    let dead_threshold = (bin_capacity as f64) * 0.15;
    if (post_residual as f64) < dead_threshold {
        // Near-perfect fit: strong reward.
        score -= 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    } else {
        // Large leftover: penalize proportionally, worse late in the stream.
        score += 0.05 * (post_residual as f64 - dead_threshold) * (0.5 + progress);
    }

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.1 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; penalize leaving awkward fragments that block the lookahead.
        let waste = post_residual as f64;
        if waste < next_item_size as f64 {
            score += 0.15 * (next_item_size as f64 - waste) * (0.5 + progress);
        }
    }

    // Global state: prefer filling bins with low residual when many bins are open (consolidation).
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        // This bin is tighter than average: good, reward more when many bins are open.
        score -= 0.1 * mean_gap * (open_bins_count as f64).sqrt();
    } else {
        // This bin is looser than average: mild penalty.
        score += 0.05 * (-mean_gap);
    }

    // Open-bin pressure: when many bins are open, discourage spreading onto fresh space;
    // when few bins are open, allow flexibility.
    if open_bins_count > 4 {
        score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Penalize opening a new empty bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 20.0;
        // But if no open bin is a good fit (this is the only candidate or fits are scarce),
        // discount the new-bin cost so we don't fragment items.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Late in the stream, avoid opening new bins more aggressively.
        score += 15.0 * progress;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize wasted space, with a smooth non-linear shaping of post_residual
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Tight fits are strongly rewarded (quadratic coupling)
    let tightness = 1.0 - pr / cap; // 1 = perfect fit
    score -= 30.0 * tightness * tightness;

    // Stream-progress coupling: early on, prefer filling bins loosely to keep options;
    // later, be aggressive about tight packing.
    score -= 20.0 * progress * tightness * tightness;
    score += 10.0 * (1.0 - progress) * (pr / cap);

    // Penalize bins whose residual is far from mean residual (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let slack = (pr - n) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            score += 6.0 * ((n - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate bias: only attractive when stream is early or fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0 * progress + 10.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact small classes are "dead space" classes.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left

    // Penalize residuals that fall into "unusable" harmonic classes.
    // Small residuals (< ~1/8 of capacity) are nearly dead space.
    if post_residual > 0 {
        let class = post_residual % 10;
        let dead_penalty = match class {
            1 | 2 | 3 => 6.0,
            4 | 5 => 3.0,
            6 | 7 => 1.5,
            _ => 0.0,
        };
        // Dead space penalty scales with how small the residual is relative to capacity
        if frac < 0.125 {
            score += dead_penalty + 10.0;
        } else if frac < 0.25 {
            score += dead_penalty;
        } else {
            score -= dead_penalty * 0.5; // generous residual is fine
        }
    } else {
        score -= 25.0; // perfect closure is excellent
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how "snug" the next fit is
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 12.0 * snug;
        } else {
            // next item does NOT fit: penalize more if post_residual is in a dead class
            let wasted = post_residual as f64 / next_item_size.max(1) as f64;
            score += 4.0 * (1.0 - wasted.min(1.0));
        }
    } else {
        // last item: closing bins is free bonus
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 3 {
        score += 2.0; // plenty of alternatives, be pickier
    }

    // Progress-based modulation: early in stream, be conservative (prefer tight fits);
    // late in stream, prefer closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - frac);

    // Mean residual coupling: if this bin is far below mean residual, it is "ragged";
    // prefer bins near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer division threshold on post_residual: residuals divisible by common item
    // sizes (10..=80 by 10) are reusable; reward them.
    if post_residual >= 10 && post_residual % 10 == 0 {
        score -= 3.0;
    }

    // Slight penalty for opening a new bin when many bins are already open and empty-bin
    // candidate (residual == capacity) competes with tight fits.
    if bin_residual == bin_capacity && post_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Strong tightness reward: cubic in normalized fill quality
    let tightness = 1.0 - post / cap_f;
    score -= 8.0 * tightness * tightness * tightness;

    // Perfect-fill rewards
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 12 {
        score -= 60.0;
    }

    // Dead-space penalty for unusable slivers
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    }

    // Lookahead: reward when next item fits, scaled by resulting slack
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap_f);
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 3.0 * (over / cap_f);
