pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A gap is "dead" if it is smaller than the smallest possible item (1),
    // but practically we penalize gaps that are too small to be useful
    // relative to typical item sizes. Use a hard penalty for tiny residuals.
    if post_residual > 0 {
        // Treat residuals below a threshold as wasted space: quadratic penalty.
        let dead_threshold = 10.0f64; // minimum item size in original spec
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.0;
        } else {
            // Mild reward for leaving a gap that can still fit plausible items
            score -= 1.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Penalize post_residuals that cannot fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 1.5;
    }

    // Reward when this bin is the last chance (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing bins
    // (penalize opening new bins). Applied to the new-bin candidate via
    // bin_residual == bin_capacity check.
    if bin_residual == bin_capacity {
        // New bin candidate: add pressure proportional to open bins count.
        score += open_bins_count as f64 * 2.5;
        // Also penalize if some open bins can already fit the item.
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Existing bin: mild reward proportional to how full the bin already is.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 5.0;
    }

    // Stream progression: later in the stream, be more conservative about
    // opening new bins (consolidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Coupling with mean residual: if mean residual across open bins is high,
    // there is slack available; discourage creating more slack (new bins).
    if bin_residual == bin_capacity && mean_residual > 20.0 {
        score += (mean_residual - 20.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
