    // Encourage filling bins whose residual is close to the current item (fine-grained best fit).
    if post_residual > 0 && post_residual >= item_size {
        let gap = (post_residual - item_size) as f64;
        if gap < 8.0 {
            score -= 6.0 * (1.0 - gap / 8.0);
        }
    }

    // Moderate new-bin opening when stream is nearly done: discourage less.
    let remaining = total_items.saturating_sub(step_index);
    if bin_residual == bin_capacity && remaining < 20 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
