        }
    }

    // Harmonic alignment of leftovers
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 15.0; }
        if post_residual % 20 == 0 { score -= 10.0; }
    }

    // Last-chance bin: avoid opening a new bin on a poor fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Crowding pressure
    if open_bins_count > 8 && post_residual < item_size {
