    // [10..20) marginal, >=20 keeps room for typical small items.
    let cls = post_residual / 10;
    match cls {
        0 => score += 25.0,          // dead space penalty
        1 => score += 8.0,           // marginal
        _ => score -= (cls.min(6) as f64) * 2.0, // reward roomy leftovers
    }

    // Lookahead harmony: if next item fits exactly into post_residual,
    // strongly reward; if next item fits at all, mild reward; if next
