        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.5;
        }
        // modulo harmony between next item and post residual class
        if post_residual > 0 && (next_item_size % 10) == (post_residual % 10) && next_item_size < post_residual {
            score -= 6.0;
        }
        let _ = nxt;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (post_residual very small).
    if fitting_bins_count == 1 {
        score -= 18.0;
        if post_residual < 5 {
            score += 22.0; // near-perfect fit is great, but keep bonus net positive
