    if post_residual < 31 && post_residual > 0 && fitting_bins_count > 3 {
        score += 1.5;
    }

    // Borrowed: new-bin bonus when mean residual is high and next item fits a fresh bin.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size <= bin_capacity && mean_residual > 1.5 * next_item_size as f64 {
            score -= 3.0;
        }
        let remaining = total_items.saturating_sub(step_index);
        if remaining < 20 {
            score -= 15.0;
        }
    }

    score
}

