                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
        }
        // Penalize wasteful slack that next item can't fully use
        let slack = post_residual as i64 - next_item_size as i64;
        if slack > 0 && (slack as u32) < next_item_size && (slack as u32) * 2 > next_item_size {
            score += 1.5;
        }
    }

    // Compare post_residual against mean residual across open bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using the only fitting open bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize fresh bin so tight fits win,
    // but allow opening when open bins are nearly full on average
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Consolidation pressure when many bins are open
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }

    // Late in the stream, tighten packing further
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.4 * progress;

    // Small pressure toward fewer open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept a future item (>=1, but practically < 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Residuals in 10..20 can only fit tiny items; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (small post_residual) non-linearly.
    score -= 40.0 / (1.0 + post_residual as f64);

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    }
    // Penalize if post residual nearly fits next item (tempting dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid
    // opening a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins slightly.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: prefer it only when the item is huge and no
    // good fit exists; otherwise make the fresh bin slightly unattractive.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 40.0;
        }
        // If existing bins are fragmented, a fresh bin is fine.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Progression: early in the stream, keep bins tighter (future
    // capacity matters more); later, allow looser packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits with small slack afterwards: strong reward scaled by tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit here: penalize leaving space the next item can't use
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Tiny dead space (<10, unusable for min-size items) is fine; large leftover is not
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0;
    }

    // Compare against mean residual: placing into a bin with above-average residual
    // reduces fragmentation of small leftovers
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full on average
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 - 30.0 * avg_fullness;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

