pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.11;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space proportionally to its "unusability"
        let dead = post_residual as f64;
        score += (dead / bin_capacity as f64).powi(3) * 50.0;
    }

    // Lookahead: if next item fits in post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.2 * next_item_size as f64;
    }
    // If next item would fit only in residual before placement (i.e., placement kills it), penalize slightly
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 60.0;
        // Late in the stream with many open bins, be more conservative about new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0 + (open_bins_count as f64).ln() * 10.0;
        // If mean residual is large (open bins are roomy), discourage new bin
        score += mean_residual * 0.3;
    } else {
        // Prefer tighter existing bins (best-fit flavor) via residual term already present
        // Reward bins whose residual is close to item size (tight fit)
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.1;
        // Slight preference for bins with residual close to mean (spread usage)
        score -= (bin_residual as f64 - mean_residual).abs() * 0.05;
    }

    // Early stream: encourage consolidation into few bins
    if open_bins_count > 1 && step_index < total_items / 4 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: mild quadratic penalty on leftover; late: stronger cubic/quartic shaping.
    let t = progress;
    let w2 = 0.6 + 1.8 * t;             // quadratic weight grows over time
    let w3 = 0.9 * t * t;               // cubic term only matters late
    let norm = pr / cap;                 // normalized leftover in [0,1)
    score += w2 * norm * norm * cap * 0.5;
    score += w3 * norm * norm * norm * cap;

    // Reward tight fits: subtract a smooth bump when post_residual is small.
    let tightness = 1.0 - norm;          // 1 when perfect fit
    score -= 8.0 * tightness * tightness * tightness * (0.5 + t);

    // Lookahead coupling: penalize leftovers that cannot fit next item,
    // reward leftovers that exactly accommodate it (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx) / cap;
        if gap >= 0.0 {
            // leftover can host next item: reward exact-match via smooth decay
            score -= 6.0 * (-gap * gap * 40.0).exp() * (0.4 + t);
        } else {
            // wasted dead space relative to next item: polynomial penalty
            score += 2.0 * gap * gap * cap * (0.5 + t);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (0.5 + t);
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += 0.3 * (open_bins_count as f64).ln() * (0.5 + t);

    // Anchor to mean residual: prefer bins below mean residual (denser bins).
    score += 0.4 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer fills that leave little usable space.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 9.0 * tightness * tightness * tightness;

    // Finer ramp: penalize gaps too small to be useful for typical items.
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Soft penalty: gaps that likely cannot fit the next item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
    }

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead synergy with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            if post_residual - next_item_size < item_size / 3 {
                score -= 3.0;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
        if post_residual >= next_item_size && post_residual < next_item_size + 6 {
            score -= 2.0;
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Scarce-fit preference.
    if fitting_bins_count <= 2 && post_residual >= item_size {
        score -= 3.5;
    }

    // Consolidation pressure with many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        let rel = item_size as f64 / cap;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        score += 40.0 + pressure * 8.0 + 12.0 * rel * scarcity + 0.015 * remaining;
    } else {
        score -= pressure * 4.0;
    }

    // Prefer bins tighter than the average residual (best-fit style refinement).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Penalize wasteful large leftover space.
    if post_residual > 0 {
        let ratio = post_residual as f64 / cap;
        if ratio > 0.5 {
            score += 2.0 * (ratio - 0.5);
        }
        if mean_residual > 0.0 && (post_residual as f64) > 1.3 * mean_residual {
            score += 1.0;
        }
    }

    // Roomy residual can still hold the item again: mild penalty to avoid sprawl.
    if post_residual >= 2 * item_size {
        score += 1.5;
    }

    // Many open bins: dead residual is costly.
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Last-chance small-fit rescue.
    if post_residual > 0 && post_residual < item_size && fitting_bins_count <= 1 {
        score -= 2.5;
    }

    // --- Combined fine-grained fit + lookahead mutations ---

    // Two-item chain anticipation: bonus when residual exactly fits next two items summed.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next == item_size {
            score -= 14.0;
        } else if after_next > 0 && after_next < item_size {
            score += 3.0;
        }
    }

    // Sharper dead-space penalty scaled by stream progress (late dead space is worse).
    if post_residual > 0 && post_residual < item_size / 4 {
        score += 4.0 + 6.0 * progress;
    }

    // Fine-grained best fit: residual close to current item.
    if post_residual > 0 && post_residual >= item_size {
        let gap = (post_residual - item_size) as f64;
        if gap < 8.0 {
            score -= 6.0 * (1.0 - gap / 8.0);
        }
    }

    // Deeper chain: exact residual match for next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == next_item_size {
            score -= 6.0;
        } else if r2 > 0 && r2 < 10 {
            score -= 2.0 + 0.2 * (10 - r2) as f64;
        }
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 && next_item_size > 20 {
            score -= 4.0 + 0.3 * (6 - gap) as f64;
        }
        let slack = post_residual - next_item_size;
        if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
            score += 1.5;
        }
    }

    // Moderate new-bin opening when stream is nearly done: discourage less.
    let remaining = total_items.saturating_sub(step_index);
    if bin_residual == bin_capacity && remaining < 20 {
        score -= 15.0;
    }

    // Small-residual scarcity penalty with many fitting options.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }

    // New mutation: triple-chain lookahead — reward residuals that can host
    // next item plus current-size item plus a small remainder cleanly.
    if next_item_size > 0 && post_residual >= next_item_size + item_size {
        let tail = post_residual - next_item_size - item_size;
        if tail == 0 {
            score -= 10.0;
        } else if tail <= 4 {
            score -= 5.0;
        }
    }

    // New mutation: avoid fragmenting bins whose residual is a near-exact
    // future fit when several bins already fit the current item.
    if next_item_size > 0 && fitting_bins_count > 2
        && post_residual >= next_item_size
        && (post_residual - next_item_size) < 3 {
        score -= 3.0;
    }

    // New mutation: smooth dead-space penalty scaled by mean residual context —
    // residuals well below average are precious, keep them for small items.
    if post_residual > 0 && mean_residual > 0.0
        && (post_residual as f64) < 0.6 * mean_residual
        && post_residual < 40 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "useful" is the leftover space?
    // Residuals that are multiples of common item sizes (or leave room for
    // typical sizes) are more valuable. Penalize dead space in awkward bands.
    let post = post_residual;

    // Perfect fit: strongly reward.
    if post == 0 {
        score -= 200.0;
    }

    // Harmonic classes via integer division on post_residual:
    // class 0: post == 0 (perfect), class 1: 1..=10 (near-dead),
    // class 2: 11..=25 (small-item territory), class 3: 26..=50 (mid),
    // class 4: 51..=100 (large, still flexible).
    let class = match post {
        0 => 0,
        1..=10 => 1,
        11..=25 => 2,
        26..=50 => 3,
        _ => 4,
    };
    // Reward larger classes (more usable leftover) with a bonus subtracted.
    let class_bonus = [0.0, -5.0, -15.0, -30.0, -45.0];
    score += class_bonus[class];

    // Modulo arithmetic: leftover divisible by 10 (common size quantum) is
    // more likely reusable — subtract a bonus proportional to alignment.
    if post % 10 == 0 && post > 0 {
        score -= 20.0;
    } else if post % 5 == 0 && post > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin is extremely valuable — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 120.0;
        } else if next_item_size < post {
            // Next item fits: leftover after next placement, penalize small
            // awkward remainders.
            let post2 = post - next_item_size;
            if post2 == 0 {
                score -= 90.0;
            } else if post2 <= 10 {
                score += 5.0;
            } else {
                score -= 25.0;
            }
        } else {
            // Next item does NOT fit here: penalize bins whose residual is
            // just barely too small (wasted capacity trap).
            let gap = next_item_size - post;
            if gap <= 10 {
                score += 30.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or no good fits exist; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let fill_fraction = item_size as f64 / cap;
        // Opening a new bin wastes (100 - item) immediately; the larger the
        // item, the less waste, so reward large items in a fresh bin.
        score += 60.0 * (1.0 - fill_fraction);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If many bins are open, discourage yet another one.
        score += 4.0 * open_bins_count as f64;
        // If item exactly fills a fresh bin (item == 100), it's ideal.
        if item_size == bin_capacity {
            score -= 150.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor) via mean
    // residual coupling: placing into a bin tighter than average is good.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Fractional thresholds on post_residual: penalize residuals in the
    // "dead zone" (1..=9) where almost nothing fits.
    if post >= 1 && post <= 9 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that cannot fit the smallest plausible item range.
    if post_residual > 0 && post_residual < item_size.max(next_item_size) {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize blocking the next item.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (1.0 - t);

    // Prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: keep it neutral-to-slightly-high so only truly bad fits open new bins.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
