pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (minimal dead space).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 5 {
        score -= 300.0;
    } else if post_residual < 10 {
        score -= 150.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches the post residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 400.0; // perfect chaining: this bin will be closed by the next item
        } else if diff <= 5.0 {
            score -= 200.0;
        } else if diff <= 10.0 {
            score -= 100.0;
        } else {
            // penalize leaving gaps the next item cannot use
            score += diff * 0.5;
        }
        // If next item can still fit into the remaining space, mild bonus
        if next_item_size <= post_residual {
            score -= 20.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins),
    // penalize placing into bins that are already loose.
    let resid_f = post_residual as f64;
    if resid_f > mean_residual {
        score += (resid_f - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - resid_f) * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the item
    // fits poorly everywhere (large post_residual relative to capacity is
    // naturally penalized above; add a modest penalty for opening new bins
    // when plenty of open bins exist).
    if bin_residual == bin_capacity {
        score += 60.0 + (open_bins_count as f64) * 2.0;
        // but if it's early in the stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
    }

    // Slight preference to fill larger residual bins when many bins are open
    // (consolidation pressure).
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

