    // prefer filling existing bins harder; if low, be pickier
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score -= 0.3 * mr;
    score += 0.15 * (post_residual as f64 - mr).abs();

    // Time horizon: early in the stream, be conservative (favor new bins
    // for poor fits since long stream remains); late, squeeze into open bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if new_bin {
        // Opening a new bin is cheap early, expensive late
        let openness = 1.0 - progress;
        score -= 10.0 * openness;
        // Penalize opening new bin if a decent fit exists elsewhere
        if post_residual as u32 > bin_capacity - item_size {
            // always true for new bin; rely on progress term
        }
        // If many open bins with large residuals, discourage new bin
        score += 0.2 * open_bins_count as f64;
    } else {
        // Existing bin: late stream rewards consolidation
        score -= 10.0 * progress;
    }

    // Non-linear residual shaping: quadratic penalty on medium-size leftovers
    let pr = post_residual as f64;
    score += 0.02 * pr * pr * 0.1;

    // Discourage bins that would be left with tiny unusable slivers (1..9)
    if post_residual >= 1 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
