pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, with smooth non-linear shaping over progress
    let mut score = pr;

    // Non-linear polynomial coupling: weight of residual waste grows as stream progresses
    let waste_coupling = pr_norm * pr_norm * (0.5 + 1.5 * progress);
    score += 40.0 * waste_coupling;

    // Perfect fit reward, stronger later in the stream (smooth polynomial in progress)
    let perfect = (pr_norm - 0.02).abs().min(1.0);
    score -= 25.0 * (1.0 - perfect) * (1.0 + progress);

    // Tight fit bonus: quadratic in post-residual smallness
    score -= 15.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * item_size as f64 / cap;

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Penalize leaving residual close to but not zero relative to future item (lookahead)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.4 * gap * (1.0 - progress);
        if pr >= nx {
            score -= 10.0 * (1.0 - gap / cap.max(1.0));
        }
    } else {
        // Last item: minimize waste entirely
        score += pr * 0.5;
    }

    // Mean residual context: bins far from mean get smooth penalty (fragmentation)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (0.5 + progress);

    // Prefer filling bins when many bins are open (consolidation pressure)
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.0 * open_pressure * pr_norm;

    // New-bin candidate: mild penalty so we prefer reusing unless fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * progress - 0.1 * item_size as f64;
    }

    score
}

