pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fractions (1/8 classes)
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    let class = (frac * 8.0).floor(); // 0..7 harmonic class

    // Reward residuals that fall into "usable" classes (small residuals are tight fits)
    let tight_bonus = match class {
        0.0 => 14.0,
        1.0 => 10.0,
        2.0 => 6.0,
        3.0 => 3.0,
        4.0 => 0.0,
        5.0 => -2.0,
        6.0 => -4.0,
        _ => -6.0,
    };
    score -= tight_bonus;

    // Integer-division threshold: post_residual divisible by common item sizes
    // (10/20/25/50 style granularity) => residual reusable by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 5.0; }
        else if post_residual % 5 == 0 { score -= 2.5; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item cannot use residual: penalize proportionally to waste
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless residuals
    // across open bins are large (i.e., current bins are crowded).
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap) - 0.5; // positive when bins are loose
        score += 10.0 - 12.0 * crowding.max(0.0) - (open_bins_count as f64).min(10.0) * 0.5;
        if next_item_size > 0 && next_item_size <= item_size {
            score += 2.0;
        }
    }

    // Mild phase drift: later in stream, prefer tighter packing (favor small residuals).
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * phase * (frac - 0.3);

    // Slight pull toward mean residual to keep bin residuals homogeneous.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score += 180.0 + 6.0 * (10 - post_residual) as f64;
    } else if post_residual <= 25 {
        score += 60.0 + 1.5 * (25 - post_residual) as f64;
    } else if post_residual >= 50 {
        score -= 45.0;
    }

    // Fill ratio bonus.
    let fill = (item_size as f64) / cap;
    score -= 60.0 * fill;

    // Consolidation pressure, softened as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Lookahead: exact match next step is gold.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 20.0;
            } else if r2 > 0 && r2 < 10 {
                // second-fit chain: near-perfect remainder for next-next step
                score -= 2.0 + 0.25 * (10 - r2) as f64;
            }
            // small gap after a large item: keep tight chains alive
            let gap = r2;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            // awkward half-slack: gap too small to reuse well
            if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 6.0 * (over / cap);
        }
    }

    // Mean-residual balance: avoid hoarding space far above the mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.4 * diff.abs();

    // Don't burn a big bin on a tiny item unless few bins are open anyway.
    if item_size <= 20 && bin_residual >= 80 && open_bins_count > 4 {
        score += 45.0;
    }

    // Late-stream tightness.
    if open_bins_count > 8 && post_residual > 0 && post_residual < item_size {
        score += 3.0;
    }

    // Tiny dead gap with many fitting options: mild extra penalty.
    if post_residual < 31 && fitting_bins_count > 3 && post_residual > 0 {
        score += 1.5;
    }

    // New-bin arbitration.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if progress < 0.15 {
            score -= 10.0;
        }
        // fresh bin attractive only if it can host the next item too
        if next_item_size > 0 && next_item_size <= bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use
    // are pure waste; tiny gaps are the worst. Penalize non-linearly.
    if post_residual > 0 && post_residual <= 9 {
        // unusable sliver: heavy penalty, sharper for smaller gaps
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 20 {
        // risky mid-range gap: moderate penalty
        score += 12.0;
    }

    // Reward tight fits (small post_residual is good, already base score,
    // but add extra quadratic reward for near-perfect packing).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // but allow it when the bin landscape is fragmented (high mean residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate: make it attractive only when the item fits badly
    // everywhere else. An empty bin has post_residual == capacity - item_size,
    // which is large; offset its base cost when fragmentation is high.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 + 0.5 * fragmentation;
        // If next item is small, a fresh bin keeps flexibility.
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity as f64) * 0.25 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item exactly fills this bin's post_residual,
    // strongly prefer this bin (perfect two-item pairing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // next item still fits here: mild reward proportional to fit quality
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next <= 9 {
            score -= 20.0; // creates a perfect finish
        } else {
            score -= 5.0;
        }
    }

    // Slight preference for bins below mean residual (consolidating emptier bins
    // keeps large residuals available for large future items).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: next item exactly fills the new residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into post_residual: chain placement is possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
    }
    // Next item cannot fit here: penalize, especially small dead space left behind.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
        // Very small unusable residue is dead space.
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Reward tight fits of the current item (small post_residual generally good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Compare against mean residual: prefer bins that become below-average residual
    // (i.e., we're filling an under-filled bin well).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    // or this is a large item that would leave bad residue elsewhere.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (100.0 - mean_residual).max(0.0) / 100.0;
        score += 20.0 - crowded * 2.0;
        if item_size > 70 {
            score -= 10.0;
        }
    }

    // Late in the stream, consolidate: discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
