        }
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 && next_item_size > 20 {
            score -= 4.0 + 0.3 * (6 - gap) as f64;
        }
        let slack = post_residual - next_item_size;
        if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
            score += 1.5;
        }
    }

    // Moderate new-bin opening when stream is nearly done: discourage less.
    let remaining = total_items.saturating_sub(step_index);
    if bin_residual == bin_capacity && remaining < 20 {
        score -= 15.0;
    }

    // Small-residual scarcity penalty with many fitting options (avoid fragmenting good bins).
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }

    // New mutation: strong exact-fit bonus for the current item (best-fit sharpening).
    if post_residual == 0 && item_size == bin_residual {
        score -= 20.0;
    }

    // New mutation: lookahead exact pair — residual equals next + current.
    if next_item_size > 0 && post_residual == next_item_size + item_size {
        score -= 10.0;
    }

    // New mutation: avoid leaving residuals just below common item sizes; nudge toward
    // residuals that can still host the next item cleanly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < 8.0 {
            score += 3.0 * (1.0 - deficit / 8.0);
        }
    }

    // New mutation: with few open bins early, prefer conserving tight bins for large items.
    if open_bins_count <= 3 && post_residual > 0 && post_residual < 15 && next_item_size > 25 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else {
        // Fractional waste penalty, amplified for small residuals (near-perfect fits).
        let fit_ratio = post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * (1.0 - fit_ratio * fit_ratio);
    }

    // Penalize residual gaps that no plausible future item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // dead space
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 40.0;
        } else {
            // Next item won't fit here: mild penalty proportional to overflow.
            let overflow = next_item_size as f64 - post_residual as f64;
            score += 0.3 * overflow.min(100.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make opening a new bin costly unless the item is large relative to
    // capacity or open bins are already crowded (high mean_residual).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let crowd = mean_residual / bin_capacity as f64;
        // Cost decreases when item is big or existing bins are tight.
        let new_bin_cost = 60.0 - 40.0 * item_frac - 50.0 * crowd;
        score += new_bin_cost.max(-20.0).min(120.0);
    }

    // Time horizon: early in the stream, be conservative (avoid fragmentation);
    // later, tolerate waste since fewer items remain to fill gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins with slack: discourage spreading, favor consolidation.
    if open_bins_count > 3 {
        let slack = mean_residual - post_residual as f64;
        score += 0.05 * (open_bins_count as f64) * (slack.max(0.0) / bin_capacity as f64) * 10.0;
    }

    score
}

