pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 and integer-division thresholds.
    let post = post_residual;
    let class = post % 10;
    let tier = post / 10; // 0..=10

    // Reward tight fits: lower post_residual is better, but small nonzero leftovers
    // that form "dead classes" are extra penalized.
    // Dead-space classes: residuals 1..=9 are hard to fill; class 0 is perfect.
    if post == 0 {
        score -= 50.0; // perfect closure
    } else if class > 0 && class <= 5 {
        // small awkward remainder: penalize proportionally to awkwardness
        score += (6 - class) as f64 * 3.0;
    } else if class > 5 {
        // larger remainder may still host a small future item
        score -= class as f64 * 0.5;
    }

    // Tier coupling: big tiers mean lots of leftover space -> the bin is "wasteful" to use
    // unless the item is large. Favor using bins with moderate leftover for large items.
    let size_frac = item_size as f64 / bin_capacity as f64;
    score += (tier as f64).powi(2) * 0.8 * (1.0 - size_frac);

    // Lookahead coupling: if next item can exactly fill this bin's post-residual,
    // strongly reward leaving that residue.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post {
            let new_res = post - next_item_size;
            // reward if the pair leaves a harmonic class-0 or near-0 residue
            if new_res % 10 == 0 {
                score -= 25.0;
            } else if new_res < 10 {
                score -= 8.0;
            } else {
                score -= (new_res as f64) * 0.15;
            }
        } else {
            // next item cannot fit in the leftover: the residue becomes dead
            score += (post as f64) * 0.35;
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // attractive only when the item is large or no good fit exists.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 12.0;
        // large items deserve fresh bins (avoid fragmenting open bins)
        if item_size > bin_capacity / 2 {
            score -= 18.0;
        }
        // early in the stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Global pressure: many open bins with high mean residual -> encourage closing gaps
    // (use existing bins) rather than spreading.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        score += pressure * (open_bins_count as f64).ln() * 2.0;
    }

    // Exact-fill of current residual (item consumes everything) is always great.
    if item_size == bin_residual {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste — penalize them quadratically.
    let dead_threshold = 12u32;
    if post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0
               + (dead_threshold - post_residual) as f64 * (dead_threshold - post_residual) as f64 * 4.0;
    }

    // Reward near-perfect fits (very small usable leftovers too).
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 7.0;
    }

    // Coupling with mean residual: placing into a bin whose residual is far
    // below the mean concentrates waste elsewhere; prefer bins tighter than mean.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= residual_gap * 0.6;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids inflating open_bins_count).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading to bins with
    // large residuals; slight bias toward tight bins.
    score += open_bins_count as f64 * 0.15 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
        if post_residual - next_item_size <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; if post-residual is unusable, penalize.
        if post_residual < dead_threshold {
            score += 5.0;
        }
    }

    // New-bin candidate: opening a fresh bin is attractive when the item is
    // large (poor fit candidates elsewhere) or many bins are open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_pressure = item_size as f64 / bin_capacity as f64;
        score = 40.0 + item_pressure * 60.0 - progress * 10.0;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no alternatives: opening is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0; // room for lookahead item in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: unusable slivers are pure waste; penalize non-linearly.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Reward tight fits (quadratic near-perfect packing bonus).
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage new bins when many are open, scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate handling: offset base cost only when fragmentation is high.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 + 0.5 * fragmentation;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.25 {
            score -= 15.0;
        }
        // Fresh bin with large residual is valuable when mean residual is small.
        if post_residual as f64 > mean_residual * 1.5 && next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Lookahead: perfect two-item pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            // Two-step lookahead: residual after next item pairs with item itself.
            if gap == next_item_size as u32 {
                score -= 3.0;
            } else if gap > 0 && gap < 10 {
                score -= 2.0 + 0.2 * (10 - gap) as f64;
            }
            // Half-slack trap: leftover barely too small to reuse.
            if slack > 0.0 && slack < next_item_size as f64 && slack * 2.0 > next_item_size as f64 {
                score += 1.5;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Prefer bins below mean residual (keep large residuals for large items).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Crowding: when many bins fit, slightly penalize tight post-residuals to
    // avoid hoarding near-perfect bins needed for exact pairings.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: keep it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score = 60.0 - 40.0 * pressure - 0.5 * mean_gap;
