        if next_item_size > 0 && bin_capacity as f64 - next_item_size as f64 >= 0.0 {
            score -= 5.0;
        }
        return score;
    }

    // Perfect lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Near match: small gap between post_residual and next item.
    else if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (-gap / 15.0).exp();
    }

    // Penalize dead space that likely can't be reused (small residuals).
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (good fits first).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Mild late-stream consolidation: fewer open bins is better late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.05 * open_bins_count as f64;

    score
}

