        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes potential unless
    // open bins have poor fits or are already crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, reduced late in the stream
        // (fewer future items to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - 0.5 * progress);

        // If the mean residual across open bins is small, open bins are
        // nearly full and a new bin is more acceptable.
        score -= (mean_residual / bin_capacity as f64) * 10.0;

        // If many bins can already fit this item, no need for a new one.
        if fitting_bins_count > 1 {
            score += 12.0;
        }
    } else {
        // Prefer filling bins with larger residuals when many bins are open
        // (consolidation), but mildly: avoid fragmenting many half-empty bins.
        score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.15;

