pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact match: massive bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Penalize small dead space that nothing (min size 1..10) can use later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins tighter than the mean residual (fill full bins first)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - fill_ratio);
    }

    // Mild preference for high occupancy
    score -= 0.3 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score += 180.0 + 6.0 * (10 - post_residual) as f64;
    } else if post_residual <= 25 {
        score += 60.0 + 1.5 * (25 - post_residual) as f64;
    } else if post_residual >= 50 {
        score -= 45.0;
    }

    // Small-residual penalty (borrowed from best): discourage leaving tiny dead gaps.
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Fill ratio bonus.
    let fill = (item_size as f64) / cap;
    score -= 60.0 * fill;

    // Consolidation pressure, softened as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Lookahead: exact match next step is gold.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 20.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.25 * (10 - r2) as f64;
            }
            let gap = r2;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 6.0 * (over / cap);
        }
    }

    // Mean-residual balance: avoid hoarding space far above the mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.4 * diff.abs();

    // Don't burn a big bin on a tiny item unless few bins are open anyway.
    if item_size <= 20 && bin_residual >= 80 && open_bins_count > 4 {
        score += 45.0;
    }

    // Late-stream tightness.
    if open_bins_count > 8 && post_residual > 0 && post_residual < item_size {
        score += 3.0;
    }

    // Tiny dead gap with many fitting options: mild extra penalty.
    if post_residual < 31 && fitting_bins_count > 3 && post_residual > 0 {
        score += 1.5;
    }

    // New-bin arbitration.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if progress < 0.15 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
            score -= 3.0;
        }
    }

    // Dead-space ratio control: penalize bins whose post-fit residual is a
    // large fraction of capacity (wasted space) relative to open-bin count.
    if post_residual > 0 && open_bins_count > 2 {
        let waste_ratio = post_residual as f64 / cap;
        if waste_ratio > 0.5 {
            score -= 4.0 * (waste_ratio - 0.5) * (1.0 - progress);
        }
    }

    // Two-step lookahead: if next item exactly fills post_residual, strongly prefer.
    if next_item_size > 0 && post_residual >= next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == 0 {
            score -= 30.0;
        } else if r2 <= 4 {
            score -= 6.0 + (4 - r2) as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: penalize if next item cannot use the post residual well.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            score -= 8.0 * (nx / (post_residual as f64 + 1.0));
        } else {
            // dead space risk: post residual too small for next item
            score += 6.0 * ((nx - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > (bin_capacity as f64) * 0.5;
        let crowding = open_bins_count as f64 / (mean_residual + 1.0);
        if poor_fit && fitting_bins_count > 0 {
            score -= 5.0; // allow new bin only when fit would be very poor
        } else {
            score += 15.0 + 2.0 * crowding.min(10.0);
        }
    }

    // Global state: many open bins with large mean residual -> prefer consolidation.
    if bin_residual as f64 > mean_residual {
        score += 0.5 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 0.5 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Time horizon: early stream favors balance; late stream favors just fitting anywhere tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0 * tightness;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream we tolerate larger post_residuals; late we penalize them harder.
    let progress_weight = 1.0 + 3.0 * progress * progress;
    score += 20.0 * norm_post * norm_post * progress_weight;

    // Reward tight fits (small post residual) with a non-linear bonus.
    score -= 15.0 * (1.0 - norm_post) * (1.0 - norm_post) * norm_item;

    // Penalize dead space that cannot fit the next item (smooth quadratic gap penalty).
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size as f64 - post) / cap;
        score += 25.0 * gap * gap;
    } else if next_item_size > 0 {
        // Reward bins whose leftover still accommodates the lookahead item.
        score -= 8.0 * (post - next_item_size as f64) / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Compare against mean residual: bins far below mean residual are "wasted" space.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // fits poorly everywhere; smooth penalty decaying with item size.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = (1.0 - norm_item).powi(2);
        score += 12.0 + 40.0 * poor_fit_penalty * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64 * norm_post;

    score
}

