pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: residues divisible by small divisors
    // leave room for common small items (e.g. 10, 20, 25, 50).
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    for &d in &[50u32, 25, 20, 10, 5] {
        if pr % d == 0 && pr > 0 {
            harmonic_bonus = (bin_capacity as f64) / (d as f64);
            break;
        }
    }
    score -= harmonic_bonus;

    // Penalize awkward dead space: residues not matching any common item size
    if pr > 0 && pr < 10 {
        score += 60.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 400.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // next fits, but check double-fit (two more items)
        let rem2 = pr - next_item_size;
        if item_size <= rem2 || (next_item_size > 0 && rem2 >= 10) {
            score -= 80.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // placing here strands the next item's preferred bin class
        score += 40.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so that
    // reasonable fits into open bins win, but bad fits open new bins.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
        // early stream: prefer opening bins to build flexibility
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 50.0 * (1.0 - progress);
    }

    // Prefer tighter bins overall: compare residual to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    } else {
        score += 10.0;
    }

    // Large item relative to residual: reward filling big chunks
    score -= (item_size as f64) * 0.3;

    score
}

