 // and reward bins whose post-residual stays harvestable given stream position.
 if next_item_size > 0 && post_residual >= next_item_size { let leftover = post_residual - next_item_size ; if leftover > 0 && leftover < next_item_size && (leftover as f64) < mean_residual * 0.5 { score += 2.0 ; } } if post_residual > 0 && post_residual < 8 && step_index + 1 < total_items { score -= 1.5 ; } // NEW: in crowded states, mildly prefer tighter fits over lookahead bonuses.
