pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any small unusable gap (0 < post_residual < 10)
    // is heavily penalized; exact fit (0) is strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score += 60.0;
    } else {
        // Mild reward for leaving gaps that could still fit small items (>=10)
        score -= 5.0;
    }

    // If the lookahead item can use the post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post_residual is nonzero but too small for the next item, penalize.
    if post_residual > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // Open-bin pressure: prefer spreading across fewer bins when few are open,
    // but encourage opening a new bin when many are already open and fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Last-chance bin (only one fitting bin) gets a strong bonus to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates from mean
    // (tighter-than-average bins are better fill candidates).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // New-bin candidate: keep it neutral-to-slightly-high so it only wins
    // when open bins have truly bad fits.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of next item into post residual is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: this bin becomes exactly full after next item
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportionally to how well next item fills the remainder
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leftover dead space more strongly
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: prefer minimal waste
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average when item fits well.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // if next item is small, a fresh bin keeps flexibility
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Early in stream: slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Fill ratio bonus.
    let fill = (item_size as f64) / cap;
    score -= 40.0 * fill;

    // Consolidation pressure, softened as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Lookahead: exact match next step is gold.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 38.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 3.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.2 * (10 - r2) as f64;
            }
            let gap = r2;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Mean-residual balance: avoid hoarding space far above the mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.25 * diff.abs();

    // Don't burn a big bin on a tiny item unless few bins are open anyway.
    if item_size <= 20 && bin_residual >= 80 && open_bins_count > 4 {
        score += 45.0;
    }

    // Late-stream tightness.
    if open_bins_count > 8 && post_residual > 0 && post_residual < item_size {
        score += 2.5;
    }

    // Tiny dead gap with many fitting options: mild extra penalty.
    if post_residual < 31 && fitting_bins_count > 3 && post_residual > 0 {
        score += 1.5;
    }

    // New-bin arbitration.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if progress < 0.15 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 40.0;

    // Penalize dead space: residuals too small for the minimum item (1) are fine,
    // but residuals that are small-but-not-tiny are wasted capacity.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * waste * 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64 / post_residual as f64) * 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual too small for next item: mild penalty for stranding space.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more selective (favor tight fits),
    // later, prioritize closing out bins to avoid proliferation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Global state: if many bins are open, discourage opening new ones
    // (new empty bin has bin_residual == bin_capacity; its post_residual is large,
    // so add a penalty scaled by open bins to keep it from winning cheaply).
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.0;
        // But allow new bin when item is large relative to mean residual space.
        if item_size as f64 > mean_residual.max(0.0) {
            score -= 12.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below mean
    // (draining fuller bins first keeps the bin set compact).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = post * (1.0 + 0.8 * progress * norm_post * norm_post);

    // Smooth penalty for residual that is small but hard to fill later.
    let dead = (norm_post - 0.5) * (norm_post - 0.5) * 12.0 * (1.0 - progress);

    // Reward near-perfect fills via smooth quadratic discount.
    let perfect = (norm_post * norm_post) * 18.0;

    // Last-chance bonus when few bins fit.
    let scarcity = if fitting_bins_count <= 1 { -8.0 } else { 0.0 };

    // Lookahead coupling: smooth reward if next item likely fits post-residual.
    let lookahead = if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        let fit = if gap >= 0.0 { gap / cap } else { (gap / cap) * 6.0 };
        -fit * 5.0 * (1.0 + progress)
    } else { 0.0 };

    // Mild spread penalty relative to mean residual.
    let spread = (post - mean_residual) / cap;
    let spread_term = spread * spread * 4.0;

    // Slight nudge toward new bins early vs late.
    let new_bin_bias = if bin_residual == bin_capacity {
        6.0 * (1.0 - progress) + open_bins_count as f64 * 0.3
    } else { 0.0 };

    base + dead + perfect + scarcity + lookahead + spread_term + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fraction buckets
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize post_residuals in "dead zones" that few item sizes can fill.
    // Classes via integer division thresholds (harmonic fifths of capacity).
    let class = post_residual / (bin_capacity / 5); // 0..=5 harmonic class
    match class {
        0 => score -= 40.0,                       // near-perfect fit
        1 => score -= 10.0,                       // small gap, usually fillable
        2 => score += 5.0,                        // mid gap: awkward zone
        3 => score += 0.0,
        _ => score -= 5.0,                        // large residual still useful
    }

    // Modulo arithmetic: gaps that are multiples of common size classes (10s)
    // are more likely to be exactly filled later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Gaps divisible by 5 are moderately friendly.
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: penalize large wasted gaps
            score += 0.05 * pr;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base preference for existing bins: make new bin moderately expensive.
        score = cap * 0.75 - 0.5 * (mean_residual - pr).abs();
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 20.0; // big next item: fresh bin is attractive
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open
        }
    }

    // Mean residual coupling: if this bin's post residual is far below mean,
    // we are compacting well; reward it.
    score -= 0.3 * (mean_residual - pr).max(0.0);

    // Mild stream-progression term: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
