pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit gets a strong reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits: fraction of bin used
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Open bins pressure: prefer filling existing bins when many are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate: penalize mildly, but relax when item is large and fits poorly elsewhere
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size > bin_capacity / 2 && fitting_bins_count > 1 {
            score -= 5.0;
        }
    }

    // Last chance: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize leaving medium gaps
            if post_residual >= 13 && post_residual < next_item_size {
                score += 5.0;
            }
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead reward: next item still fits in the leftover space
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (post_residual - next_item_size) as f64 * -0.1;
        // penalize excess slack beyond what next item needs
        score += (post_residual - next_item_size) as f64 * 0.25;
    }
    // Next item will NOT fit in this bin's leftover: penalize dead space
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
        // extra penalty if leftover is tiny and unusable
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Reward tight fits relative to bin residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 8.0;

    // Compare post_residual against mean residual across open bins:
    // leaving more than average slack is wasteful
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // but if the item is large and would leave little slack, opening fresh is fine
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 20.0;
        }
        // if current bin would be a perfect lookahead match, discourage new bin
        if next_item_size > 0 && post_residual == next_item_size {
            score += 40.0;
        }
        // if this bin would be a last chance, discourage new bin
        if fitting_bins_count == 1 {
            score += 35.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer fills that leave little usable space.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 9.0 * tightness * tightness * tightness;

    // Finer ramp: penalize gaps too small to be useful for typical items.
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Soft penalty: gaps that likely cannot fit the next item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < 8.0 {
            score += 3.0 * (1.0 - deficit / 8.0);
        }
    }

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 150.0;
        if item_size == bin_residual {
            score -= 20.0;
        }
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead synergy with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            if post_residual - next_item_size < item_size / 3 {
                score -= 3.0;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
        if post_residual >= next_item_size && post_residual < next_item_size + 6 {
            score -= 2.0;
        }
        // Deeper chain: exact residual match for next item twice.
        let r2 = post_residual - next_item_size;
        if r2 == next_item_size {
            score -= 6.0;
        } else if r2 > 0 && r2 < 10 {
            score -= 2.0 + 0.2 * (10 - r2) as f64;
        }
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 && next_item_size > 20 {
            score -= 4.0 + 0.3 * (6 - gap) as f64;
        }
        if gap > 0 && gap < next_item_size && gap * 2 > next_item_size {
            score += 1.5;
        }
        // Exact pair: residual equals next + current.
        if post_residual == next_item_size + item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Scarce-fit preference.
    if fitting_bins_count <= 2 && post_residual >= item_size {
        score -= 3.5;
    }

    // Consolidation pressure with many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        let rel = item_size as f64 / cap;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        score += 40.0 + pressure * 8.0 + 12.0 * rel * scarcity + 0.015 * remaining;
        if remaining < 20.0 {
            score -= 15.0;
        }
    } else {
        score -= pressure * 4.0;
    }

    // Prefer bins tighter than the average residual (best-fit style refinement).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Penalize wasteful large leftover space.
    if post_residual > 0 {
        let ratio = post_residual as f64 / cap;
        if ratio > 0.5 {
            score += 2.0 * (ratio - 0.5);
        }
        if mean_residual > 0.0 && (post_residual as f64) > 1.3 * mean_residual {
            score += 1.0;
        }
    }

    // Roomy residual can still hold the item again: mild penalty to avoid sprawl.
    if post_residual >= 2 * item_size {
        score += 1.5;
    }

    // Many open bins: dead residual is costly.
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Last-chance small-fit rescue.
    if post_residual > 0 && post_residual < item_size && fitting_bins_count <= 1 {
        score -= 2.5;
    }

    // Fine-grained best fit: residual close to current item.
    if post_residual > 0 && post_residual >= item_size {
        let gap = (post_residual - item_size) as f64;
        if gap < 8.0 {
            score -= 6.0 * (1.0 - gap / 8.0);
        }
    }

    // Sharper dead-space penalty scaled by stream progress.
    if post_residual > 0 && post_residual < item_size / 4 {
        score += 4.0 + 6.0 * progress;
    }

    // Small-residual scarcity penalty with many fitting options.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }

    // New mutation: with few open bins early, conserve tight bins for large upcoming items.
    if open_bins_count <= 3 && post_residual > 0 && post_residual < 15 && next_item_size > 25 {
        score += 4.0;
    }

    // New mutation: scale the near-perfect-fit bonus by remaining stream length —
    // early tight fills preserve long-run capacity, late ones matter less.
    let remaining = total_items.saturating_sub(step_index) as f64;
    if post_residual > 0 && post_residual <= 3 && remaining > 50.0 {
        score -= 8.0 * (1.0 - (remaining / (total_items.max(1) as f64)).min(1.0)) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: penalize large post-residual quadratically.
    score += 0.05 * (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: if the next item can use the post-residual exactly, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits after placement: mild reward proportional to wasted gap.
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's residual: penalize dead space creation.
            score += 6.0 + 0.1 * (nxt - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidation (tighter fits).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Early in the stream, be more willing to open new bins for big items;
    // late in the stream, favor filling existing bins aggressively.
    score -= 15.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean.
    let res_f = bin_residual as f64;
    score += 0.3 * (res_f - mean_residual);

    // New-bin candidate: only attractive when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 60.0 - 40.0 * large_item * (1.0 - progress);
        if fitting_bins_count > 2 {
            score += 25.0; // plenty of alternatives; new bin is wasteful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (favor exploring); late, waste is costly.
    let progress_coupling = 1.0 + 1.5 * progress * progress + 0.5 * (1.0 - progress);
    score *= progress_coupling;

    // Dead-space quadratic penalty: residuals too small to fit the smallest
    // plausible items become unusable; penalize quadratically.
    let dead = ((40.0 - post) / 40.0).max(0.0);
    score += 25.0 * dead * dead * (0.5 + progress);

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * (0.6 + 0.4 * progress);
        // Perfect chaining bonus (smooth, not piecewise).
        let fit_quality = 1.0 - (gap / cap).min(1.0);
        score -= 15.0 * fit_quality * fit_quality;
    }

    // Last-chance bin: strongly reward using it (avoid opening a new bin).
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate: only attractive when it can absorb future mass,
    // i.e., when existing open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (mean_residual / cap).min(1.0);
        score = 20.0 + 60.0 * (1.0 - crowded) * (1.0 - progress) - 25.0 * crowded * progress;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0;
        }
    }

    // Mild regularization against bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals that are "harmonic"
    // with common item sizes (i.e. divisible-friendly leftovers).
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit is ideal
    } else if pr <= 10 {
        12.0 // dead space below min item size: unusable
    } else if pr % 10 == 0 {
        -8.0 // residual aligned to decade grid, easy to fill later
    } else if pr % 5 == 0 {
        -4.0
    } else {
        3.0 + ((pr % 5) as f64) // odd residuals are harder to fill
    };
    score += harmonic_bonus;

    // Integer-division threshold on post_residual: large leftovers are good
    // (bin stays useful), tiny leftovers are bad.
    let bucket = pr / 25; // 0..4 harmonic quartile of remaining space
    score -= bucket as f64 * 6.0;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if next item is bigger than post residual but small,
    // penalize creating a near-unusable gap.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - pr).min(40) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // existing residuals are badly fragmented relative to the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - item_size as f64).abs();
        score = 20.0 + progress * 25.0 + fragmentation * 0.4;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

