        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Penalize residual that cannot fit the lookahead item (wasted capacity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size as f64 {
        // Reward bins that can still host the next item after this placement.
        score -= 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and remaining stream.
        score += 30.0 + 4.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (tighter packing targets).
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
