        score += 10.0;
    }

    // Penalize residuals that are too small to be useful for typical items (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: this is the only fitting bin; avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the mean residual (consolidate space)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Mild penalty for opening a new bin when few items remain
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
