    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // New-bin candidate logic: penalize opening a new bin unless current
    // residuals are all poor (mean residual small) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_open_bins = if mean_residual < item_size as f64 { 1.0 } else { 0.0 };
        let penalty = 30.0 + 40.0 * progress - 25.0 * poor_open_bins
            + (open_bins_count as f64) * 1.5;
        // Reward new bin if it would create a good future split for next item
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0;
        }
        score += penalty;
    } else {
        // Prefer fuller bins (small residual before placement) mildly.
        score += (bin_residual as f64) * 0.15;
    }

    // Global balance: discourage fragmenting many bins when mean residual is high.
    score -= 0.05 * mean_residual;

    // Time horizon: late in stream, be more conservative (favor existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
