pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score += 180.0 + 6.0 * (10 - post_residual) as f64;
    } else if post_residual <= 25 {
        score += 60.0 + 1.5 * (25 - post_residual) as f64;
    } else if post_residual >= 50 {
        score -= 45.0;
    }

    // Fine-grained dead-space penalty for small residuals (borrowed from best).
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Fill ratio bonus.
    let fill = (item_size as f64) / cap;
    score -= 60.0 * fill;

    // Consolidation pressure, softened as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Lookahead: exact match next step is gold (calibrated softer).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 450.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 18.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.25 * (10 - r2) as f64;
            }
            let gap = r2;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / cap);
        }
    }

    // Mean-residual balance.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.4 * diff.abs();

    // Don't burn a big bin on a tiny item unless few bins are open anyway.
    if item_size <= 20 && bin_residual >= 80 && open_bins_count > 4 {
        score += 45.0;
    }

    // Late-stream tightness.
    if open_bins_count > 8 && post_residual > 0 && post_residual < item_size {
        score += 2.5;
    }

    // Tiny dead gap with many fitting options: mild extra penalty.
    if post_residual < 31 && fitting_bins_count > 3 && post_residual > 0 {
        score += 1.5;
    }

    // New-bin arbitration.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if progress < 0.15 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, but weighted non-linearly by stream progress.
    // Early: prefer tight fits (penalize large residual). Late: waste matters more.
    let progress_weight = 0.5 + 0.5 * progress * progress;
    let mut score = pr * (0.6 + 0.8 * progress_weight);

    // Smooth quadratic dead-space penalty: residuals that are too small to ever
    // hold a typical item are wasted; penalize the U-shaped region.
    let dead = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score -= 18.0 * dead * cap;

    // Reward leaving room for the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (pr - nx).abs();
        let closeness = 1.0 / (1.0 + fit_gap / cap);
        score -= 10.0 * closeness * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    let open_norm = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
    score += 6.0 * open_norm * pr_norm;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps residuals balanced), smoothly damped.
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * cap;

    // Perfect-fit bonus via smooth saturating term.
    score -= 8.0 * (-pr_norm * 10.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

