    // Coupling with mean residual: placing into a bin far below mean residual
    // balances the fleet.
    let dev = mean_residual - post_residual as f64;
    score += 0.3 * dev;

    // Tight-fit reward: residual barely above item size is efficient packing.
    let tight = (bin_residual - item_size) as f64;
    if tight < 10.0 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Fraction-of-capacity phase of item: mid-range items pack better into
    // mid-range leftovers (harmonic pairing).
    let item_frac = item_size as f64 / cap;
    let resid_frac = bin_residual as f64 / cap;
    let pair = (item_frac * 4.0).floor() == (resid_frac * 4.0).floor();
    if pair && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 12) are wasted capacity. Penalize hard.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 + (12 - post_residual) as f64 * 8.0;
    }
    // "Awkward zone": gaps that only tiny items can use (13..=20).
    if post_residual >= 13 && post_residual <= 20 {
        score += 18.0;
    }

    // Reward tight fits (best-fit core), super-linear.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Perfect closure is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage scattering into many bins when
    // open_bins_count is high, unless the fit is very tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Mean-residual coupling: if this bin's residual is far below average,
    // it is a "leftover" bin; using it for a big item is efficient.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.35;

    // Last-chance bin: strongly prefer filling the only bin that fits,
    // avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item would fit the post-residual, this placement
    // chains nicely; reward. If next item is large and barely misses,
    // slight penalty for stranding capacity.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 10.0;
        }
    }

    // New-bin candidate: neutral-ish baseline, slightly worse than a decent
    // fit but better than creating dead space. Scales with stream progress
    // and existing bin count (prefer consolidation early, allow new bins later).
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 1.5 - progress * 15.0;
        // If no open bin fits well, opening is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        if post_residual == 0 { score -= 40.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer fills that leave little usable space.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 9.0 * tightness * tightness * tightness;

    // Hard penalty for unusable dead space.
    if post_residual < 10 {
        score += 200.0;
    }

    // Finer ramp: penalize gaps too small to be useful for typical items.
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Soft penalty: gaps that likely cannot fit the next item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < 8.0 {
            score += 3.0 * (1.0 - deficit / 8.0);
        }
    }

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 150.0;
        if item_size == bin_residual {
            score -= 20.0;
        }
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead synergy with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            if post_residual - next_item_size < item_size / 3 {
                score -= 3.0;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
        if post_residual >= next_item_size && post_residual < next_item_size + 6 {
            score -= 2.0;
        }
        // Lookahead exact pair: residual equals next + current.
        if post_residual == next_item_size + item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Scarce-fit preference.
    if fitting_bins_count <= 2 && post_residual >= item_size {
        score -= 3.5;
    }

    // Consolidation pressure with many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        let rel = item_size as f64 / cap;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        score += 40.0 + pressure * 8.0 + 12.0 * rel * scarcity + 0.015 * remaining;
        // Near stream end: discourage new bins less strongly.
        let remaining_items = total_items.saturating_sub(step_index);
        if remaining_items < 20 {
            score -= 15.0;
        }
    } else {
        score -= pressure * 4.0;
    }

    // Prefer bins tighter than the average residual (best-fit style refinement).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Penalize wasteful large leftover space.
    if post_residual > 0 {
        let ratio = post_residual as f64 / cap;
        if ratio > 0.5 {
            score += 2.0 * (ratio - 0.5);
        }
        if mean_residual > 0.0 && (post_residual as f64) > 1.3 * mean_residual {
            score += 1.0;
        }
    }

    // Roomy residual can still hold the item again: mild penalty to avoid sprawl.
    if post_residual >= 2 * item_size {
        score += 1.5;
    }

    // Many open bins: dead residual is costly.
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Last-chance small-fit rescue.
    if post_residual > 0 && post_residual < item_size && fitting_bins_count <= 1 {
        score -= 2.5;
    }

    // Two-item chain anticipation: residual exactly fits next two items summed.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next == item_size {
            score -= 14.0;
        } else if after_next > 0 && after_next < item_size {
            score += 3.0;
        }
    }

    // Sharper dead-space penalty scaled by stream progress.
    if post_residual > 0 && post_residual < item_size / 4 {
        score += 4.0 + 6.0 * progress;
    }

    // Fine-grained best fit: residual close to current item.
    if post_residual > 0 && post_residual >= item_size {
        let gap = (post_residual - item_size) as f64;
        if gap < 8.0 {
            score -= 6.0 * (1.0 - gap / 8.0);
        }
    }

    // Deeper chain: residual match for next item twice.
    if next_item_size > 0 && post_residual >= next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == next_item_size {
            score -= 6.0;
        } else if r2 > 0 && r2 < 10 {
            score -= 2.0 + 0.2 * (10 - r2) as f64;
        }
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 && next_item_size > 20 {
            score -= 4.0 + 0.3 * (6 - gap) as f64;
        }
        let slack = post_residual - next_item_size;
        if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
            score += 1.5;
        }
    }

    // Small-residual scarcity penalty with many fitting options.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }

    // New mutation: with few open bins early, conserve tight bins for large items.
    if open_bins_count <= 3 && post_residual > 0 && post_residual < 15 && next_item_size > 25 {
        score += 4.0;
    }

    // New mutation: scale exact next-item match bonus by scarcity of fitting options.
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 2 {
        score -= 8.0;
    }

    // New mutation: when many bins are open, favor bins whose residual after placement
    // can still host the next item, penalizing otherwise (fragmentation control).
    if open_bins_count > 5 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 1.5 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: unusable slivers are pure waste; penalize non-linearly.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Reward tight fits (quadratic near-perfect packing bonus).
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage new bins when many are open, scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate handling: offset base cost only when fragmentation is high.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 + 0.5 * fragmentation;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.25 {
            score -= 15.0;
        }
        if post_residual as f64 > mean_residual * 1.5 && next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Lookahead: perfect two-item pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            // Two-step lookahead: residual after next item pairs with item itself.
            if gap == next_item_size as u32 {
                score -= 3.0;
            } else if gap > 0 && gap < 10 {
                score -= 2.0 + 0.2 * (10 - gap) as f64;
            }
            // Half-slack trap: leftover barely too small to reuse.
            if slack > 0.0 && slack < next_item_size as f64 && slack * 2.0 > next_item_size as f64 {
                score += 1.5;
            }
            // NEW: dead-space ratio coupling — penalize bins whose post-fit leftover
            // is a large fraction of capacity while many alternatives exist.
            if fitting_bins_count > 2 && post_residual as f64 > cap * 0.45 {
                score += 2.0 + 2.0 * (post_residual as f64 / cap);
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Prefer bins below mean residual (keep large residuals for large items).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Crowding: when many bins fit, slightly penalize tight post-residuals to
    // avoid hoarding near-perfect bins needed for exact pairings.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // NEW: combine residual fine-graining with lookahead — if the item nearly
    // empties the bin (post_residual tiny) and the next item is small, reward
    // completing this bin to keep open-bin count low.
    if post_residual <= 4 && next_item_size > 0 && next_item_size >= post_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small post_residual relative to capacity)
    let perfect_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * perfect_fit * perfect_fit;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how tightly it matches
            score -= 12.0 * (1.0 - diff / (post_residual.max(1) as f64));
        } else {
            // next item would NOT fit in residual: penalize leaving awkward space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste.min(30.0);
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins whose residual is close to item size (tight relative fit)
    let mean_res = mean_residual.max(1.0);
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * (tightness - 0.5).abs().min(0.5); // reward tightness near 1.0
    score += 1.5 * ((bin_residual as f64 - mean_res) / mean_res).abs().min(1.0);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize new-bin candidate mildly so it only wins when open bins are bad fits
    if bin_residual == bin_capacity {
        score += 6.0;
        // new bin more attractive early or when open bins are crowded
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 4.0; // new bin allows a clean pair
        }
    }

    // Prefer using fewer bins: mildly favor bins when many are open
    score += 0.02 * open_bins_count as f64;

    // Dead-space penalty: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 3.0 * fit_ratio;

    // Penalize small post-residuals that are still dead space
    // (too small for typical items but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Spread load when many bins fit: prefer bins with larger residuals
        score += 0.5 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (fresh empty bin candidate looks better early, worse later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: base score plus time-dependent adjustment
        score = bin_capacity as f64 * 0.9 + 20.0 * (1.0 - progress) - 10.0 * progress;
        // if no existing bin fits, new bin is the only option anyway
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global state: many open bins -> prefer consolidating into existing bins.
    score += 0.3 * open_bins_count as f64;

    // Mild nonlinearity: penalize mid-range residuals that waste capacity.
    let waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * waste * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly super-linear to punish dead space
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, demand tight packing.
    let tight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += tight * pr * pr / cap;

    // Perfect fit reward (smooth, quadratic falloff)
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_frac * fit_frac;

    // Lookahead: reward if next item fits in post_residual (smooth bonus)
    if next_item_size > 0 {
        let room = pr - next_item_size as f64;
        let bonus = (-room / cap).exp();
        score -= 8.0 * bonus;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Penalize scattering when many bins are open
    score += 0.15 * open_bins_count as f64;

    // Mean residual alignment: prefer bins close to mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fit (0), tiny waste, usable, dead space.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always take it
    } else if post_residual <= 5 {
        score -= 60.0;   // near-perfect fit, negligible waste
    } else if post_residual <= 20 {
        score -= 10.0;   // moderate waste still potentially usable
    } else {
        // large dead space: penalize quadratically
        score += (post_residual as f64 - 20.0) * 0.8;
    }

    // Harmonic class via integer division: post_residual buckets of 10
    let post_class = post_residual / 10;
    score += match post_class {
        0 => -25.0,
        1 => -5.0,
        2 => 0.0,
        3 => 5.0,
        4 => 10.0,
        5 => 15.0,
        6 => 20.0,
        7 => 25.0,
        8 => 30.0,
        _ => 35.0,
    };

    // Lookahead: does next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // chain exact fit
        } else if next_item_size <= post_residual {
            score -= 20.0;  // next item can also go here: good packing
        } else {
            // next item won't fit: dead space unless it's small waste
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
        // modulo coupling: next_item in same harmonic class as post_residual
        if post_residual > 0 && (next_item_size % 10) == (post_residual % 10) && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer reusing open bins early; allow new bin only
    // if current item is small relative to capacity (keeps flexibility)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let flexibility = 100.0 - item_size as f64;
        score = 110.0 + flexibility * 0.5 - progress * 20.0;
        // don't open a new bin if an open bin fits decently
        if fitting_bins_count > 0 && item_size <= 50 {
            score += 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // bigger item coming: fresh bin attractive
        }
    }

    // Prefer fuller bins: tie-break via fill fraction
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 12.0;

    // Mean residual coupling: if open bins are generally full, conserve them
    if mean_residual < 15.0 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (gaps that likely can't fit future items).
    let dead_threshold = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: fraction of bin used by this item.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 20.0;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual {
            score += 30.0; // new bin wastes more capacity than average open residual
        }
        score += open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item can't use the gap
    }

    // Slight preference for consolidating when stream is late (fewer bins overall).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: unusable slivers are pure waste; penalize non-linearly.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Reward tight fits (quadratic near-perfect packing bonus).
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage new bins when many are open, scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate handling: offset base cost only when fragmentation is high.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 + 0.5 * fragmentation;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.25 {
            score -= 15.0;
        }
        if post_residual as f64 > mean_residual * 1.5 && next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
        // NEW: open a fresh bin early when current open bins are badly fragmented
        // and the next item is large — a full bin preserves pairing options.
        if open_bins_count > 4 && next_item_size > 0 && (next_item_size as f64) > cap * 0.6 {
            score -= 4.0;
        }
    }

    // Lookahead: perfect two-item pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            // Two-step lookahead: residual after next item pairs with item itself.
            if gap == next_item_size as u32 {
                score -= 3.0;
            } else if gap > 0 && gap < 10 {
                score -= 2.0 + 0.2 * (10 - gap) as f64;
            }
            // Half-slack trap: leftover barely too small to reuse.
            if slack > 0.0 && slack < next_item_size as f64 && slack * 2.0 > next_item_size as f64 {
                score += 1.5;
            }
            // Dead-space ratio coupling — penalize bins whose post-fit leftover
            // is a large fraction of capacity while many alternatives exist.
            if fitting_bins_count > 2 && post_residual as f64 > cap * 0.45 {
                score += 2.0 + 2.0 * (post_residual as f64 / cap);
            }
            // NEW: triple-pairing lookahead — residual can host next item exactly
            // twice (gap == next_item_size), already covered; extend to gap being
            // exactly the mean of item and next item (harmonic fit).
            if gap > 0 && (gap as f64 - (item_size as f64 + next_item_size as f64) / 2.0).abs() < 1.0 {
                score -= 2.5;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Prefer bins below mean residual (keep large residuals for large items).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Crowding: when many bins fit, slightly penalize tight post-residuals to
    // avoid hoarding near-perfect bins needed for exact pairings.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Completing bins: if the item nearly empties the bin and the next item is
    // small, reward completing this bin to keep open-bin count low.
    if post_residual <= 4 && next_item_size > 0 && next_item_size >= post_residual {
        score -= 6.0;
    }

    // NEW: progress-scaled completion bonus — later in the stream, closing out
    // bins with small residuals is increasingly valuable.
    if post_residual <= 12 && progress > 0.5 {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: residual consumed by next item
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after that
            let second_leftover = post_residual - next_item_size;
            score -= 200.0;
            score += second_leftover as f64 * 0.5;
        } else {
            // next item won't fit here: penalize large dead residuals
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize creating dead space relative to mean residual
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Prefer filling bins that are already fairly full
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Slight preference to keep open bin count low
    score += open_bins_count as f64 * 0.5;

    // Late in the stream, tighten packing (avoid leaving scattered residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 400.0; // opening a fresh bin that will chain perfectly
        }
    }

    score
}

