pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer fills that leave little usable space.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 9.0 * tightness * tightness * tightness;

    // Hard penalty for unusable dead space.
    if post_residual < 10 {
        score += 200.0;
    }

    // Finer ramp: penalize gaps too small to be useful for typical items.
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Soft penalty: gaps that likely cannot fit the next item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * post_residual as f64;
        let deficit = (next_item_size - post_residual) as f64;
        if deficit < 8.0 {
            score += 3.0 * (1.0 - deficit / 8.0);
        }
    }

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 150.0;
        if item_size == bin_residual {
            score -= 20.0;
        }
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead synergy with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
            if fitting_bins_count <= 2 {
                score -= 8.0;
            }
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            if post_residual - next_item_size < item_size / 3 {
                score -= 3.0;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
        if post_residual >= next_item_size && post_residual < next_item_size + 6 {
            score -= 2.0;
        }
        if post_residual == next_item_size + item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Scarce-fit preference.
    if fitting_bins_count <= 2 && post_residual >= item_size {
        score -= 3.5;
    }

    // Consolidation pressure with many open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        let rel = item_size as f64 / cap;
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        let remaining = (total_items.saturating_sub(step_index)) as f64;
        score += 40.0 + pressure * 8.0 + 12.0 * rel * scarcity + 0.015 * remaining;
        // New-bin lookahead: if the next item fits comfortably in a fresh bin too,
        // and the current fit is loose, opening a new bin is cheaper.
        if next_item_size > 0 && post_residual > next_item_size * 2 {
            score += 6.0;
        }
        let remaining_items = total_items.saturating_sub(step_index);
        if remaining_items < 20 {
            score -= 15.0;
        }
    } else {
        score -= pressure * 4.0;
    }

    // Prefer bins tighter than the average residual (best-fit style refinement).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    // Penalize wasteful large leftover space.
    if post_residual > 0 {
        let ratio = post_residual as f64 / cap;
        if ratio > 0.5 {
            score += 2.0 * (ratio - 0.5);
        }
        if mean_residual > 0.0 && (post_residual as f64) > 1.3 * mean_residual {
            score += 1.0;
        }
    }

    // Roomy residual can still hold the item again: mild penalty to avoid sprawl.
    if post_residual >= 2 * item_size {
        score += 1.5;
    }

    // Many open bins: dead residual is costly.
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Last-chance small-fit rescue.
    if post_residual > 0 && post_residual < item_size && fitting_bins_count <= 1 {
        score -= 2.5;
    }

    // Two-item chain anticipation: residual exactly fits next two items summed.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next == item_size {
            score -= 14.0;
        } else if after_next > 0 && after_next < item_size {
            score += 3.0;
        }
    }

    // Sharper dead-space penalty scaled by stream progress.
    if post_residual > 0 && post_residual < item_size / 4 {
        score += 4.0 + 6.0 * progress;
    }

    // Fine-grained best fit: residual close to current item.
    if post_residual > 0 && post_residual >= item_size {
        let gap = (post_residual - item_size) as f64;
        if gap < 8.0 {
            score -= 6.0 * (1.0 - gap / 8.0);
        }
    }

    // Deeper chain: residual match for next item twice.
    if next_item_size > 0 && post_residual >= next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == next_item_size {
            score -= 6.0;
        } else if r2 > 0 && r2 < 10 {
            score -= 2.0 + 0.2 * (10 - r2) as f64;
        }
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 6 && next_item_size > 20 {
            score -= 4.0 + 0.3 * (6 - gap) as f64;
        }
        let slack = post_residual - next_item_size;
        if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
            score += 1.5;
        }
    }

    // Small-residual scarcity penalty with many fitting options.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }

    // With few open bins early, conserve tight bins for large items.
    if open_bins_count <= 3 && post_residual > 0 && post_residual < 15 && next_item_size > 25 {
        score += 4.0;
    }

    // Fragmentation control with many open bins.
    if open_bins_count > 5 && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 1.5 + 2.0 * progress;
    }

    // New mutation: graded exact-fit ladder — residual exactly fitting the next item
    // is rewarded more when the residual is small (high-value space preservation).
    if next_item_size > 0 && post_residual == next_item_size && post_residual < 40 {
        score -= 5.0 * (1.0 - post_residual as f64 / 40.0);
    }

    // New mutation: avoid leaving residuals in the "awkward middle band" that few
    // item sizes can fill; push selection toward either very tight or very usable.
    if post_residual > 40 && post_residual < 70 {
        score += 2.0 + 0.1 * (70 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always excellent
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fits are good: reward small post_residual relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 12.0 / (1.0 + tightness);

    // Penalize dead space that no future item can use: post_residual below
    // minimum item size (1) is impossible here, but very small residuals
    // (< 10) are likely wasted unless the bin is nearly full.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain two items into this bin
            let two_fit_tight = (post_residual - next_item_size) as f64;
            score -= 10.0 + 8.0 / (1.0 + two_fit_tight);
        } else {
            // Next item won't fit here; penalize leaving awkward gaps
            score += 4.0;
            // If the gap is smaller than next item but larger than tiny,
            // it may become dead space
            if post_residual < next_item_size {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin fits well. Make the empty-bin call costly unless the
    // item is large relative to capacity or open bins are very fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin
        let mut new_bin_penalty = 20.0;
        // Large items benefit from a fresh bin
        new_bin_penalty -= 18.0 * fill_ratio;
        // Fragmentation: if mean residual is small relative to item, open bins are poor hosts
        let frag = (item_size as f64 - mean_residual).max(0.0) / bin_capacity as f64;
        new_bin_penalty -= 25.0 * frag;
        // Late in the stream, prefer consolidating into open bins
        new_bin_penalty += 10.0 * progress;
        // If many bins can fit the item, definitely prefer an existing one
        if fitting_bins_count > 2 {
            new_bin_penalty += 15.0;
        }
        score += new_bin_penalty;
    } else {
        // Prefer fuller bins (waste-aware): reward low current residual usage
        let used = (bin_capacity - bin_residual) as f64;
        score -= 5.0 * (used / bin_capacity as f64);

        // Mild preference for bins whose residual is close to mean residual
        // (keeps bin pool homogeneous, easing future packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Global state: when many bins are open, discourage opening more
    score += 0.3 * open_bins_count as f64;

    // Progress-horizon coupling: early on, be tolerant of imperfect fits
    // (exploration); later, be strict to squeeze the tail.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: later in stream, penalize residual more strongly (tighten packing)
    let progress_coupling = 1.0 + 0.6 * progress * (1.0 - progress * 0.5);
    score *= progress_coupling;

    // Smooth interaction: post_residual vs mean residual — avoid bins that leave residual far below mean (isolated dead space)
    let mean_gap = (pr - mean_residual) / cap;
    score += 12.0 * mean_gap * mean_gap;

    // Reward near-perfect fills smoothly (post_residual close to 0)
    score -= 20.0 * (-pr / 8.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: penalize leaving residual that barely misses the next item (unusable sliver)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            // next item fits later; small positive gap is a wasted sliver
            score += 6.0 * (-gap / 5.0).exp();
        } else {
            // next item cannot fit here anyway; residual value depends on reusability
            score += 2.0 * (pr / cap);
        }
    }

    // Slight preference for keeping many open bins consolidated when few remain
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: make it moderately attractive only when residual is full and item is large
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
