pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals divisible by common
    // item granularities (10/20/25/50) are far more reusable than odd ones.
    let cap = bin_capacity;
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr == 0 {
        harmonic_bonus -= 60.0; // perfect fit: best possible outcome
    } else {
        if pr % 10 == 0 { harmonic_bonus -= 14.0; }
        if pr % 20 == 0 { harmonic_bonus -= 8.0; }
        if pr % 25 == 0 { harmonic_bonus -= 8.0; }
        if pr % 50 == 0 { harmonic_bonus -= 10.0; }
        // Integer-division thresholds: small residuals are dead space.
        if pr < 10 { harmonic_bonus += 25.0; }           // unusable sliver
        else if pr < 20 { harmonic_bonus += 12.0; }
        else if pr > cap / 2 { harmonic_bonus -= 6.0; }  // still roomy
    }
    score += harmonic_bonus;

    // Lookahead coupling: does the next item's harmonic class fit this residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or leaves a harmonic residual
            let next_post = pr - next_item_size;
            if next_post == 0 { score -= 22.0; }
            else if next_post % 10 == 0 { score -= 10.0; }
        } else {
            // next item cannot reuse this bin's residual at all
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-poor so we only
    // open a new bin when existing options are truly bad.
    if bin_residual == cap {
        score += 18.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If many open bins are already cluttered, fresh bin is attractive.
        if mean_residual < 15.0 && open_bins_count > 2 { score -= 15.0; }
    }

    // Mild penalty for scattering across too many bins when a tight fit exists.
    if post_residual < 15 && bin_residual < cap {
        score -= 4.0;
    }

    score
}

