            score -= 38.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            // Two-item lookahead: residual that exactly fits next item again.
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 3.0;
