    // Many open bins: discourage spreading when fit is poor.
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Crowded packing pressure on tight residuals.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.3;
        // But allow new bin if residual is large relative to mean (poor fits everywhere).
        if next_item_size > 0 && next_item_size <= bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
