    } else {
        // 2-step lookahead: reward if next item exactly fills the new residual,
        // penalize if next item cannot fit into the residual (dead space risk).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0; // chain of two perfect fills
            } else if next_item_size > post_residual {
                // dead space unless this is the last fitting bin
                let progress = step_index as f64 / total_items.max(1) as f64;
                score += 40.0 + 60.0 * progress;
                if fitting_bins_count == 1 {
                    score -= 120.0; // last chance: avoid opening a new bin
                }
            } else {
                // next item fits: mild reward proportional to tightness
                let tight = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
                score -= 30.0 * tight;
                if next_item_size + post_residual as u32 > 0 && post_residual - next_item_size == 0 {
                    score -= 500.0;
                }
            }
        }

        // Prefer bins tighter than the mean residual (best-fit flavor).
        score += 0.5 * (mean_residual - bin_residual as f64);

        // Last-chance bin bonus.
        if fitting_bins_count == 1 {
            score -= 80.0;
        }

        // Penalize opening a brand-new bin when a decent fit exists elsewhere.
        if bin_residual == bin_capacity {
            // New bin residual = capacity - item, large; add fixed penalty so
            // existing bins with reasonable post_residual win, but if all open
            // bins are hopeless (huge post_residual), new bin still wins.
            score += 70.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 10.0; // fresh bin leaves room for lookahead item
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
