pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let pr = post_residual as f64;

    // Lookahead coupling: reward bins whose leftover perfectly hosts the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (nx - pr).abs() < 0.5 {
            score -= 25.0; // perfect two-item fill
        } else if nx <= pr {
            score -= 10.0 * (nx / pr.max(1.0)); // next item fits well here
        } else {
            score += 3.0 * ((nx - pr) / bin_capacity as f64); // next item won't use leftover
        }
    }

    // Dead-space shaping: tiny leftovers are great, mid-range waste is penalized
    if pr < 10.0 {
        score -= 6.0;
    } else {
        score += 0.35 * (pr - 10.0).min(40.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when alternatives are poor/absent
    if is_new_bin {
        if fitting_bins_count > 1 {
            score += 22.0 + 6.0 * (fitting_bins_count as f64).ln().max(0.0);
        } else if fitting_bins_count == 1 {
            score += 6.0; // still slightly favor reusing the single fitting bin
        } else {
            score -= 10.0; // must open a new bin
        }
        score -= 0.15 * open_bins_count as f64; // consolidation pressure on bin count
    }

    // Prefer tighter-than-average bins (relative residual ordering)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Dynamic time horizon: mild tightening of preferences as stream progresses
    score *= 1.0 + 0.08 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap; // fraction filled after placement
    let mut score = pr;

    // Smooth non-linear coupling: quadratic fill reward grows with stream progress
    score -= 18.0 * fill * fill * (0.5 + progress);

    // Penalize dead space relative to mean residual, smooth cubic in fill
    let dead = (pr - mean_residual).max(0.0);
    score += 0.05 * dead * (1.0 + fill * fill);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * fill;
    }

    // Lookahead coupling: reward if next item fits smoothly into post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_frac = next_item_size as f64 / cap;
        score -= 12.0 * fit_frac * (1.0 - fill) * (1.0 + progress);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize creating residual too small for the lookahead item
        score += 6.0 * (1.0 - pr / cap) * progress;
    }

    // Slight pressure to consolidate when many bins are open
    score -= 3.0 * fill * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // New-bin candidate: keep it competitive only when existing bins are poor fits
    if bin_residual == bin_capacity {
        score += 10.0 * fill + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-capacity buckets (mod arithmetic on capacity fractions)
    let quarter = bin_capacity / 4;
    let item_class = item_size / quarter;               // 0..=4
    let next_class = next_item_size / quarter;          // 0..=4 (0 => no lookahead)
    let post_class = post_residual / quarter;           // harmonic class of leftover

    // Reward placing item into a bin whose residual is in a complementary harmonic class:
    // residual class == item class means near-perfect fill.
    let residual_class = bin_residual / quarter;
    if residual_class == item_class {
        score -= 8.0;
    } else if residual_class == item_class + 1 {
        score -= 4.0;
    }

    // Penalize dead space: leftover in the lowest harmonic band is fine only if tiny.
    if post_residual > 0 && post_residual < quarter / 2 {
        score += 3.0; // unusable sliver
    }
    if post_class == 0 && post_residual > 0 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual (same class match),
    // strongly reward this bin to enable chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap < quarter / 2 {
            score -= 6.0;
        } else if (post_residual / quarter) == (next_item_size / quarter) {
            score -= 3.0;
        }
    }
    // If next item cannot fit here, mild penalty proportional to its size class.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 1.0 + 0.5 * next_class as f64;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 5.0 + 0.05 * (item_size as f64);
    }

    // New-bin candidate handling: an empty bin has huge post_residual; make it
    // attractive only when open-bin fits are bad (large post_residual relative to mean).
    if bin_residual == bin_capacity {
        // Baseline competitiveness: slight penalty so it only wins when others are worse.
        score += 4.0;
        // Early in the stream or many bins open: prefer reusing bins less aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 2.0 * (1.0 - progress);
        // If mean residual of open bins is small, a new bin is justified.
        if mean_residual < item_size as f64 {
            score -= 6.0;
        }
        // Big items (top harmonic class) start fresh bins more readily.
        if item_class >= 2 {
            score -= 2.0 * item_class as f64;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    if total_items > 0 && step_index + 2 >= total_items {
        score -= 3.0;
    }

    // Small global tie-breaker toward tighter fits.
    score += (post_residual as f64) * 0.01 * (1.0 + 0.1 * open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover in (0, 10) is unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward filling a bin deeply (tight fit relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins implicitly
    // by favoring existing bins more; with few bins, allow spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 6.0 * pressure;

    // Dead-space coupling: if post_residual is small-but-nonzero AND many bins
    // are open, penalize extra hard (accumulated fragmentation).
    if post_residual > 0 && post_residual < 20 && open_bins_count > 4 {
        score += 10.0 * ((20 - post_residual) as f64 / 20.0);
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would also be blocked by this post residual, penalize.
    if next_item_size > post_residual && post_residual > 0 && next_item_size <= item_size + 5 {
        score += 8.0;
    }

    // Mild preference to keep mean residual high (balanced bin usage).
    score -= 0.05 * mean_residual;

    // Slight late-stream tightening: as stream progresses, avoid waste more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New empty bin: only attractive when no tight option exists.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
