    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.5 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // New-bin candidate handling: an empty bin is only attractive when the current
    // item is large and no open bin fits well, or late in the stream with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let best_open = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        // Base penalty so new bins aren't opened frivolously.
        score += 45.0;
        // Reward opening a new bin when the item is huge relative to capacity
        // (large items pair poorly with fragmented residuals).
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // Slightly more willing to open bins early (plenty of stream left to fill them).
        score -= 15.0 * (1.0 - progress);
        // If no other bin even fits, opening is inevitable; reduce penalty.
        if best_open < 1.0 {
            score -= 30.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (i.e., tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Mild pressure to keep the number of open bins from exploding.
    score += 0.5 * open_bins_count as f64;

    // Time horizon: late in the stream, prioritize closing out bins (fill them fully).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance with graduated penalty.
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: exact match strongly rewarded, near match graded.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 38.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            // Two-of-next-item lookahead.
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 3.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.2 * (10 - r2) as f64;
            }
            // Tight gap with substantial next item.
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            // Slack half-of-next: moderately bad leftover.
            let slack2 = post_residual - next_item_size;
            if slack2 > 0 && slack2 < next_item_size && slack2 * 2 > next_item_size {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.4;
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.3;
        // But allow a new bin late in stream if open bins are nearly full.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 8.0 + 5.0 * progress;
        }
    }

    // Small residual with several fitting bins: slight penalty (waste risk).
    if post_residual < 31 && fitting_bins_count > 3 && post_residual > 0 {
        score += 1.5;
    }

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth stream-progress coupling: early on tolerate residual, late on penalize it
    let progress_coupling = 0.5 * progress * (1.0 - progress);
    score -= progress_coupling * pr * (item_size as f64 / cap);

    // Reward tight fits via a smooth saturating term
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_tightness * fit_tightness * (1.0 - progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 3.0 * (gap / cap).powi(2) * (1.0 + progress);
        } else {
            score -= 2.0 * (-gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balanced fills)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: make it unattractive unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let post_f = post_residual as f64;
    let quarter = post_residual / (bin_capacity / 4);
    let eighth = post_residual / (bin_capacity / 8);
    let sixteenth = post_residual / (bin_capacity / 16);

    // Perfect fit -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small post_residual nonlinearly (dead space penalty grows fast).
    score += (post_f * post_f) / (cap * 4.0);

    // Harmonic class bonus: leftover that exactly matches common item sizes
    // (multiples of capacity/16 classes) is more reusable.
    if post_residual != 0 && post_residual % (bin_capacity / 16) == 0 {
        score -= 5.0 + (sixteenth as f64);
    }
    if post_residual % (bin_capacity / 8) == 0 && post_residual != 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; leftover becomes dead space unless small
            score += 10.0 * (1.0 - post_f / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize opening new bins unless current
    // bin would leave awkward residue and many bins already open.
    if bin_residual == bin_capacity {
        score = cap as f64 + 50.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 60.0; // big next item: fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer bins whose residual is "harmonically compatible" with item.
        let item_class = item_size / (bin_capacity / 8);
        let res_class = bin_residual / (bin_capacity / 8);
        if item_class == res_class {
            score -= 8.0;
        }
        // Late in stream, consolidate: reward filling existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress * (1.0 - post_f / cap);
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
