    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: unusable slivers are pure waste; penalize non-linearly.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Reward tight fits (quadratic near-perfect packing bonus).
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage new bins when many are open, scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate handling: offset base cost only when fragmentation is high.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 + 0.5 * fragmentation;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.25 {
            score -= 15.0;
        }
        if post_residual as f64 > mean_residual * 1.5 && next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
        // NEW: avoid opening a new bin when several open bins still fit well.
        if fitting_bins_count > 1 && mean_residual > cap * 0.5 {
            score += 8.0 + 1.5 * fitting_bins_count as f64;
        }
    }

    // Lookahead: perfect two-item pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            // Two-step lookahead: residual after next item pairs with item itself.
            if gap == next_item_size as u32 {
                score -= 3.0;
            } else if gap > 0 && gap < 10 {
                score -= 2.0 + 0.2 * (10 - gap) as f64;
            }
            // Half-slack trap: leftover barely too small to reuse.
            if slack > 0.0 && slack < next_item_size as f64 && slack * 2.0 > next_item_size as f64 {
                score += 1.5;
            }
            // Dead-space ratio coupling — penalize bins whose post-fit leftover
            // is a large fraction of capacity while many alternatives exist.
            if fitting_bins_count > 2 && post_residual as f64 > cap * 0.45 {
                score += 2.0 + 2.0 * (post_residual as f64 / cap);
            }
            // NEW: fine-grained residual bucketing — reward leaving residuals
            // in the "highly reusable" band (roughly 25..=55) which future
            // mid-size items can still fill.
            if post_residual >= 25 && post_residual <= 55 && next_item_size < post_residual {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Prefer bins below mean residual (keep large residuals for large items).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Crowding: when many bins fit, slightly penalize tight post-residuals to
    // avoid hoarding near-perfect bins needed for exact pairings.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Completing a bin when the next item is small keeps open-bin count low.
    if post_residual <= 4 && next_item_size > 0 && next_item_size >= post_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else if post_residual < 2 * min_useful {
        score += 15.0; // awkward small gap
    }

    // Coupling: dead-space penalty scales with stream progression (later waste is costlier).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: prefer bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Mean residual alignment: prefer bins near the mean to keep balance.
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    // New-bin candidate: allow opening a new bin only when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < min_useful;
        if poor_fit {
            score -= 55.0; // new bin better than creating dead space
        } else {
            score += 70.0; // strongly prefer existing bins otherwise
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits into the leftover space -> reward proportionally
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit -> penalize wasted near-fit space
    else if next_item_size > 0 && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        score += 25.0 * (miss / 100.0).min(1.0);
    }

    // Last-chance bin: if this is the only bin that can fit, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Compare residual to mean residual across open bins:
    // prefer bins tighter than average (concentrate fill)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Penalize leaving tiny dead space that nothing (min size 1..) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Late in the stream, prefer closing bins tightly (favor fuller bins)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate (empty bin): make it unattractive unless residuals are all bad
    if bin_residual == bin_capacity {
        score += 150.0 + 10.0 * open_bins_count as f64;
        // If next item is huge and no open bin would hold both, opening may be fine
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to capacity (wasted capacity).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead * dead;

    // Lookahead: penalize if the post-residual can't fit the next item (blocking),
    // but only when it's a near-miss; if next item fits comfortably, reward.
    if next_item_size > 0 {
        if (post_residual as f64) < next_item_size as f64 {
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.6 * gap;
        } else {
            score -= 0.3 * (post_residual as f64 - next_item_size as f64).min(20.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make the empty bin attractive only when the
    // current fit is poor (item much smaller than residual) or when many bins
    // are open with low mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let poor_fit = 1.0 - fit_ratio;
        let frag = (mean_residual / bin_capacity as f64 - 0.5).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * poor_fit * (0.5 + 0.5 * progress) + 15.0 * frag;
        // Early in the stream, keep bins consolidated; later, opening fresh bins
        // is fine since future items are unpredictable.
        score += 10.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins when mean residual
    // is already low (fragmentation control).
    if open_bins_count > 4 {
        score += 0.05 * open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64);
    }

    // Small noise-free tie-breaker favoring bins with smaller original residual
    // (denser bins first).
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

