    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Reward tight fits (quadratic near-perfect packing bonus).
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage new bins when many are open, scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate handling: offset base cost only when fragmentation is high.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 + 0.5 * fragmentation;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.25 {
            score -= 15.0;
        }
        if post_residual as f64 > mean_residual * 1.5 && next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Lookahead: perfect two-item pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            // Two-step lookahead: residual after next item pairs with item itself.
            if gap == next_item_size as u32 {
                score -= 3.0;
            } else if gap > 0 && gap < 10 {
                score -= 2.0 + 0.2 * (10 - gap) as f64;
            }
            // Half-slack trap: leftover barely too small to reuse.
            if slack > 0.0 && slack < next_item_size as f64 && slack * 2.0 > next_item_size as f64 {
                score += 1.5;
            }
            // Dead-space ratio coupling — penalize bins whose post-fit leftover
            // is a large fraction of capacity while many alternatives exist.
            if fitting_bins_count > 2 && post_residual as f64 > cap * 0.45 {
                score += 2.0 + 2.0 * (post_residual as f64 / cap);
            }
            // NEW: combine residual fine-graining with lookahead — reward bins
            // whose post-fit leftover is a reusable "nice" size (divisor-like
            // chunks) so future small items can tile the remainder exactly.
            if gap >= 10 && gap <= 60 && gap % 10 == 0 {
                score -= 3.0 + 0.1 * (gap as f64 / 10.0);
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
            // NEW: if this bin is the ONLY one that could take the next item
            // after a slightly different placement, don't waste it on a bad fit.
            if fitting_bins_count == 1 && over > cap * 0.5 {
                score += 6.0;
            }
        }
    }

    // Prefer bins below mean residual (keep large residuals for large items).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Crowding: when many bins fit, slightly penalize tight post-residuals to
    // avoid hoarding near-perfect bins needed for exact pairings.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Combine residual fine-graining with lookahead — if the item nearly
    // empties the bin (post_residual tiny) and the next item is small, reward
    // completing this bin to keep open-bin count low.
    if post_residual <= 4 && next_item_size > 0 && next_item_size >= post_residual {
        score -= 6.0;
    }

    // NEW: mean-residual coupling — when the item leaves a post-residual close
    // to the stream's mean residual, future items are likely to fit; reward it.
    let mr_diff = (post_residual as f64 - mean_residual).abs();
    if post_residual > 0 && mr_diff < 5.0 {
        score -= 2.5 * (1.0 - mr_diff / 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - progress) - prn * progress * progress;
    score += 12.0 * poly;

    // Reward tight fits, stronger as stream progresses
    let tightness = 1.0 - prn;
    score -= 8.0 * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: penalize wasting space the next item could use
    if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
        let waste = pr - next_item_size as f64;
        score += 0.05 * waste * waste / (1.0 + progress);
    }

    // Penalize spreading residuals when many bins are open
    score += 0.1 * (open_bins_count as f64).ln() * (prn - mean_residual / bin_capacity as f64).abs();

    // New-bin candidate: prefer it only when residuals are fragmented late
    if bin_residual == bin_capacity {
        score -= 2.0 * (1.0 - progress) - 1.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
