    // Harmonic classes: classify post_residual into capacity-fraction bands.
    // Residuals in the "dead zone" (<= 1/4 capacity) are nearly unusable for
    // typical items, so penalize them; mid residuals are flexible.
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    let post = post_residual as f64;
    if post > 0.0 {
