    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Modulo arithmetic on residual: residuals near multiples of 8 pair well
    // with common item sizes; reward closeness to the nearest multiple of 8.
    let m = post_residual % 8;
    let dist = m.min(8 - m) as f64;
    score -= 1.5 * (4.0 - dist);

    // Integer-division thresholds: post_residual / next_item_size lookahead.
    if next_item_size > 0 && post_residual > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits here too: excellent chaining.
            score -= 8.0 + 0.1 * n;
            let leftover = post_residual - next_item_size as u32;
            if leftover <= 10 {
                score -= 5.0; // near-perfect two-item packing
            }
        } else {
            // Next item won't fit: waste risk, scaled by how much it overflows.
            let over = (next_item_size - post_residual) as f64;
            score += 0.08 * over;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: prefer keeping it closed when decent fits exist;
    // open it only if this bin's post-fit residual would be very small
    // relative to the mean residual of open bins.
    if bin_residual == bin_capacity {
        score = post + 6.0;
        if post < mean_residual.min(40.0) - 5.0 {
            score -= 10.0; // open a fresh bin for a very tight fit
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild stream-progress term: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (post / cap);

    score
}

