    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Reward completing this bin when the next item can also fit the leftover.
    if post_residual <= 4 && next_item_size > 0 && next_item_size >= post_residual {
        score -= 6.0;
    }

    // COMBINED: guard against creating stranded slivers that no typical item
    // (>= 10) can ever reuse, scaled by how many alternatives exist.
    if post_residual > 0 && post_residual < 10 && fitting_bins_count > 1 && next_item_size > post_residual {
        score += 4.0 + 0.5 * (10 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + t * (0.35 - 0.9 * norm_pr) + t * t * (0.6 * norm_pr - 0.2);
    score *= poly;

    // Reward tight fits (small post_residual), smoothly via squared term
    score -= (cap - pr) * (cap - pr) / (cap * cap) * 6.0;

    // Penalize dead space relative to mean residual across open bins
    score += ((pr - mean_residual).abs() / cap) * 4.0;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for too many open bins, encouraging consolidation
    score += open_bins_count as f64 * 0.05 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit style preference for tight fits, with dead-space penalty
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * dead * dead; // superlinear penalty on unusable slack

    // Harmonic classes: classify post_residual into capacity fraction classes
    // class 0: post_residual == 0 (perfect fit) -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Integer division thresholds: post_residual bucket by quarter-capacity
        let quarter = bin_capacity / 4;
        let class = post_residual / quarter.max(1); // 0..=4 harmonic class
        match class {
            0 => score -= 18.0, // residual < 25: nearly full, great placement
            1 => score -= 4.0,  // residual 25..49: moderately usable
            2 => { /* residual 50..74: neutral */ }
            3 => score += 6.0,  // residual 75..99: wasteful for a small item
            _ => score += 10.0, // placing into an essentially empty bin
        }
        // Modulo arithmetic: items leaving residual divisible by common sizes
        // (e.g. residual in {10,20,25,50}) are more likely to be reused later
        let r = post_residual;
        if r % 10 == 0 || r % 25 == 0 || r % 50 == 0 {
            score -= 5.0;
        }
        // Penalize residuals that no typical item (1..100) can pair with well:
        // residual 1..9 is dead space for the stated granularity
        if r < 10 {
            score += 25.0;
        }
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain a perfect follow-up
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * snug;
        } else {
            // next item cannot use this bin's remainder: mild penalty unless
            // residual is large enough to be generically reusable
            if post_residual < next_item_size && post_residual < 30 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early
    // in the stream or when open bins are already cluttered with slack
    if bin_residual == bin_capacity {
        // empty new bin: score = capacity (large residual), adjusted by context
        let progress = step_index as f64 / total_items.max(1) as f64;
        let clutter = mean_residual / bin_capacity as f64;
        // late in stream with low clutter, prefer reusing open bins
        score += 20.0 * (1.0 - progress) * (1.0 - clutter);
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
        if fitting_bins_count == 0 {
            score -= 10.0; // nothing fits anywhere; new bin is fine
        }
    }

    // Slight tie-breaker: prefer bins with more total slack absorbed already
    score += 0.01 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score += 180.0 + 6.0 * (10 - post_residual) as f64;
    } else if post_residual <= 25 {
        score += 60.0 + 1.5 * (25 - post_residual) as f64;
    } else if post_residual >= 50 {
        score -= 45.0;
    }

    // Fill ratio bonus.
    let fill = (item_size as f64) / cap;
    score -= 60.0 * fill;

    // Consolidation pressure, softened as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Lookahead: exact match next step is gold.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 20.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.25 * (10 - r2) as f64;
            }
            let gap = r2;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 6.0 * (over / cap);
        }
    }

    // Mean-residual balance: avoid hoarding space far above the mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.4 * diff.abs();

    // Don't burn a big bin on a tiny item unless few bins are open anyway.
    if item_size <= 20 && bin_residual >= 80 && open_bins_count > 4 {
        score += 45.0;
    }

    // Late-stream tightness.
    if open_bins_count > 8 && post_residual > 0 && post_residual < item_size {
        score += 3.0;
    }

    // Tiny dead gap with many fitting options: mild extra penalty.
    if post_residual < 31 && fitting_bins_count > 3 && post_residual > 0 {
        score += 1.5;
    }

    // Dead-space ratio: penalize bins whose residual stays small and unusable
    // relative to the incoming item when many alternatives exist.
    if post_residual > 0 && fitting_bins_count > 2 {
        let usable = (post_residual as f64) / cap;
        if usable < 0.12 && item_size > post_residual {
            score += 6.0 * (0.12 - usable) / 0.12;
        }
    }

    // Reward leaving a residual close to a plausible future item size
    // (multiples of small items are common in these streams).
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 3.0;
    }

    // New-bin arbitration.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if progress < 0.15 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
            score -= 3.0;
        }
        // Opening a fresh bin is wasteful if an open bin fits with near-zero waste.
        if post_residual <= 15 && fitting_bins_count >= 1 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage filling existing ones.
    let open_pressure = open_bins_count as f64 * 0.4;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to pressure.
        score += open_pressure;
        // Also penalize if the lookahead item could have shared this bin's slot.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 10.0;
        }
    } else {
        // Reward using existing bins more when many are open.
        score -= open_pressure * 0.5;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item is large and would leave this bin's residual dead, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Early stream: be slightly more willing to open bins (future flexibility);
    // late stream: consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * -5.0 + progress * 5.0;
    }

    // Mean residual coupling: if average residual is high, prefer tightening bins.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

