pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is already favored by the base term.

    // 2-step lookahead: strongly reward when next item exactly fills post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here after placement; penalize slightly
        score += 10.0;
    }

    // Perfect-fill lookahead bonus
    if next_item_size == post_residual && next_item_size > 0 {
        score -= 40.0;
    }

    // Penalize creating dead space relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bin residuals are all poor fits
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // if few bins fit the item, opening a new bin is more attractive
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        // late in the stream, prefer closing out bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Mild preference for bins with less residual before placement (denser bins)
    score += 0.1 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.99;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post-residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness;

    // Penalize dead space: residuals too small to fit typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 3.0 * (30.0 - post_residual as f64) / 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this placement; penalize if it nearly fits but not quite.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for hoarding capacity in a many-bin regime.
        score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0) / 10.0;
    }

    // Global state: when many bins are open, discourage opening new bins
    // (handled implicitly since new-bin candidate has max residual; add explicit pull).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more heavily as stream progresses
        // and when open bins could absorb the item.
        score += 8.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
        // Early stream: opening fresh bins is cheap, allow it sometimes.
        if progress < 0.1 && fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidate fuller bins),
    // scaled by how far along the stream we are.
    let mean_gap = mean_residual - bin_residual as f64;
    score -= 1.5 * progress * mean_gap / 20.0;

    // Waste-avoidance term: placing a large item into a nearly-full bin is ideal.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 5.0 * fill_ratio * fill_ratio * tightness;

    // Small jitter-free deterministic tiebreak based on bin identity proxy.
    score += (bin_residual as f64) * 0.001;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: quadratic penalty on wasted space.
    let waste_norm = pr / cap;
    score += 30.0 * waste_norm * waste_norm;

    // Penalize bins whose residual is far from mean residual (prefer balanced depletion).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Stream-progress coupling: later in stream, waste matters more (fewer future items to fill gaps).
    let progress_coupling = 1.0 + 3.0 * progress * progress;
    score *= progress_coupling;

    // Lookahead: bonus if the post residual can accommodate the next item exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - gap * gap);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Discard opening a new bin unless existing fits are bad: new-bin candidate gets residual 100-item.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress);
        // If no open bin could fit, opening is necessary — soften the penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "reusable"
    // for typical item sizes should be rewarded. Class by modulo 10 bands.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty grows super-linearly for awkward leftovers
    if pr > 0 {
        let awkward = match class {
            1..=3 => 6.0,   // tiny slivers nearly unusable
            4..=6 => 2.5,
            7..=9 => 0.0,   // decent chunks
            _ => 0.0,
        };
        score += awkward * (pr as f64 / cap).sqrt();
    }

    // Perfect/near-perfect fits are gold
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward proportional to how snugly next item fits
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
            score -= 12.0 + 10.0 * snug;
        } else {
            // leftover cannot host next item: penalize mildly
            score += 4.0;
            // but if next item fits this bin's CURRENT residual alongside,
            // placing here keeps a big cavity elsewhere useful
            if bin_residual >= item_size + next_item_size {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer fuller bins when many bins are open (balance consolidation)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / cap;
    score -= 10.0 * fill_ratio * fill_ratio;

    // New-bin candidate logic: opening a bin is only attractive when the
    // item would leave an awkward residual in every existing bin, or when
    // the item is huge and would nearly fill a fresh bin.
    if bin_residual == bin_capacity {
        // baseline cost of a new bin
        score = cap as f64 * 0.9;
        if item_size >= 70 {
            score -= 25.0; // huge items belong in fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 50 {
            score -= 10.0; // pair big items in sequence
        }
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * (1.0 - progress);
        // many open bins with high mean residual -> consolidate instead
        score += (open_bins_count as f64).ln().max(0.0) * 2.0 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (small, unlikely to fit future items) are heavily penalized.
    let dead_zone_low = 0.0;
    let dead_zone_high = 20.0;
    if (post_residual as f64) > dead_zone_low && (post_residual as f64) <= dead_zone_high {
        // Quadratic penalty peaked for tiny-but-nonzero gaps
        score += (dead_zone_high - post_residual as f64) * 2.5;
    }

    // Perfect fit reward: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward if the leftover residual can still fit the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover can't fit next item: dead space penalty
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we are forced to open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open bins pressure: with many open bins, discourage spreading;
    // prefer tighter packing (larger fill => smaller post_residual already
    // handled), but add mild penalty proportional to open bins count
    // for placements that leave large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    // Make it attractive only when no good fit exists (many open bins with
    // poor fit), otherwise keep it slightly worse than a tight fit.
    if bin_residual == bin_capacity {
        // baseline for new bin
        score += 3.0;
        // if existing bins are fragmented (high mean residual spread) and
        // many bins already open, opening fresh is cheap
        if open_bins_count > 3 && mean_residual > 25.0 {
            score -= 8.0;
        }
        // last item: no reason to open a new bin
        if next_item_size == 0 {
            score += 20.0;
        }
    }

    // Slight bonus for filling a bin beyond half capacity
    if item_size >= bin_residual.min(bin_capacity) / 2 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 500.0; // chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            let slack = pr - nr;
            // reward tight two-item packing
            score -= 200.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot fit here; penalize proportionally to wasted gap
            let gap = nr - pr;
            score += gap * 2.0;
        }
    }

    // Compare post_residual against mean residual: leaving near-mean residual is neutral,
    // leaving much less wastes the bin, leaving much more is fine only if useful.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.3 && pr > 0.0 {
        score += (mean_residual * 0.3 - pr) * 1.5; // dead-space penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin leaves bad residue
    if bin_residual == bin_capacity {
        score += 250.0;
        // allow new bin if lookahead says current bins would leave big gaps anyway
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate into fewer bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (bin_residual.max(1) as f64);
    score += 30.0 * tightness;

    // Penalize dead space that is too small to be useful later (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly-ish.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.15 * gap;
        if post_residual >= next_item_size {
            score -= 12.0; // this bin likely useful next step too
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        score += 4.0 * (fitting_bins_count as f64 - 2.0); // many options -> be pickier
    }

    // Global state: many open bins with high mean residual -> prefer reusing big-residual bins.
    if open_bins_count > 4 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev; // prefer below-average residual bins (tighter ones)
        score += 1.5 * open_bins_count as f64; // pressure to consolidate
    }

    // Time horizon: early stream -> be conservative (favor new bins less); late stream -> consolidate hard.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base = 55.0 - 20.0 * progress;
        score = score.max(base) + 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 900.0;
    } else if post_residual <= 10 {
        score += 160.0 + 5.0 * (10 - post_residual) as f64;
    } else if post_residual <= 25 {
        score += 50.0 + 1.2 * (25 - post_residual) as f64;
    } else if post_residual >= 50 {
        score -= 40.0;
    }

    // Fill ratio bonus.
    let fill = (item_size as f64) / cap;
    score -= 55.0 * fill;

    // Consolidation pressure, softened as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.8 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Lookahead: exact match next step is gold.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 420.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 22.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.0 + 0.4 * (13.0 - slack);
            }
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 18.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.25 * (10 - r2) as f64;
            }
            let gap = r2;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / cap);
        }
    }

    // Mean-residual balance: avoid hoarding space far above the mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.35 * diff.abs();

    // Don't burn a big bin on a tiny item unless few bins are open anyway.
    if item_size <= 20 && bin_residual >= 80 && open_bins_count > 4 {
        score += 40.0;
    }

    // Late-stream tightness.
    if open_bins_count > 8 && post_residual > 0 && post_residual < item_size {
        score += 2.5;
    }

    // Tiny dead gap with many fitting options: mild extra penalty.
    if post_residual > 0 && post_residual < 21 {
        score += 10.0 + 0.5 * (21 - post_residual) as f64;
    }
    if post_residual < 31 && fitting_bins_count > 3 && post_residual > 0 {
        score += 1.5;
    }

    // New-bin arbitration.
    if bin_residual == bin_capacity {
        score += 9.0 + 0.05 * open_bins_count as f64;
        if progress < 0.15 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);
    score -= 8.0 * pr_norm * (1.0 - progress) * (1.0 - progress);
    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 10.0 * tightness * tightness * (0.3 + progress);
    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Lookahead: penalize if post_residual cannot fit the next item but is small (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx && pr > 0.0 {
            score += 6.0 * (nx - pr) / cap * (1.0 + progress);
        } else if pr >= nx {
            score -= 3.0 * (nx / cap) * (1.0 - progress);
        }
    }
    // Mild penalty for leaving residual far from mean residual (fragmentation spread)
    score += 0.05 * (pr - mean_residual).abs();
    // Penalize opening a new bin when good existing options exist
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: unusable slivers are pure waste; penalize non-linearly.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Reward tight fits (quadratic near-perfect packing bonus).
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage new bins when many are open, scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate handling: offset base cost only when fragmentation is high.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 + 0.5 * fragmentation;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.25 {
            score -= 15.0;
        }
        if post_residual as f64 > mean_residual * 1.5 && next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
        // Suppress new-bin opening when plenty of open bins already fit the item.
        if fitting_bins_count >= 2 {
            score += 30.0;
        }
    }

    // Lookahead: perfect two-item pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            // Two-step lookahead: residual after next item pairs with item itself.
            if gap == next_item_size as u32 {
                score -= 3.0;
            } else if gap > 0 && gap < 10 {
                score -= 2.0 + 0.2 * (10 - gap) as f64;
            }
            // Half-slack trap: leftover barely too small to reuse.
            if slack > 0.0 && slack < next_item_size as f64 && slack * 2.0 > next_item_size as f64 {
                score += 1.5;
            }
            // Dead-space ratio coupling — penalize bins whose post-fit leftover
            // is a large fraction of capacity while many alternatives exist.
            if fitting_bins_count > 2 && post_residual as f64 > cap * 0.45 {
                score += 2.0 + 2.0 * (post_residual as f64 / cap);
            }
            // COMBINED: fine-grained residual coupling with lookahead — reward
            // bins whose post-residual lands in the reusable mid-band (>= 21)
            // when the next item can consume most of it.
            if post_residual >= 21 && next_item_size >= 8 && (post_residual as f64) <= cap * 0.6 {
                let reuse = next_item_size as f64 / post_residual as f64;
                if reuse > 0.5 {
                    score -= 3.0 * reuse;
                }
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Prefer bins below mean residual (keep large residuals for large items).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Crowding: when many bins fit, slightly penalize tight post-residuals to
    // avoid hoarding near-perfect bins needed for exact pairings.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Reward completing this bin when the next item can also fit the leftover.
    if post_residual <= 4 && next_item_size > 0 && next_item_size >= post_residual {
        score -= 6.0;
    }

    // COMBINED: guard against creating stranded slivers that no typical item
    // (>= 10) can ever reuse, scaled by how many alternatives exist.
    if post_residual > 0 && post_residual < 10 && fitting_bins_count > 1 && next_item_size > post_residual {
        score += 4.0 + 0.5 * (10 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual;
    let mut score = pr as f64;
    let is_new = bin_residual == bin_capacity;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut look = 0.0;

    if pr == 0 {
        // perfect closure: bin exactly filled
        look -= 1000.0;
    } else if next_item_size > 0 {
        let n = next_item_size;
        if n == pr {
            // exact harmonic pairing: next item fills this residual precisely
            look -= 400.0;
        } else if n < pr {
            // residual stays usable by the lookahead item
            look -= 30.0 + (pr - n) as f64 * 0.5;
        } else {
            // dead space: next item cannot use it; penalize by decade class
            // (integer division of post_residual into capacity-fraction classes)
            let cls = (pr / 10) as f64;
            look += (n - pr) as f64 * 0.8 + cls * 4.0;
            // round residuals (multiples of 10) are slightly more reusable
            if pr % 10 == 0 {
                look -= 5.0;
            }
        }
    }

    // favor bins that are already fuller than the average open bin
    let fullness = mean_residual - bin_residual as f64;
    if fullness > 0.0 {
        score -= fullness * 0.3;
    }

    if is_new {
        // brand-new empty bin: dampen lookahead bonuses so tight open-bin fits
        // and exact pairings in existing bins still win, but poor fits lose
        look *= 0.5;
        score += look
            + 20.0                      // fresh residual is maximally flexible
            - item_size as f64 * 0.1    // large items keep a big usable residual
            + open_bins_count as f64 * 0.5  // consolidation pressure
            + t * 10.0;                 // late in the stream, prefer existing bins
    } else {
        // last chance: only this open bin fits — strongly avoid opening a new bin
        if fitting_bins_count == 1 {
            look -= 60.0;
        }
        score += look;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance with graded penalty.
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving space exactly or nearly fitting next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 38.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Two-step lookahead: residual after hypothetically placing next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let r2 = post_residual - next_item_size;
        if r2 == next_item_size {
            score -= 3.0;
        } else if r2 > 0 && r2 < 10 {
            score -= 2.0 + 0.2 * (10 - r2) as f64;
        }
    }

    // Penalize half-empty-looking slack that can't hold next item usefully.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
            score += 1.5;
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.3;
        // But allow a new bin when all open fits are terrible.
        if post_residual < item_size / 2 && open_bins_count > 8 {
            score -= 6.0;
        }
    }

    // Many open bins with a poor fit: mild penalty to consolidate.
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space penalty: small unusable gaps are costly.
        let pr = post_residual as f64;
        // Gap is "unusable" if smaller than the smallest plausible item (~10)
        // and cannot host the lookahead item either.
        let min_item = 10.0f64;
        let gap_unusable = pr < min_item;
        let gap_blocks_next = next_item_size > 0 && (pr as u32) < next_item_size;
        if gap_unusable {
            score += 40.0;
        }
        if gap_blocks_next {
            score += 15.0 + 0.3 * (next_item_size as f64 - pr);
        }
        // Non-linear waste term: penalize proportionally wasted capacity.
        score += (pr / cap) * (pr / cap) * 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins tighter than the mean residual (good fits cluster together).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Lookahead synergy: reward leaving exactly the lookahead size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when item nearly fills it or existing
    // fits are poor. Penalize opening new bins mildly, more when few open bins.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 20.0 - 25.0 * fill; // near-full items in fresh bin are great
        if open_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0; // fresh bin can also host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance with graded penalty.
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: exact fit strongly rewarded; tight slack also rewarded.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 38.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            // Two-item lookahead: residual after placing next item.
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 3.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.2 * (10 - r2) as f64;
            }
            // Avoid leaving slivers just above half of the next item.
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            let slack2 = post_residual - next_item_size;
            if slack2 > 0 && slack2 < next_item_size && slack2 * 2 > next_item_size {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Pressure from number of open bins: discourage spreading.
    score += open_bins_count as f64 * 0.6;
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist, scaled by mean slack.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.3;
    }

    // Many alternatives with a tight post-fit: slight penalty to prefer roomier bins.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: baseline score so it's chosen only when open bins are bad fits.
    if bin_residual == bin_capacity {
        let mut nb = 95.0;
        // Opening a new bin is cheap when many bins already open / stream late.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb -= 25.0 * progress;
        nb -= 2.0 * (open_bins_count.min(20) as f64);
        // Last-chance bin: strongly prefer using it over opening a new one.
        if fitting_bins_count == 1 {
            nb += 400.0;
        }
        // If item exactly fills a new bin, opening is great.
        if item_size == bin_capacity {
            nb -= 200.0;
        }
        return nb;
    }

    // Perfect fill: item exactly consumes the bin.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // exact 2-step chain
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize residual that is nearly-but-not usable.
            let waste = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 60.0; // tiny dead space
            } else if waste <= 10.0 {
                score += 80.0; // frustrating near-miss
            } else {
                score -= 20.0; // large residual still generally useful
            }
        }
    }

    // Reward bins with residual below mean (tighter bins get emptied first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 250.0;
        // But if the fit is terrible (huge dead space), soften the bonus.
        if post_residual > 0 && post_residual < 10 {
            score += 120.0;
        }
    }

    // Mild preference for tighter fits overall.
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Slight bias toward using more-open-bin states to consolidate.
    score -= 0.1 * (open_bins_count.min(30) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: unusable slivers are pure waste; penalize non-linearly.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Reward tight fits (quadratic near-perfect packing bonus).
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly prefer the only fitting open bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage new bins when many are open, scaled by progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate handling: offset base cost only when fragmentation is high.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 + 0.5 * fragmentation;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.25 {
            score -= 15.0;
        }
        if post_residual as f64 > mean_residual * 1.5 && next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Lookahead: perfect two-item pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            // Two-step lookahead: residual after next item pairs with item itself.
            if gap == next_item_size as u32 {
                score -= 3.0;
            } else if gap > 0 && gap < 10 {
                score -= 2.0 + 0.2 * (10 - gap) as f64;
            }
            // Half-slack trap: leftover barely too small to reuse.
            if slack > 0.0 && slack < next_item_size as f64 && slack * 2.0 > next_item_size as f64 {
                score += 1.5;
            }
            // Dead-space ratio coupling — penalize bins whose post-fit leftover
            // is a large fraction of capacity while many alternatives exist.
            if fitting_bins_count > 2 && post_residual as f64 > cap * 0.45 {
                score += 2.0 + 2.0 * (post_residual as f64 / cap);
            }
            // COMBINED: fine-grained residual coupling with lookahead — reward
            // bins whose post-residual lands in the reusable mid-band (>= 21)
            // when the next item can consume most of it.
            if post_residual >= 21 && next_item_size >= 8 && (post_residual as f64) <= cap * 0.6 {
                let reuse = next_item_size as f64 / post_residual as f64;
                if reuse > 0.5 {
                    score -= 3.0 * reuse;
                }
            }
            // NEW: exact double-pairing — post-residual exactly twice the next item
            // means two future items can tile the leftover perfectly.
            if gap > 0 && next_item_size >= 4 && gap == 2 * next_item_size {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Prefer bins below mean residual (keep large residuals for large items).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Crowding: when many bins fit, slightly penalize tight post-residuals to
    // avoid hoarding near-perfect bins needed for exact pairings.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Reward completing this bin when the next item can also fit the leftover.
    if post_residual <= 4 && next_item_size > 0 && next_item_size >= post_residual {
        score -= 6.0;
    }

    // COMBINED: guard against creating stranded slivers that no typical item
    // (>= 10) can ever reuse, scaled by how many alternatives exist.
    if post_residual > 0 && post_residual < 10 && fitting_bins_count > 1 && next_item_size > post_residual {
        score += 4.0 + 0.5 * (10 - post_residual) as f64;
    }

    // NEW: residual-band conservation — when the current residual is already a
    // "golden" reusable size for the next item, prefer consuming it here rather
    // than fragmenting another bin; scaled by open-bin pressure.
    if bin_residual < bin_capacity && next_item_size > 0 && bin_residual == next_item_size && open_bins_count > 2 {
        score -= 8.0;
    }

    // NEW: late-stream tightening — as the stream nears its end, favor bins
    // whose post-residual is small enough that leftover waste is bounded.
    if progress > 0.7 && post_residual > 0 && (post_residual as f64) < cap * 0.2 {
        score -= 2.0 * (1.0 - post_residual as f64 / (cap * 0.2));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness).powi(6);

    // Penalize large dead space quadratically.
    score += 0.35 * tightness * tightness * (bin_capacity as f64);

    // Lookahead: bonus if next item exactly fills post_residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Reward leaving space the next item can partially use.
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - pair_waste / (bin_capacity as f64)).powi(3);
        } else {
            // Penalize leaving space that next item cannot use at all.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early
    // or open bins have poor residuals relative to the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = (mean_residual - item_size as f64).max(0.0);
        let mut new_bin_score = 70.0 + 40.0 * progress;
        new_bin_score -= 0.5 * poor_fits; // if open bins fit poorly, new bin less bad
        new_bin_score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        score = score.max(new_bin_score);
        score += new_bin_score * 0.5;
    }

    // Mild global pressure: when many bins are open, prefer filling existing ones.
    score += 0.15 * (open_bins_count as f64).sqrt();

    // Time horizon: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), with non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, waste is penalized more heavily.
    let waste = pr / cap;
    score += 20.0 * waste * waste * (0.5 + progress);

    // Penalize bins that leave a residual the next item cannot use
    // (smooth interaction rather than hard threshold).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 8.0 * (gap / cap) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight preference for bins with residuals below the mean (consolidating waste).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild pressure to avoid proliferating open bins late in the stream.
    score += 0.01 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into modulo buckets.
    // Residuals that are multiples of 10 are "reusable" (item sizes 10..80 often
    // align to decade grid); residuals in low classes are near-dead.
    let pr = post_residual;
    let class = pr % 10;
    match class {
        0 => score -= 6.0,               // perfectly reusable residual
        1 | 2 | 8 | 9 => score += 4.0,   // nearly dead slivers
        3 | 4 | 6 | 7 => score += 1.5,   // awkward classes
        _ => {}                          // class 5: half-space, moderately useful
    }

    // Integer-division thresholds on post_residual: chunked reusability.
    let chunks = pr / 10;
    score -= (chunks as f64) * 1.2;

    // Perfect fit: post_residual zero is ideal.
    if pr == 0 {
        score -= 20.0;
    } else if pr < 10 {
        // creates unusable dead space below minimum item size (1..100 but small)
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // next item fits: residual class harmony
            let harmony = (pr % 10 == next_item_size % 10) as i32;
            score -= 5.0 + harmony as f64 * 3.0;
        } else {
            // next item will not fit here: slight penalty proportional to overshoot
            let overshoot = (next_item_size - pr) as f64;
            score += (overshoot / 100.0).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
        // prefer new bin only when mean residual is small (bins nearly full)
        score += 15.0 + (mean_residual / bin_capacity as f64) * 20.0 - progress * 3.0 - openness.min(5.0);
    }

    // Mild preference for fuller bins overall.
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Mean-residual coupling: when open bins are generally full, conserve them.
    if (mean_residual / bin_capacity as f64) < 0.15 && pr > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // A gap is "dead" if it cannot hold even the smallest plausible item (size 1),
    // but practically we penalize gaps too small for the lookahead or typical small items.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(20) } else { 20 };
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual tightly matches the item (low waste relative to residual).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow here: penalize slightly more if gap is tiny.
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize opening new bins / spreading items thinly).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // If this bin is the last chance to fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Deviation from mean residual: prefer bins that are either near-mean
    // (balanced packing) or far below mean (already dense).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // New-bin candidate: empty bin should only win when nothing decent is open.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
    }

    score
}

