    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: grows with stream progress and open-bin count,
    // so a fresh bin is only chosen when existing fits are genuinely poor
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * progress + 1.5 * open_bins_count as f64;
    }

    score
}

