    // Lookahead coupling: reward post_residual that still accommodates the next item,
    // penalize post_residual that is awkwardly small but nonzero (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - post / cap) * (1.0 - progress);
