    // item-size classes (e.g. multiples of 10, 5, 25) are more likely to
    // be exactly filled by future items.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 {
        score -= 2.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Odd, prime-ish residuals are dead space magnets.
    if post_residual % 2 == 1 && post_residual > 10 {
        score += 4.0;
    }

