            // Next item won't fit here; penalize more if this bin was
            // the only fitting option (last-chance bin wasted).
            score += 5.0;
            if fitting_bins_count == 1 {
                score += 8.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_residual / 2 {
        score -= 7.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when
    // no open bin offers a decent fit or residuals are all tiny.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        // With healthy open residual mass, prefer existing bins.
        score += 30.0 * (1.0 - pressure);
        // Late in the stream, opening fresh bins is less useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Small item into a fresh bin wastes most of it.
        score += 0.3 * (cap - item_size as f64);
    }

    // Mild diversity pressure: many open bins with large mean residual
    // means we should consolidate into fuller bins.
    if open_bins_count > 4 && mean_residual > 0.5 * cap {
        score += 2.0;
    }

    score
}

