            score -= (pr - nx).min(30.0) * 0.3;
        } else {
            score += (nx - pr) * 0.5;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * ((fitting_bins_count - 1) as f64).ln().max(0.0);
    }

    // Many open bins with high mean residual: discourage spreading
    if open_bins_count > 1 && mean_residual > 0.0 {
        score += (open_bins_count as f64).ln() * (mean_residual / cap) * 2.0;
