    }

    // Tight fits are excellent
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= eighth {
        score -= 25.0;
    }

    // Integer-division threshold on next item: if next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic coupling: next item leaves a clean class too
            let next_post = post_residual - next_item_size;
            if next_post % quarter.max(1) == 0 {
                score -= 12.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (post_residual as f64) * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly unless current fit is bad
    if bin_residual == bin_capacity {
        score += 35.0;
        if post_residual > bin_capacity / 2 {
            score += 10.0;
        }
    }

    // Stream progression: early on, prefer tight packing into few bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    // Prefer bins whose residual is below mean (consolidating small residuals)
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: small unusable gaps heavily penalized, scaled.
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 38.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 3.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.2 * (10 - r2) as f64;
            }
            if slack * 2.0 > next_item_size as f64 && slack < next_item_size as f64 {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Pressure from number of open bins: discourage spreading.
    score += open_bins_count as f64 * 0.6;
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.3;
    }

    if post_residual >= bin_capacity {
        if next_item_size > 0 && next_item_size <= bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
            score -= 3.0;
        }
    } else if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item
    // (or for the lookahead item) are heavily penalized.
    let min_useful = 1u32;
    if post_residual < min_useful {
        score += 1000.0;
    }

    // Lookahead coupling: a residual that cannot host the next item is dead space
    // with high probability; penalize proportionally to how "close" it is to fitting.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that remain useful for the lookahead item.
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).sqrt();
        } else {
            let gap = (next_item_size - post_residual) as f64;
            // Penalty grows steeply as the gap approaches the lookahead size.
            score += 15.0 + 10.0 * (1.0 - gap / next_item_size as f64);
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate and reward reuse).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: score scales with open bins count and stream progress.
        score += 20.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
        // A new bin is acceptable if no tight fits exist anywhere.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Reward filling bins with high fill ratio.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // Mean-residual coupling: bins far below mean residual are poor fits;
    // prefer bins whose residual is close to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    // Mild preference for low-residual bins overall (waste minimization).
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

