    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 20.0 + 0.5 * fragmentation;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.25 {
            score -= 15.0;
        }
        if post_residual as f64 > mean_residual * 1.5 && next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
        // New-bin lookahead: opening a fresh bin is bad if the next item is small
        // and could easily consume some open residual elsewhere.
        if next_item_size > 0 && (next_item_size as f64) <= mean_residual * 0.5 {
            score += 6.0;
        }
    }

    // Lookahead: perfect two-item pairing.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let gap = post_residual - next_item_size;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
