    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Crowding guards.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Reward completing this bin when the next item can also fit the leftover.
    if post_residual <= 4 && next_item_size > 0 && next_item_size >= post_residual {
        score -= 6.0;
    }

    // Guard against stranded slivers that no typical item can reuse.
    if post_residual > 0 && post_residual < 10 && fitting_bins_count > 1 && next_item_size > post_residual {
        score += 4.0 + 0.5 * (10 - post_residual) as f64;
    }

    score
}

