pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base cost: wasted space after placement, normalized.
    let mut score = post / cap;

    // Quadratic penalty on dead space: small residuals are cheap, large ones costly.
    score += 0.9 * (post / cap) * (post / cap);

    // Smooth coupling of dead space with stream progress: as the stream advances,
    // waste becomes harder to recover, so penalize growing residuals more.
    score += 1.4 * (post / cap).powi(3) * (0.35 + 0.65 * progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    score -= 0.8 * (1.0 - (post / cap)).powi(2);

    // Lookahead: if the next item fits exactly into post_residual, reward strongly
    // (smooth interaction term); otherwise mild penalty proportional to mismatch.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt) / cap;
        if diff >= 0.0 {
            score -= 0.6 * (1.0 - 2.0 * diff).max(-1.0) * (1.0 - progress * 0.5);
        } else {
            score += 0.25 * (-diff);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5;
    }

    // New-bin candidate handling: empty bins are attractive only when existing bins
    // would leave large, unusable residuals. Smoothly gate by post_residual.
    if bin_residual == bin_capacity {
        score = 1.6 + 0.8 * progress - 0.5 * (post / cap);
        if fitting_bins_count == 1 {
            score += 3.0; // never open a new bin when it's the last chance elsewhere
        }
    }

    // Mild preference for balancing residual mass across open bins.
    score += 0.1 * (post - mean_residual) / cap;

    // Slight late-stream conservatism: keep bins tighter as stream ends.
    score += 0.3 * progress * (post / cap);

    score
}

