pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space.
    // Class 0: post_residual == 0 -> perfect fit, huge reward.
    // Class 1: small leftovers (1..=10) -> near-perfect, strong reward.
    // Class 2: medium (11..=30) -> still likely fillable.
    // Class 3: large (>30) -> dead-space risk, penalize.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    } else if post_residual <= 30 {
        score -= 100.0;
    } else {
        score += 50.0;
    }

    // Harmonic class via modular arithmetic: leftover divisible by common
    // item-size granularities (5, 10) tends to be refilled by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 60.0;
        } else if post_residual % 5 == 0 {
            score -= 30.0;
        } else {
            score += 15.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / cap_f);
        } else {
            score += 40.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // New-bin candidate: it has full residual; penalize opening it unless
    // the current fit would leave a really bad (large, non-harmonic) gap.
    if bin_residual == bin_capacity {
        score += 250.0;
        if post_residual <= 10 {
            score -= 200.0; // placing here is fine anyway (won't happen on empty bin, guard)
        }
        // If the item is large relative to capacity, opening fresh is fine.
        let frac = item_size as f64 / cap_f;
        if frac > 0.7 {
            score -= 120.0;
        }
    }

    // Stream progression: late in stream, consolidate into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 80.0 * progress;

    // Prefer bins with below-mean residual (tighter packing) mildly.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild penalty proportional to number of open bins to discourage sprawl.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold a future item
    // (items can be as small as 1, so treat very small gaps as near-dead) are
    // penalized super-linearly, while large comfortable residuals are fine.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 120.0;
    } else {
        // Mildly reward larger usable leftovers.
        score -= 0.35 * post_residual as f64;
    }

    // Reward tight fits relative to current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading onto new bins,
    // but allow new bins when existing ones are crowded.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by how much room
        // already exists in open bins (mean_residual).
        score += 25.0 + 0.6 * pressure + 0.4 * mean_residual.max(0.0);
        // If nothing open fits well (this is the lone candidate), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Placing into an existing bin relieves pressure.
        score -= 0.3 * pressure;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 50.0;
        } else {
            score -= 15.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual < 10 {
        // Next item cannot use the tiny gap: dead space confirmed.
        score += 30.0;
    }

    score
}

