        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open new bins when few are open (early stream).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If open bins are on average full, new bin is more acceptable.
        score -= 0.3 * (bin_capacity as f64 - mean_residual).max(0.0);
