    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, but with non-linear curvature
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, small residuals are tolerable; late in the stream,
    // large residuals are heavily penalized (dead space).
    let curvature = 1.0 + 3.0 * progress * progress;
    score += norm_pr * norm_pr * 40.0 * curvature;

    // Reward tight fits (small post_residual) more as progress increases
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize relative to mean residual: bins with much-above-average
    // residual are better targets; below-average residual bins penalized.
    let mr = if mean_residual.is_finite() { mean_residual } else { cap };
    score += 0.3 * (mr - pr);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 10.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // smooth penalty growing with mismatch
        let gap = (next_item_size as f64 - pr) / cap;
        score += 8.0 * gap * gap;
    }

    // Mild penalty for many open bins, encouraging consolidation
    score += 0.5 * open_bins_count as f64 * progress;

    // Slight preference to fill bins with less residual overall
    score += 0.1 * (bin_residual as f64 - item_size as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let post_class = (post_residual % quarter.max(1)) as f64;
    score += post_class * 0.35;

    // Penalize residuals that fall into "dead" classes: 1..=5 unusable slivers
    if post_residual > 0 && post_residual <= 5 {
        score += 40.0;
    }

    // Reward near-perfect fits (post_residual in tiny-but-usable band)
    if post_residual > 5 && post_residual <= 15 {
        score -= 25.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next_item_size divides-ish post_residual
            let m = post_residual % next_item_size.max(1);
            score -= 30.0 - (m as f64) * 0.5;
        } else {
            score += 12.0;
        }
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer opening a new bin when current best
    // fit would waste a lot, or when mean residual is already high
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        let pressure = mean_residual / cap;
        score = waste + 25.0 * pressure;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 15.0; // big item coming, fresh bin attractive
        }
        if step_index as f64 / total_items.max(1) as f64 > 0.8 {
            score += 10.0; // late stream: consolidate instead of opening
        }
    }

    // Mild consolidation pressure when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Integer-division threshold: reward leaving residuals that are multiples of 10
    if post_residual % 10 == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance with graded penalty (borrowed graded ramp).
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    } else if post_residual >= 21 && post_residual < 30 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: exact-fit strong reward, tight slack reward, overflow penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 38.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 7.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 3.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.2 * (10 - r2) as f64;
            }
            if r2 > 0 && r2 < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - r2) as f64;
            }
            if slack > 0.0 && slack < next_item_size as f64 && slack * 2.0 > next_item_size as f64 {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap);
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.6;

    // Many open bins with a poor fit: mild penalty to prefer better placements.
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.3;
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: prefer consolidating into existing bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current item barely fits anywhere useful.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Late in the stream: be more conservative, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match: big bonus (subtract heavily).
        if diff < 0.5 {
            score -= 60.0;
        } else {
            // Penalize mismatch scaled by how far post_residual is from next item,
            // especially when post_residual < next_item (dead space next item can't use).
            if (post_residual as i64) < (next_item_size as i64) {
                score += diff * 1.5;
            } else {
                score += diff * 0.6;
            }
        }
        // Prefer bins whose post_residual is close to mean residual of open bins
        // (keeps distribution balanced), mild coupling.
        score += (post_residual as f64 - mean_residual).abs() * 0.15;
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless waste is huge).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * post_residual as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so later in the stream
    // and when many bins are already open (amortization).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // But if next item exactly fills a fresh bin minus this item, allow opening.
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) == 0 {
            score -= 100.0;
        }
    }

    // Small bonus for tight fits overall (low post residual already favored via base).
    if post_residual <= 10 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post-residual), with a convex penalty
    // so that small leftovers are tolerated but large dead space is punished.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powf(1.8) * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Penalize residuals that are too small to be useful for typical items
    // (dead space): residuals in a "useless" band get a bump.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly reward; if next item cannot fit, mildly penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 - 0.15 * slack as f64;
        } else {
            score += 8.0;
        }
        // If post-residual is a "niche" size that only this next item fills.
        if (pr - nxt).abs() < 1.0 {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }
    // Conversely, if many bins fit, we can afford to be picky: add a small
    // penalty so only the tightest wins.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count.min(10) as f64 - 3.0);
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer filling existing bins rather than spreading.
    let mr = mean_residual;
    if mr > 30.0 {
        score -= 0.10 * (mr - 30.0);
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep options open); late in the stream, consolidate tightly.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        1.0
    };
    score -= 10.0 * progress; // late stream: favor existing bins
    score += 6.0 * (1.0 - progress); // early stream: slight preference to explore

    // New-bin candidate handling: an empty bin has huge post_residual, but we
    // must decide when opening a new bin beats a poor fit. Base penalty for
    // opening a new bin, discounted when current fit is bad or stream is early.
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (pr / bin_capacity as f64);
        // If no open bin fits at all, opening is necessary.
        let must_open = fitting_bins_count == 0;
        let poor_fit_elsewhere = pr > 40.0; // large dead space if placed here... (this IS the new bin)
        let _ = poor_fit_elsewhere;
        let open_penalty = 25.0
            - 15.0 * (1.0 - progress)
            - (if must_open { 100.0 } else { 0.0 })
            - 0.2 * (open_bins_count as f64).max(0.0).min(20.0) * 0.0;
        score = score.max(0.0) + open_penalty;
        // A new bin is attractive if the item is large relative to capacity
        // (large items pair well with fresh bins).
        let size_frac = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * size_frac * (1.0 - fit_quality.abs() * 0.0);
        // If next item is large too, a fresh bin may host a good pair.
        if next_item_size >= 50 && next_item_size <= bin_residual {
            score -= 8.0;
        }
    }

    // Mild penalty for proliferating bins when residuals are still usable.
    if open_bins_count > 5 && mean_residual > 20.0 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 20 {
        // Dead-space avoidance: small remainders are costly.
        score += 13.0 + 0.6 * (20 - post_residual) as f64;
    } else if post_residual <= 40 {
        score += 4.0 + 0.4 * (40 - post_residual) as f64;
    } else if post_residual >= 60 {
        score -= 20.0;
    }

    // Fill ratio bonus.
    let fill = (item_size as f64) / cap;
    score -= 55.0 * fill;

    // Consolidation pressure, softened as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 1.8 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Lookahead: fine-grained residual anticipation.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 12.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.25 * (10 - r2) as f64;
            }
            let gap = r2;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            // awkward half-slack: gap too small to reuse well
            if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / cap);
        }
    }

    // Mean-residual balance: avoid hoarding space far above the mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.35 * diff.abs();

    // Don't burn a big bin on a tiny item unless few bins are open anyway.
    if item_size <= 20 && bin_residual >= 80 && open_bins_count > 4 {
        score += 45.0;
    }

    // Late-stream tightness.
    if open_bins_count > 8 && post_residual > 0 && post_residual < item_size {
        score += 2.5;
    }

    // Tiny dead gap with many fitting options: mild extra penalty.
    if post_residual < 31 && fitting_bins_count > 3 && post_residual > 0 {
        score += 1.5;
    }

    // New-bin arbitration.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if progress < 0.15 {
            score -= 10.0;
        }
        // fresh bin attractive only if it can host the next item too
        if next_item_size > 0 && next_item_size <= bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual in [0,1]
    let pr = (post_residual as f64) / (bin_capacity as f64);
    let pr2 = pr * pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, small residuals are prized more (dead space penalized).
    let progress_coupling = pr2 * (1.0 - progress) - pr * progress * (1.0 - pr);
    score += 20.0 * progress_coupling;

    // Reward tight fits more strongly as stream progresses (smooth polynomial in fit quality)
    let fit_quality = 1.0 - pr; // fraction of bin filled by item
    score -= 15.0 * fit_quality * fit_quality * (0.5 + 0.5 * progress);

    // Penalize creating residuals that cannot fit the next item (smooth falloff)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - post_residual as f64;
        if gap > 0.0 {
            let frac = gap / (bin_capacity as f64);
            score += 10.0 * frac * frac * (1.0 - progress);
        } else {
            let slack = -gap / (bin_capacity as f64);
            score -= 5.0 * slack * (1.0 - slack);
        }
    }

    // Last-chance bonus: only one bin fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Slight penalty when bin residual deviates from mean residual (keeps bin pool balanced)
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 3.0 * dev * dev;

    // New-bin candidate: make it moderately attractive only when residual is tiny
    if bin_residual == bin_capacity {
        let tight = (item_size as f64) / (bin_capacity as f64);
        score += 6.0 * (1.0 - tight) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: quantize into capacity fractions.
    let q = (post_residual * 4) / bin_capacity; // 0..=3 harmonic class
    match q {
        0 => score -= 30.0,                    // near-perfect fit
        1 => score -= 8.0,                     // good fit
        2 => score += 5.0,                     // mediocre
        _ => score += 15.0,                    // large dead space
    }

    // Modulo-class coupling: residual classes divisible by common item sizes
    // (10/20/25/50) are more likely to be filled later.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 50 == 0 { score -= 5.0; }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 12.0 - (gap as f64).min(12.0);
        if gap == 0 { score -= 20.0; }
    } else if next_item_size > post_residual {
        score += 6.0; // next item cannot use this bin's remainder
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins; encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: keep it slightly unattractive unless existing bins
    // have poor fits (large mean residual means bins are mostly empty).
    if bin_residual == bin_capacity {
        score += 18.0;
        if mean_residual < 0.35 * bin_capacity as f64 && fitting_bins_count > 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 10.0; // fresh bin can't take next item either
        }
    }

    // Stream progression: early on, be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
