        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 20.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.25 * (10 - r2) as f64;
            }
            let gap = r2;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
                score += 1.5;
            }
            // dead-space guard: leaving a gap smaller than typical item is wasted
            if r2 > 0 && r2 < 8 && next_item_size > r2 + 8 {
                score += 3.0;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 6.0 * (over / cap);
        }
    }

    // Mean-residual balance: avoid hoarding space far above the mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.4 * diff.abs();

    // Don't burn a big bin on a tiny item unless few bins are open anyway.
    if item_size <= 20 && bin_residual >= 80 && open_bins_count > 4 {
        score += 45.0;
    }

    // Late-stream tightness.
    if open_bins_count > 8 && post_residual > 0 && post_residual < item_size {
        score += 3.0;
    }

    // Tiny dead gap with many fitting options: mild extra penalty.
    if post_residual < 31 && fitting_bins_count > 3 && post_residual > 0 {
        score += 1.5;
    }

    // Prefer bins whose post-residual can still host the next item (chainability).
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        score -= 4.0 * (next_item_size as f64 / cap);
    }

    // New-bin arbitration.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if progress < 0.15 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
            score -= 3.0;
        }
        // discourage new bin when a decent existing fit exists
        if fitting_bins_count > 1 {
            score += 6.0 + 0.5 * fitting_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // A residual that cannot fit even the smallest plausible item is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 25 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < 40 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize waste relative to capacity: bigger item fill => better.
    score -= item_size as f64 * 0.5;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would NOT fit post-residual but would fit a fresh bin, penalize.
    if next_item_size > bin_residual {
        score += 5.0;
    }

    // New-bin candidate: prefer it only when open bins are crowded and fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 10.0 + open_bins_count as f64 * 2.0 + progress * 5.0;
        // If no open bin fits, opening is attractive.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance: small unusable gaps heavily penalized (scaled by tightness).
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 38.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - 5.0 * (slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            // Two-step lookahead: residual after hypothetically placing next item.
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 3.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.2 * (10 - r2) as f64;
            }
            if slack > 0.0 && slack < next_item_size && slack * 2 > next_item_size {
                score += 1.5;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 10.0 + 4.0 * (over / cap);
        }
    }

    // Pressure from many open bins: discourage spreading.
    score += open_bins_count as f64 * 0.6;
    if open_bins_count > 8 && post_residual < item_size {
        score += 2.5;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.3;
    }

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Fragmentation risk among many candidates.
    if post_residual < 31 && fitting_bins_count > 3 {
        score += 1.5;
    }

    score
}

