pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a quadratic dead-space penalty.
    let dead = post_residual as f64;
    score += 0.35 * dead * dead / bin_capacity as f64;

    // Lookahead: dead space is only wasted if the next item cannot use it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual is reusable by the next item: reward this bin.
            score -= 6.0 + 0.25 * next_item_size as f64;
        } else {
            // Dead space the next item cannot fill: penalize proportionally.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Crowding pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64) * 0.05);
    if bin_residual < bin_capacity {
        score -= 3.0 * pressure;
    }

    // Global residual alignment: bins with residuals near the mean are "typical";
    // reward keeping residual distribution coherent.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Time horizon: early in the stream, be conservative (favor new bins for large
    // future flexibility); late in the stream, squeeze everything into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it, more so late in the stream.
        score += 10.0 + 25.0 * progress;
        // Exception: if item leaves a large awkward residual and no other bin fits well,
        // opening fresh is fine — the base post_residual already reflects that.
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // Existing bin: reward usage more strongly as stream progresses.
        score -= 4.0 * progress;
    }

    // Small tie-breaker favoring fuller bins.
    score -= 0.01 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let base = post / cap;
    let sharp = base * base * (1.0 + 2.0 * base);

    // Non-linear coupling of post_residual with stream progress:
    // early on tolerate slack; later demand tighter packing.
    let progress_coupling = sharp * (1.0 + 3.0 * progress * progress);

    // Reward using an existing bin: penalty for opening a new bin grows with progress.
    let new_bin_penalty = if bin_residual == bin_capacity {
        0.8 + 1.2 * progress + 0.5 * (open_bins_count as f64).ln().max(0.0)
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -0.6 * (1.0 + progress)
    } else {
        0.0
    };

    // Dead-space penalty: post_residual too small for typical future items.
    let dead = if post > 0.0 && post < 10.0 { (10.0 - post) * 0.05 } else { 0.0 };

    // Lookahead: reward leaving room for the next item exactly.
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post - nx).abs();
        -0.15 * (1.0 - diff / cap).max(0.0) * (1.0 + progress)
    } else {
        0.0
    };

    // Slight preference for bins with below-average residual (consolidate slack).
    let mean_pull = if bin_residual != bin_capacity {
        0.05 * ((mean_residual - bin_residual as f64) / cap)
    } else {
        0.0
    };

    let mut score = progress_coupling * cap * 0.1 + new_bin_penalty + dead + mean_pull + lookahead + last_chance;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter capacity classes (1..=4)
    let item_class = ((item_size * 4 + bin_capacity - 1) / bin_capacity).max(1);
    // Harmonic class of the residual space left behind
    let post_class = ((post_residual * 4 + bin_capacity - 1) / bin_capacity).max(1);

    // Reward placements where the residual's class is at least the item's class
    // (residual can still host same-or-larger-class items later).
    score -= 8.0 * (post_class as f64) / (item_class as f64);

    // Perfect fit bonus: post_residual is a multiple of common item sizes
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Penalize dead space: post_residual in awkward low band (1..=9) is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let nxt_class = ((next_item_size * 4 + bin_capacity - 1) / bin_capacity).max(1);
            if nxt_class <= post_class {
                score -= 10.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (large dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate: penalize opening a fresh bin when good fits exist,
    // but allow it if all open bins would leave tiny dead space.
    if bin_residual == bin_capacity {
        score += 25.0;
        score -= 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Late in the stream, prefer compacting into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / cap);

    // Prefer bins whose residual is close to the mean (balanced packing)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are almost unusable -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    } else if post_residual > 10 && post_residual < 20 {
        // Moderately small gaps are also risky.
        score += 15.0 * (1.0 - ((post_residual - 10) as f64) / 10.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Compare post_residual against what the next item could use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // gap remains useful for lookahead item
        } else {
            score += 6.0; // gap too small for next item -> dead space
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: baseline cost plus pressure from open bins count.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 50.0; // avoid wasting a fitting bin by opening a new one
        }
        if post_residual == 0 {
            score -= 40.0; // perfect fit should never open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear penalty on dead space.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item can't fit here; penalize wasted residual relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Compare post_residual to mean residual across open bins:
    // leaving residual far above mean creates fragmented space.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_open_fit = next_item_size > 0 && post_residual >= next_item_size;
        if fitting_bins_count > 0 && good_open_fit {
            score += 80.0; // discourage opening new bin when a decent fit exists
        } else {
            score -= 10.0; // mild preference for fresh bin on poor fits
        }
    }

    // Early in stream: keep bins open and flexible; late: pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: absolute priority.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score += 180.0 + 6.0 * (10 - post_residual) as f64;
    } else if post_residual <= 25 {
        score += 60.0 + 1.5 * (25 - post_residual) as f64;
    } else if post_residual >= 50 {
        score -= 45.0;
    }

    // Fill ratio bonus.
    let fill = (item_size as f64) / cap;
    score -= 60.0 * fill;

    // Consolidation pressure, softened as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 320.0;
    }

    // Lookahead: exact match next step is gold.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.5 + 0.45 * (13.0 - slack);
            }
            let r2 = post_residual - next_item_size;
            if r2 == next_item_size {
                score -= 20.0;
            } else if r2 > 0 && r2 < 10 {
                score -= 2.0 + 0.25 * (10 - r2) as f64;
            }
            let gap = r2;
            if gap > 0 && gap < 6 && next_item_size > 20 {
                score -= 4.0 + 0.3 * (6 - gap) as f64;
            }
            if slack > 0 && slack < next_item_size && slack * 2 > next_item_size {
                score += 1.5;
            }
            // three-step chain: r2 can host the item after next exactly
            if r2 >= next_item_size && r2 < 2 * next_item_size && r2 % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 6.0 * (over / cap);
            // near-miss: item almost fits, keep this bin alive for later compaction
            if over <= 5.0 {
                score -= 3.0 + 0.4 * (5.0 - over);
            }
        }
    }

    // Mean-residual balance: avoid hoarding space far above the mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.4 * diff.abs();

    // Don't burn a big bin on a tiny item unless few bins are open anyway.
    if item_size <= 20 && bin_residual >= 80 && open_bins_count > 4 {
        score += 45.0;
    }

    // Late-stream tightness.
    if open_bins_count > 8 && post_residual > 0 && post_residual < item_size {
        score += 3.0;
    }

    // Tiny dead gap with many fitting options: mild extra penalty.
    if post_residual < 31 && fitting_bins_count > 3 && post_residual > 0 {
        score += 1.5;
    }

    // Dead-space guard: residual too small for typical upcoming items.
    if post_residual > 0 && post_residual < 21 {
        score += 13.0 + 0.6 * (21 - post_residual) as f64;
    }

    // New-bin arbitration.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if progress < 0.15 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity && (post_residual as f64) > mean_residual * 1.5 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving residuals that no plausible future item can use well.
    // Items are 1..=100; a residual below ~10 is near-dead, a residual just
    // above a typical small item is fine. Reward residuals in a "usable" band.
    let r = post_residual as f64;
    if r > 0.0 {
        if r < 10.0 {
            score += 6.0 * (10.0 - r); // dead space penalty
        } else if r <= 50.0 {
            score -= 4.0; // moderately reusable residual
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item would leave a very awkward residual in every open bin,
    // or when open-bin load is high and mean residual is small.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: discourage unless justified.
        score += 12.0;
        // If mean residual across open bins is small (they're all nearly full),
        // opening a new bin is reasonable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_res_norm = mean_residual / bin_capacity as f64;
        if mean_res_norm < 0.25 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 10.0 * progress;
        // If many bins are open with plenty of slack, discourage new bins.
        score += (open_bins_count as f64).sqrt() * mean_res_norm * 8.0;
        // Lookahead: if the next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
    } else {
        // Placing into an open bin: lookahead coupling. If the post-residual
        // can exactly host the next item, big reward (chained packing).
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 30.0;
            } else if post_residual >= next_item_size {
                score -= 6.0 * (post_residual as f64 / (post_residual + next_item_size) as f64);
            } else {
                // Next item won't fit here; slight penalty proportional to waste.
                score += 3.0 * (next_item_size as f64 - r).min(20.0) / 20.0;
            }
        }
        // Prefer filling bins that are already committed (low residual) to
        // keep other bins' large residuals available for big future items.
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Mild global pressure: with many open bins, tighten selection.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress.min(1.0).max(0.0);
    let poly = 1.0 + 0.6 * p * p - 0.3 * p;
    score *= poly;

    // Reward tight fits (small post_residual relative to capacity) with smooth decay
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap > 0.0 {
            score += 0.35 * gap * gap / cap;
        } else {
            // next item fits: reward leaving exactly usable space
            score -= 6.0 * (-gap / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0);
    }

    // Mild pressure toward consolidating into many-open-bins regimes
    score += 0.4 * (open_bins_count as f64).sqrt();

    // Align with mean residual: prefer bins whose post-residual stays near the mean
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: keep it neutral-ish; only attractive when residuals are fragmented
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * mean_residual * (open_bins_count as f64).sqrt() + 20.0 * p;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Dead-space penalty grows super-linearly for small unusable residuals.
    if pr > 0 {
        // residuals that cannot fit even the smallest plausible item are dead
        if pr < 10 {
            score += (10.0 - pr) * 8.0;
        }
        // modulo arithmetic: residuals divisible by common item sizes are reusable
        let reusable = (post_residual % 10 == 0) as f64
            + (post_residual % 20 == 0) as f64
            + (post_residual % 25 == 0) as f64
            + (post_residual % 50 == 0) as f64;
        score -= reusable * 6.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 12.0;
        if gap == 0 {
            score -= 25.0;
        } else if gap < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // this bin becomes dead for the next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive if current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced open
        } else {
            // penalize opening when a decent fit exists elsewhere
            let best_possible_waste = bin_residual - item_size;
            if best_possible_waste <= 15 {
                score += 25.0;
            }
            // early in stream, keep bins open; late, allow consolidation
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (1.0 - progress) * 15.0;
            // many open bins with large mean residual: prefer reuse
            if mean_residual > 30.0 && open_bins_count > 3 {
                score += 20.0;
            }
        }
    }

    // Tightness coupling: favor bins whose residual is close to item size
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 10.0;

    // Mild preference for fuller bins overall
    score -= (1.0 - frac) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
