pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance with graded penalty.
    if post_residual > 0 && post_residual < 21 {
        score += 12.0 + 0.55 * (21 - post_residual) as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: reward residual matching next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 42.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
            if slack > 0.0 && slack < 13.0 {
                score -= 5.0 + 0.4 * (13.0 - slack);
            }
            // Two-step lookahead: residual after placing next item too.
            let r2 = post_residual - next_item_size;
            if r2 > 0 && (r2 as f64) < mean_residual * 0.5 {
                score -= 1.0;
            }
            if r2 > 0 && r2 < next_item_size && r2 * 3 < item_size {
                score += 0.6;
            }
        } else {
            let dead = (next_item_size - post_residual) as f64;
            score += 4.0 * (dead / cap);
            if post_residual > 0 && dead as u32 <= next_item_size / 4 {
                score -= 0.8;
            }
            if post_residual > 0 && (post_residual as f64) < 0.25 * next_item_size as f64 {
                score += 0.9 * (1.0 - post_residual as f64 / (0.25 * next_item_size as f64));
            }
        }
    }

    // Bin pressure.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 28.0;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + mean_residual * 0.3;
        let crowded = open_bins_count > 4 && mean_residual < cap * 0.22;
        if crowded {
            score -= 2.5;
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual * 2.0 {
            score -= 3.5;
        }
        if fitting_bins_count <= 2 {
            score -= 1.5;
        }
        if open_bins_count > 6 && (mean_residual / cap) < 0.15 {
            score -= 1.8;
        }
        if total_items > 0 && step_index > total_items * 9 / 10 {
            score += 2.0;
        }
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 1.2;
        }
        if (mean_residual / cap) > 0.35 && open_bins_count > 3 {
            score -= 1.4;
        }
    }

    // Small residual that cannot fit next item is waste; but tiny leftovers get mercy late.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        if step_index > total_items * 4 / 5 && post_residual <= 3 {
            score -= 1.5;
        }
    }

    // Waste relative to item size.
    if post_residual > 0 && post_residual < item_size {
        score += 1.6 * (item_size - post_residual) as f64 / cap;
    }

    // Progress tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Tight residual below mean is good.
    if bin_residual != bin_capacity && post_residual > 0 && (post_residual as f64) < mean_residual * 0.6 {
        score -= 1.1;
    }

