    // fits are poor. Penalize the fresh bin mildly so tight fits win, but
    // keep it competitive against bins with large unusable residuals.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
    }

    // Progress-based calibration: late in the stream, be more aggressive
    // about filling bins to avoid leftover waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual as f64) * 0.3;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += ((bin_residual as f64) - (item_size as f64)).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize large dead space, nonlinearly (dead space that can't fit small items is worse)
        let dead = post_residual as f64;
        score += dead * dead / (bin_capacity as f64 * 0.5);
    }

    // 2-step lookahead: reward when next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain: this item + next item fills bin
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to tightness of the chain
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * chain_tightness;
        } else {
            // next item will NOT fit here: penalize, worse if gap is small (wasted potential)
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Compare against mean residual across open bins:
    // prefer bins whose residual is tighter than average (good packing)
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.6 * residual_diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Prefer compacting into fewer bins when many are open
    score += 2.0 * open_bins_count as f64;

    // New-bin candidate: prefer it only when no open bin gives a decent fit.
    // Make new bins slightly unattractive by default.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if lookahead suggests the next item is huge and this item is small,
        // a fresh bin is a reasonable hedge
        if next_item_size > 70 && item_size < 40 {
            score -= 60.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Small reward for using bins that are already fairly full
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
