    score -= 30.0 * tightness * (0.5 + 0.5 * progress);

    // Reward bins whose residual aligns with the lookahead item (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let match_term = 1.0 - ((pr_norm - nxt) * (pr_norm - nxt)) / (1.0 + nxt);
        score -= 25.0 * match_term.max(0.0) * (1.0 - progress);
    }

