        score -= 35.0 * (1.0 - pr_norm);
    } else {
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Mean-residual coupling: prefer bins below mean residual (consolidation)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev - 8.0 * dev;

    // Mild penalty for opening new bins, relaxing late in the stream
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - 0.5 * progress) + 2.0 * open_bins_count as f64;
    }

    score
}

