        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item)
    // unless post_residual is large and harmonically useful.
    if bin_residual == bin_capacity {
        score += 12.0; // base cost of a fresh bin
        if post_residual >= 50 {
            score -= 8.0; // roomy new bin is acceptable early on
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // if no open bin fits well, new bin is fine
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is already below mean (consolidating fullness).
    let res_frac = bin_residual as f64 / cap;
    let mean_frac = mean_residual / cap;
    if res_frac < mean_frac {
        score -= 5.0 * (mean_frac - res_frac);
    } else {
        score += 3.0 * (res_frac - mean_frac);
    }

    // Mild pressure to keep open-bin count low.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Heavy penalty for small unusable gaps (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Dead-space penalty amplified when the gap cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Slight penalty for leaving large residuals relative to mean
    if post_residual as f64 > mean_residual {
        score += 3.0;
    }

    // New-bin candidate: only attractive if all fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead coupling: reward exact or near-exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: huge reward (2-step chain closure)
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item still fits: scale reward by closeness
            score -= (1.0 - diff / bin_capacity as f64) * 15.0;
        } else {
            // next item won't fit here: penalize leaving a large unusable gap
            score += diff * 0.05;
        }
    }

    // Favor tight fits overall: small post_residual relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Penalize creating dead space far below the smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins with residuals below the mean (consolidate emptiness)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when few bins fit or residual is large
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base penalty so new bins open only when genuinely beneficial
        score += 30.0;
        score -= scarcity * 35.0;
        // late in stream, more willing to open fresh bins for clean packing
        score -= progress * 10.0;
        // if lookahead matches an empty bin exactly, encourage opening
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64 - item_size as i64) <= 0 {
            score -= 5.0;
        }
    }

    // Slight preference for fewer open bins (encourage filling existing ones)
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = post_residual as f64 / (bin_residual as f64 + 1.0);
    score += 20.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: penalize if post_residual cannot fit the next item but is
    // large enough to be "wasted dead space"; reward if next item fits exactly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // Dead space that won't be usable next step.
            let waste = post_residual as f64 - (post_residual % next_item_size.max(1)) as f64;
            score += 0.05 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let avg_fit_penalty = (mean_residual - item_size as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when open bins have large residuals poorly matching item,
        // or when many bins are already open (diversification late in stream).
        if avg_fit_penalty > 20.0 {
            score -= 10.0 + 0.2 * avg_fit_penalty;
        }
        if open_bins_count > 5 {
            score -= 2.0 * (open_bins_count as f64).sqrt();
        }
        // Mild time pressure: late in the stream, consolidate into open bins.
        score += 15.0 * (1.0 - progress);
        // Never open a new bin when a good fit exists elsewhere.
        if item_size >= 50 && mean_residual > item_size as f64 + 30.0 {
            score += 20.0;
        }
    }

    // Prefer bins whose residual is already small (consolidation).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Slight penalty for very large leftover chunks that only huge items could use.
    if post_residual > 60 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let p = progress;
    let poly = pr * pr / (bin_capacity as f64 * 2.0) * (0.5 + 0.5 * (p * p + p));

    // Penalize large residuals more as stream progresses (dead space becomes costly)
    score += 0.8 * poly;

    // Smooth interaction: tight fits (small post_residual) rewarded, more so early
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= 12.0 * tightness * tightness * (1.0 - 0.5 * p);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && bin_residual != bin_capacity {
        score += 2.0 * p;
    }

    // New-bin candidate: penalize mildly, less so late in stream when many bins open
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * p;
    }

    // Slight preference for fuller bins among open ones
    score -= (bin_residual as f64 / bin_capacity as f64) * (1.0 + 0.5 * p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo classes on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post_residuals that belong to "harmonic" residual classes:
    // residuals that are themselves likely item sizes (10..80 range, common sizes)
    if post_residual >= 10 && post_residual <= 80 {
        score -= 12.0;
        // Extra reward for residuals in frequently co-occurring classes
        // (multiples of 5 and 10 are common in integer size streams)
        if post_residual % 10 == 0 {
            score -= 10.0;
        } else if post_residual % 5 == 0 {
            score -= 5.0;
        }
    }

    // Penalize tiny dead space (< 10, unusable since min item is 1, but small
    // residuals pair poorly) — under interface items can be as small as 1,
    // so scale dead-space penalty by residual size
    if post_residual < 10 {
        score += (10.0 - pr) * 3.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let next_left = post_residual - next_item_size;
            // Reward chain fits that leave harmonic residuals
            if next_left % 10 == 0 {
                score -= 30.0;
            }
            score -= (next_left as f64) * 0.3;
        } else {
            // Next item cannot follow into this bin: mild penalty
            score += 8.0;
        }
    }

    // Integer-division thresholds on post_residual (halves/quarters of capacity)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        // Very tight bin: good packing density, but check it's not dead space
        score -= 15.0;
    } else if post_residual <= half {
        score -= 5.0;
    } else {
        // Leaving more than half the bin empty: penalize proportionally
        score += (pr - half as f64) * 0.4;
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but prefer reusing
    // open bins unless the new bin gives a notably better structure.
    if bin_residual == bin_capacity {
        // A fresh bin has full residual: baseline score = capacity + adjustments.
        // Encourage opening a new bin when current bins are fragmented and
        // the item is large (poor fit prospects elsewhere).
        score = cap + 25.0;
        if item_size > half {
            score -= 20.0;
        }
        if open_bins_count > 0 && mean_residual < item_size as f64 * 1.2 {
            // Existing bins are too full on average; new bin attractive
            score -= 35.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
        // Late in the stream, avoid proliferating bins with tiny leftovers
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && open_bins_count > 2 {
            score += 15.0;
        }
    } else {
        // Reward bins whose residual is close to the item (tight fit)
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.1;

        // Coupling with mean residual: prefer bins below mean residual
        // (fill the fuller bins first, keep emptier bins flexible)
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }

        // Many open bins: encourage consolidation into tighter bins
        if open_bins_count > 4 && post_residual < quarter as u32 {
            score -= 10.0;
        }
    }

    // Progress-based tie-breaking: deterministic mild jitter via step parity
    // (harmonic class of step_index) to break ties consistently
    match step_index % 3 {
        0 => score -= 0.5,
        1 => score += 0.25,
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward when the leftover gap could still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if the leftover gap is too small for the next item (dead space for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer tightening existing bins
    // over spreading; with few open bins, allow looser fits.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Deviation from mean residual: prefer bins whose residual is close to the item
    // (tight fit relative to fleet state).
    let fit_gap = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.15 * fit_gap.abs();

    // New-bin candidate: neutral-ish base, but attractive when current fit is bad
    // or the bin would be left with a tiny dead gap.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual > 0 && post_residual < 10) || (next_item_size > 0 && next_item_size > post_residual && post_residual > 0);
        if bad_fit {
            score -= 20.0;
        } else {
            score += 5.0 + pressure * 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly consumes the post residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 60.0; // perfect 2-step chain: bin fully closed
        }
        // Penalize leaving a residual that neither fits next item nor is tiny.
        if next_item_size as u32 > post_residual && post_residual > 0 {
            score += 25.0; // dead space relative to lookahead
        }
    } else {
        // Last item: prefer minimal leftover.
        score += post_residual as f64 * 0.5;
    }

    // Prefer bins tighter than the mean residual (good fits).
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a fresh empty bin unless it enables a good chain.
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && next_item_size <= post_residual {
            (bin_capacity - post_residual) as f64
        } else {
            0.0
        };
        score += 20.0 - 0.5 * chain_bonus;
    }

    // Mild late-stream preference for closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that likely cannot be reused by future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    } else if post_residual >= 10 && post_residual < 40 {
        // residual in the common small-item range is reusable
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Many open bins: prefer consolidating into existing bins to limit bin count.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 5.0 * pressure;

    // Mean residual coupling: when average residual is high, prefer bins
    // that bring their residual closer to the mean (leveling fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: late in the stream, be more conservative — avoid
    // opening bins with poor residual structure since fewer items remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly late in the stream,
        // but allow it early or when existing bins are badly fragmented.
        let mut new_bin_penalty = 12.0 + 40.0 * progress;
        if mean_residual > 45.0 {
            new_bin_penalty -= 18.0 * ((mean_residual - 45.0) / 55.0);
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.max(1) {
            new_bin_penalty -= 10.0; // next item is big; fresh bin may serve it
        }
        score += new_bin_penalty;
    } else {
        // Existing bins get a mild late-stream bonus for absorbing items.
        score -= 6.0 * progress;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap; // in [0,1]
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Smooth interaction: dead-space penalty grows non-linearly with progress
    score += 30.0 * norm_pr * norm_pr * (0.4 + 1.2 * p2 + 0.8 * p3);

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead coupling: favor bins whose post_residual matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        if diff >= 0.0 {
            score -= 8.0 * (1.0 - diff) * (1.0 - diff) * (0.5 + 0.5 * progress);
        } else {
            score += 6.0 * diff * diff * cap / 100.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Slight penalty for spreading across many open bins early on
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * (1.0 - progress);

    // Mean residual coupling: penalize bins far from mean residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: keep it neutral-ish, mildly penalized unless very late
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * p2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // size classes (10, 20, 25, 50) are more reusable.
    let r = post_residual;
    let mut harmony_bonus = 0.0;
    if r == 0 {
        harmony_bonus += 60.0; // perfect fit, best outcome
    } else {
        if r % 10 == 0 { harmony_bonus += 8.0; }
        if r % 20 == 0 { harmony_bonus += 6.0; }
        if r % 25 == 0 { harmony_bonus += 5.0; }
        if r % 50 == 0 { harmony_bonus += 4.0; }
        // Small residuals are dead space: penalize via integer division bands
        let band = r / 10; // 0..10 harmonic band
        if band == 0 { score += 25.0; }        // r < 10: unusable for most items
        else if band == 1 { score += 10.0; }   // r in 10..20: marginal
        else if band >= 5 { harmony_bonus += 4.0; } // large residual: flexible
    }
    score -= harmony_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            let nxt_post = r - next_item_size;
            if nxt_post % 10 == 0 { score -= 10.0; }
            if nxt_post < 10 { score += 8.0; } // creates tiny dead space next step
        }
        // If next item won't fit here anyway, slight reward for tight packing now
        if next_item_size > r {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + (bin_residual - item_size) as f64 * 0.1;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64 * 0.4;
        score += 30.0 + open_pressure - progress * 10.0;
        // But if the item is large relative to capacity, a fresh bin is fine
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous, avoids stragglers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild tightness reward scaled by stream progress.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is smaller than the minimum plausible item size
    // (estimated adaptively from the lookahead and stream position).
    let min_item = if next_item_size > 0 { next_item_size.min(10).max(1) } else { 1 };
    if post_residual < min_item {
        score += 50.0; // truly wasted space
    } else if post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize gaps that cannot fit the next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open bins pressure: discourage spreading across too many bins
    // unless the fit is good; encourages consolidation when many bins are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make the empty bin attractive only when the current fit
    // would leave a poor residual or when open-bin residuals are all poor.
    if bin_residual == bin_capacity {
        let mean_fit_quality = mean_residual / bin_capacity as f64;
        if post_residual < 20 || mean_fit_quality < 0.15 {
            score -= 30.0;
        } else {
            score += 15.0;
        }
    }

    // Mild stream progression term: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight nonlinearity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Aggressive 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            let slack = post - next;
            // Perfect chaining (post_residual == next_item_size) gets a big bonus.
            if slack == 0.0 {
                score -= 60.0;
            } else {
                // Reward proportional to how well the next item packs the remainder.
                score -= 25.0 * (1.0 - slack / bin_capacity as f64);
                // Extra reward if next item also fits relative to mean residual structure.
                if post <= mean_residual + 1.0 {
                    score -= 8.0;
                }
            }
        } else {
            // Next item cannot follow into this bin: penalize leaving a "dead" residual
            // that is too small for typical items but still wasted space.
            let dead = post / bin_capacity as f64;
            if dead > 0.0 && dead < 0.10 {
                score += 30.0 * (0.10 - dead) / 0.10;
            }
            score += 6.0;
        }
    }

    // Penalize bins whose residual deviates strongly above the mean (poor consolidation).
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.20 * dev;
    } else {
        score -= 0.10 * (-dev);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Cost of opening a new bin grows with number of open bins and progress.
        score = bin_capacity as f64 + 12.0 + 0.5 * open_bins_count as f64 + 10.0 * progress;
        // But if next item is large and current bins are fragmented, opening is fine.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Mild penalty for very tight fits that strand tiny unusable space when
    // other bins also fit (keep flexibility).
    if post_residual > 0 && post_residual < 5 && fitting_bins_count > 1 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill: reward tight fits strongly (non-linear).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill * fill;

    // Penalize small post-residuals that no realistic item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Dead-space penalty: residual too small for typical next items.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
        // Reward bins whose leftover will exactly host the next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Reward leaving room compatible with the lookahead size class.
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 / (1.0 + gap / 20.0);
    } else {
        // Last item: pure tightness.
        score -= 30.0 * fill;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Crowding: many open bins -> prefer consolidating into existing ones.
    let crowding = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 10.0 * crowding * (1.0 - fill);

    // Global residual balance: prefer bins below mean residual ( fuller bins ).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, be picky about waste; later, just fill.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * (post_residual as f64 * 0.4) - t * 10.0 * fill;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        let desperate = if fitting_bins_count == 0 { 0.0 } else { 45.0 };
        score += 30.0 + desperate - 25.0 * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;

    // Base: reward small post-residual with smooth non-linear decay
    let mut score = 40.0 * (1.0 - (-norm_pr * 4.0).exp()) + pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, large residuals are acceptable (future items can use them);
    // late in the stream, dead space becomes costly.
    let coupling = norm_pr * norm_pr * (1.0 + 6.0 * progress * progress);
    score += 30.0 * coupling;

    // Smooth interaction: exact-ish fits (tiny post_residual) get extra reward,
    // amplified as the stream progresses.
    let fit_bonus = (1.0 - norm_pr).powi(3) * (1.0 + 3.0 * progress);
    score -= 15.0 * fit_bonus;

    // Penalize leaving residual that cannot fit the lookahead item smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = ((pr - ni) / cap).max(0.0);
        score += 12.0 * gap * gap * (1.0 + 2.0 * progress);
        // Reward residuals that exactly accommodate the next item
        let exact_next = 1.0 - ((pr - ni).abs() / cap).min(1.0);
        score -= 8.0 * exact_next * exact_next;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize slightly so we prefer existing bins unless
    // all fits are poor; the penalty fades late in the stream.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common size classes
    // (multiples of 10, 20, 25) are "reusable" dead space; odd fragments are dead.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        let div10 = (pr % 10 == 0) as i32;
        let div20 = (pr % 20 == 0) as i32;
        let div25 = (pr % 25 == 0) as i32;
        let harmonic = (div10 + div20 + div25) as f64;
        score -= 8.0 * harmonic;

        // Penalize tiny unusable fragments (dead space < 10 can never be filled)
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 10.0;
        }
    }

    // Coupling: can next_item_size fit exactly into post_residual? (harmonic match)
    if next_item_size > 0 && next_item_size <= pr {
        score -= 30.0;
        if pr % next_item_size == 0 {
            score -= 20.0; // exact division: perfect future fill
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // lookahead item cannot use this residual's leftover anyway
        score += 5.0;
    }

    // Integer-division threshold classes on post_residual
    let class = pr / 15; // coarse harmonic bucket
    score += class as f64 * 1.5;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // open bins crowd: encourage spreading when many bins and large mean residual
        let crowd = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score = 45.0 + crowd * 10.0 - 20.0 * (1.0 - progress);
    }

    // Mild tightness reward relative to capacity fraction
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

