    }

    // Tight fit reward: small post residual relative to capacity
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize leaving residual far from mean residual (fragmentation)
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate: penalize slightly so we prefer reusing open bins
    if bin_residual == bin_capacity {
        score += 25.0;
