pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes mod 10 and integer division bands.
    let pr = post_residual;
    let class = pr % 10;
    let band = pr / 10; // 0..=10

    // Reward exact / near-tight fits strongly.
    if pr == 0 {
        score -= 200.0;
    } else if class == 0 {
        score -= 60.0; // residual divisible by 10 -> likely reusable by future items
