        score -= 30.0; // small dead space
    } else if pr <= 20 {
        score -= 10.0;
    } else {
        // large residual: penalize proportionally to band, reward if next item fits
        score += band as f64 * 8.0;
        if next_item_size > 0 && next_item_size <= pr {
            score -= 40.0 + (pr - next_item_size) as f64 * 0.5;
        }
    }

    // Dead-space penalty: residual too small for typical minimum item (assume >=1..=100, worst-case small items)
