    if (pr as f64) < min_item * 1.0 && pr > 0 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it to avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

