    if bin_residual == bin_capacity {
        // Opening a new bin costs one bin; penalize mildly, more when many open bins already loose.
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But if mean residual is small (open bins nearly full), new bin is fine.
        score -= (mean_residual / cap).min(1.0) * 40.0;
    }

    // Lookahead coupling: if next item would exactly fill this bin's post-residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 120.0;
    } else if next_item_size > pr && pr > 0 {
