    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Late in stream: tighten packing, discourage waste more aggressively.
    if progress > 0.8 {
        score += post_residual as f64 * 0.3;
    }

    score
}

