pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are unusable -> quadratic penalty on dead space.
    if post_residual < 10 && bin_residual != bin_capacity {
        score += (10 - post_residual) as f64 * 15.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 12.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks the next item -> penalize small blocking gaps.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 6.0;
        // Still allow opening when existing bins would leave bad dead space.
        if post_residual < 10 {
            score -= 10.0;
        }
    } else {
        // Mild pressure to consolidate into fewer bins when few are open.
        score -= (open_bins_count.max(1) as f64).recip() * 3.0;
    }

    // Prefer bins whose residual is near the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 4.0;

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches (or nearly matches) the next item's size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            // Perfect 2-step packing: residual consumed exactly by next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits; reward closeness of the match.
            let gap = (post_residual as f64 - next) / bin_capacity as f64;
            score -= 40.0 * (1.0 - gap).max(0.0);
        } else {
            // Next item does NOT fit: penalize leaving a sliver that wastes space.
            let wasted = next - post_residual as f64;
            score += 15.0 * (wasted / bin_capacity as f64).min(1.0);
        }
    } else {
        // Last item: just prefer tightest fill.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins attractive only when no open bin
    // offers a good (near-perfect) fit; otherwise defer to existing bins.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Big items justify opening a new bin; small items should reuse.
        score = 35.0 * (1.0 - tightness);
        if next_item_size > 0 && (next_item_size as f64 - item_size as f64).abs() < 5.0 {
            score -= 20.0; // new bin can host this + next item pair nicely
        }
    }

    // Late-stream pressure: consolidate more aggressively as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading; prefer bins with small residual.
    if open_bins_count > 3 {
        score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward placements that leave room for the lookahead item (k=2 chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // Penalize blocking the next item if the leftover becomes dead space.
        let waste = post_residual as f64;
        if waste > 0.0 && waste < next_item_size as f64 {
            score += 0.15 * waste;
        }
    }

    // Strong reward: this is the last bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Reward very tight fits (small post_residual, but not zero-waste extremes).
    if post_residual > 0 && post_residual <= 10 {
        score -= 8.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fit
    }

    // New-bin candidate: penalize opening a new bin, more so when good alternatives exist.
    if bin_residual == bin_capacity {
        let base = 10.0 + 0.4 * open_bins_count as f64;
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        // Early in the stream, opening bins is cheaper (builds a pool); later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base + fit_pressure + 10.0 * progress;
    } else {
        // Mild reward for using existing bins relative to global mean residual.
        score -= 0.05 * (mean_residual - post_residual as f64).max(0.0);
    }

    // Penalize creating awkward residual chunks that nothing typical can use.
    if post_residual > 0 && post_residual < 5 {
        score += 6.0;
    }

    score
}

