            score -= 6.0 * (1.0 - (pr / cap)) * (nxt / cap);
        } else {
            score += 2.0 * (gap / cap);
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, more when many bins open or early stream
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 5.0 + 10.0 * crowding * (1.0 - progress);
