        score -= 4.0 * (mean_residual / cap);
    }

    // Stream progress: prefer filling existing bins more aggressively later on
    score += 3.0 * progress * (pr / cap);

    // Mean residual coupling: penalize deviating far from mean residual
    score += 0.05 * (pr - mean_residual).abs();

    score
}

