pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" residue class (multiples of 10 or small remainders) are favored.
    let post = post_residual;
    let class_bonus: f64 = if post == 0 {
        -60.0 // perfect fit, best possible outcome
    } else if post % 10 == 0 {
        -18.0 // clean class, likely reusable by future items
    } else if post <= 9 {
        -10.0 // tiny dead space, nearly a perfect fit
    } else {
        // penalize awkward remainders: mid-range dead space is least reusable
        8.0 + ((post % 10) as f64) * 0.8
    };
    score += class_bonus;

    // Integer-division thresholds: how many items of the NEXT size could fit
    // into the post residual? Reward when the lookahead item fits exactly.
    if next_item_size > 0 {
        if next_item_size <= post {
            let k = post / next_item_size; // integer division threshold
            score -= 12.0 + 6.0 * (k as f64).min(3.0);
            if post % next_item_size == 0 {
                score -= 14.0; // exact partition with lookahead item
            }
        } else {
            // lookahead cannot use this bin's leftover: penalize proportionally
            score += ((next_item_size - post) as f64) * 0.25;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 0.1 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the
    // current fit is poor (large awkward post_residual) or many bins are open.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // residual of the fresh bin after placement
        let poor_fit = if post % 10 == 0 || post <= 9 { 0.0 } else { 1.0 };
        let pressure = (open_bins_count as f64 / 8.0).min(1.0);
        // penalty for opening a new bin; relaxed when fit is poor or many bins open
        score += 35.0 - 22.0 * poor_fit - 15.0 * pressure
                 + 0.15 * waste * poor_fit;
    }

    // Stream progression: late in the stream, prefer closing bins tightly
    // (dead space at the end is pure waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already "broken"; using it up is good.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.05 * dev.min(50.0);
    } else {
        score += 0.03 * (-dev).min(50.0); // bins with above-mean residual: slightly deprioritize
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
