pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual after placement still fits the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0; // dead space relative to lookahead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and this is a decent fit; encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 + 3.0 * progress;
    } else {
        // New-bin candidate: penalize more when open bins are underutilized.
        score += 10.0 + (open_bins_count as f64).sqrt() * 2.0
            + (mean_residual - post_residual as f64).abs() * 0.3;
    }

    // Prefer bins with residual close to item size (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: minimize post_residual (tight fits win).
    // Non-linear coupling: reward exact/near-exact fits heavily.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 20.0;
    } else {
        // superlinear penalty on wasted space
        score += (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 30.0;
    }

    // 2-step lookahead: if next item fits in the post_residual, reward this bin strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // chain fit: reward proportional to how well the chain closes
            let chain_waste = post_residual as f64 - nxt;
            score -= 25.0 - 0.3 * chain_waste;
        } else {
            // next item cannot follow here: mild penalty scaled by gap
            let gap = nxt - post_residual as f64;
            score += 0.4 * gap;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill.
    let dev = pr - mean_residual;
    if dev < 0.0 {
        score += 0.25 * dev; // below-mean residual => subtract => favor
    } else {
        score += 0.35 * dev; // above-mean residual => penalize
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is generally wasteful;
    // penalize it unless the item is huge relative to residual or many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64) / (bin_capacity as f64);
        // open new bin only if item is large and current bins are fragmented
        score += 20.0 - 25.0 * big_item - 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        if progress > 0.8 && big_item > 0.5 {
            score -= 10.0; // late stream: large items justify fresh bins
        }
    }

    // Fragmentation guard: leaving residual that is awkwardly small (unusable
    // for typical items but not zero) is penalized extra.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual is the base; amplify waste quadratically
    // for small residuals (dead space hurts more when it is the last crumbs).
    if post_residual > 0 {
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_frac * waste_frac;
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + 25.0 * progress;
    }

    // Lookahead coupling (k=2): if the next item can fit into the post residual,
    // reward this placement (keeps a useful gap); otherwise penalize leaving a
    // gap that is too small for the next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else if post_residual > 0 {
            // Gap exists but next item won't fit: penalize proportionally.
            score += 10.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin, decaying late in the stream.
        score += 55.0 * (1.0 - 0.5 * progress);
        // If other bins fit the item, penalize the new bin more when the best
        // existing fit would be reasonable (approximated via mean_residual).
        if fitting_bins_count > 0 {
            let mean_fit_quality = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
            // If mean residual after placement is small (tight fit exists elsewhere),
            // make the new bin very unattractive.
            score += 60.0 * (1.0 - mean_fit_quality.min(1.0));
        }
        // Few open bins and large item: opening a fresh bin is less costly.
        if open_bins_count <= 2 {
            score -= 20.0;
        }
    } else {
        // Mild reward for using already-open bins, scaled by how many choices exist.
        score -= 8.0;
        // Prefer bins whose residual deviates favorably from the mean: a bin with
        // below-mean residual is a better "completer" candidate.
        let dev = mean_residual - bin_residual as f64;
        score += 0.1 * dev;
    }

    // Global pressure: many open bins with high mean residual -> consolidate,
    // penalize placements that leave large gaps spread across bins.
    if open_bins_count > 3 {
        score += 0.05 * (open_bins_count as f64 - 3.0) * (post_residual as f64 / bin_capacity as f64);
    }

    // Small late-stream tightening: near the end, prefer perfect packing.
    if progress > 0.85 {
        score += 0.2 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit_norm = pr / (item_size as f64).max(1.0);
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = pr_norm * pr_norm;
    let p3 = p2 * pr_norm;
    let g = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += g * (60.0 * p2 - 30.0 * p3) * (1.0 + pr_norm);
    // Reward tight fits, penalize dead space increasingly late in stream
    score -= 40.0 * (1.0 - pr_norm).powi(3) * (0.5 + progress);
    // Lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns).abs();
        score -= 25.0 * (1.0 - diff / cap) * (1.0 - progress);
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - 0.5 * progress);
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln();
    }
    // Penalize bins far from mean residual (keeps residual distribution compact)
    score += 0.5 * ((pr - mean_residual) / cap).abs() * (1.0 + progress);
    // Mild pressure to reuse existing bins when many are open
    score += 0.05 * open_bins_count as f64 * pr_norm;
    // New-bin candidate: penalize slightly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: classify leftover space by
    // which "natural" item size classes (small 1-20, mid 21-50, large 51-100)
    // could still absorb it. Dead space = residual too small for the smallest
    // plausible item class.
    let dead_threshold = 10u32; // items >= 1, but small leftovers waste less
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0; // nearly-dead residual
    }

    // Modulo-based harmonic classes on post_residual: residues that align
    // with common item-size multiples (e.g. multiples of 25, 10, 5) are
    // more reusable than awkward residues.
    let r = post_residual;
    if r % 25 == 0 && r > 0 {
        score -= 18.0;
    } else if r % 10 == 0 && r > 0 {
        score -= 12.0;
    } else if r % 5 == 0 && r > 0 {
        score -= 6.0;
    } else {
        score += 4.0; // awkward residue
    }

    // Integer-division thresholds: how many "half-capacity" units remain.
    let half_units = r / 50;
    score -= 8.0 * half_units as f64;

    // Lookahead coupling: does the next item fit the post-residual exactly?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 120.0; // chain a perfect fit
        } else if next_item_size <= r {
            score -= 10.0 + (r - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot fit here anyway; slight penalty for tight bins
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only bin that can fit the item,
    // strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current
    // item would leave a very awkward residual in every open bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55 + open_bins_count as f64 * 2.0;
        // If item is large relative to capacity, new bin is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 40.0;
        }
        // Perfect-fit opportunity exists elsewhere? discourage new bin.
        if next_item_size > 0 && next_item_size == item_size {
            score += 15.0;
        }
    }

    // Mild preference for tighter bins overall (waste-avoidance pressure).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below 10 (min item size) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable gap penalty
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits: fraction of bin used by this placement
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * tightness;

        // Non-linear penalty for awkward mid-size gaps that few items can use
        if post_residual >= 10 && post_residual < 30 {
            score += 15.0;
        }
    }

    // Lookahead: strongly favor bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 {
            score += 10.0; // next item cannot use this gap
        }
    }

    // Open-bin pressure: prefer already-open bins over opening new ones
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: avoid forcing a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately unattractive unless current bin is nearly full
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * (bin_residual as f64 / bin_capacity as f64);
        // But attractive if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer bins with below-mean residual (consolidate space)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Penalize residuals far below mean residual (wasting usable space)
    score += 0.5 * (mean_residual - post_residual as f64).max(0.0);

    // Last fitting bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening new bins when existing bins fit well
    if bin_residual == bin_capacity {
        score += 10.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin still supports the next item
        }
    }

    // Prefer tighter fits overall
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among fitting bins, prefer the fullest (smallest residual)
        score += (bin_residual as f64 - mean_residual) * 0.5;
    }

    // New-bin candidate handling: discourage opening a new bin early,
    // allow it late or when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let new_bin_penalty = 60.0 * (1.0 - progress) * (1.0 - fragmentation);
        score += new_bin_penalty;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // new bin preserves room for a big follow-up
        }
    }

    // Late stream: consolidate aggressively into open bins
    score -= progress * 10.0;

    // Mild penalty for spreading across many open bins when mean residual is high
    if open_bins_count > 3 && mean_residual > bin_capacity as f64 * 0.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space avoidance with graded penalties.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 2.0 * post_residual as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward residual that fits the next item, tune by exactness.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0;
            if slack == 0 {
                score -= 8.0; // next item fits perfectly after this one
            } else if slack < 10 {
                score -= 3.0;
            } else if slack < next_item_size {
                score += 1.5; // leaving a sliver the next item barely misses
            }
        } else {
            score += 10.0;
        }
    }

    // Pressure from number of open bins: discourage spreading.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: usually penalize, but allow opening a fresh bin
    // when open bins are badly fragmented (small mean residual, many bins).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            let frag = mean_residual / cap;
            if open_bins_count > 6 && frag < 0.12 && next_item_size > 0 && (next_item_size as f64) > mean_residual * 1.5 {
                score -= 6.0; // consolidation impossible; fresh bin is fine
            } else {
                score += 15.0 + mean_residual * 0.3;
            }
            if next_item_size > 0 && next_item_size > bin_capacity - next_item_size.min(bin_capacity / 2) {
                // next item large: fresh bin may pair items better
                score -= 2.0;
            }
        }
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Late-stream: discourage opening new bins even more.
    if progress > 0.8 && bin_residual == bin_capacity && open_bins_count > 0 {
        score += 4.0;
    }

    // Reward using bins whose residual is close to item size (near-perfect fit).
    if bin_residual != bin_capacity && post_residual > 0 {
        let fill = (bin_residual - post_residual) as f64 / bin_residual as f64;
        if fill > 0.9 {
            score -= 2.5;
        }
    }

    // Penalize leaving residuals that no typical item can use (very small gap
    // relative to stream scale).
    if post_residual > 0 && post_residual < 4 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // smooth non-linear coupling of post_residual with stream progress
    score += (norm_pr * norm_pr) * (1.0 + progress) * 20.0;
    score -= (norm_pr * (1.0 - norm_pr)) * (1.0 - progress) * 15.0;
    // lookahead: reward residual that fits next item, scaled by progress
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= (next_item_size as f64 / cap) * (1.0 + progress) * 10.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 / cap) * 8.0;
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }
    // penalize deviation from mean residual (fragmentation smoothing)
    score += ((pr - mean_residual) / cap).abs() * 12.0 * (0.5 + progress);
    // new-bin candidate: penalize mildly, more so early when bins are few
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" residue class (multiples of 10) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        let cls = pr % 10;
        // residue 0 = perfectly harmonious leftover, heavily reward
        score -= match cls {
            0 => 18.0,
            1 | 9 => 2.0,
            2 | 8 => 1.0,
            3 | 7 => 0.5,
            4 | 6 => 0.0,
            _ => 2.5, // residue 5: awkward half-class, penalize
        };
        // Dead-space threshold: leftover too small for typical items
        if pr < 10 {
            score += 25.0; // wasted bin
        } else if pr < 20 {
            score += 6.0;
        }
        // Harmonic divisibility: leftover divisible by 4 or 5 pairs well
        if pr % 20 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
    } else {
        // Perfect fit: best possible outcome
        score -= 40.0;
    }

    // Lookahead harmonic coupling: does next_item_size divide/harmonize
    // with the post_residual?
    if next_item_size > 0 && pr >= next_item_size {
        let nx = next_item_size as f64;
        // next item fits exactly into leftover -> strong reward
        if pr == next_item_size {
            score -= 20.0;
        } else if pr % next_item_size == 0 {
            score -= 10.0;
        }
        // next item's size class (integer division by 10)
        let nx_cls = next_item_size / 10;
        let pr_cls = pr / 10;
        if nx_cls == pr_cls {
            score -= 4.0; // same harmonic decade: good chaining
        }
        // fraction of leftover consumed by next item
        let fill = nx / pr as f64;
        if fill > 0.7 {
            score -= 6.0 * fill;
        } else if fill < 0.15 {
            score += 3.0; // leaves a thin unusable sliver next round
        }
    } else if next_item_size > 0 && pr < next_item_size {
        // leftover cannot host the lookahead: mild penalty scaled by gap class
        let gap_cls = (next_item_size - pr) / 10;
        score += 2.0 + gap_cls as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let tight = if fitting_bins_count == 0 { 0.0 } else {
            (post_residual as f64 - mean_residual).abs()
        };
        score += 55.0; // default: discourage new bin
        if fitting_bins_count <= 1 {
            score -= 30.0; // poor alternatives -> new bin becomes viable
        }
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
        let _ = tight;
        // progress-aware: late in stream, reuse more aggressively
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
    }

    // Prefer fuller bins (tighter packing) via residual fraction
    let res_frac = bin_residual as f64 / bin_capacity as f64;
    score += 8.0 * res_frac;

    // Crowding: many open bins -> favor consolidation into emptier ones
    if open_bins_count > 6 {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    score
}

