pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Gaps below the minimum item size (1..=10) are pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderately small gaps (< 20) risk becoming dead space too.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (post_residual near zero but not dead-space).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: penalize placements that keep many bins open
    // unless this bin is the last chance to fit the item.
    if fitting_bins_count > 1 {
        score += 3.0 * open_bins_count as f64;
    } else {
        score -= 25.0; // last chance: strongly favor using this bin
    }

    // Prefer bins whose residual is already below mean (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item does NOT fit post-residual, penalize slightly (creates stranded gap).
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity;
    // only attractive when all open bins would leave bad gaps or open bins are few.
    if bin_residual == bin_capacity {
        score += 30.0 * open_bins_count as f64;
        if post_residual < 20 {
            score += 25.0; // new bin leaving small gap is wasteful
        }
    }

    // Stream progression: mild late-stream consolidation pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 500.0;
        } else {
            score -= 80.0 * (1.0 - next_post as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize leaving a gap that the next item cannot use (dead space risk).
        score += 0.6 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average when gap is small.
    let gap_vs_mean = post_residual as f64 - mean_residual;
    if gap_vs_mean < 0.0 {
        score += 0.3 * gap_vs_mean; // below-average residual (tighter bin) rewarded
    } else {
        score += 0.5 * gap_vs_mean; // above-average residual penalized
    }

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 200.0;
        // Allow new bin if lookahead suggests a large next item needs fresh space.
        if next_item_size > 0 && post_residual == bin_capacity {
            score -= 250.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Mild pressure against bin proliferation late in the stream.
    if open_bins_count > 0 {
        score += 2.0 * open_bins_count as f64 / (1.0 + step_index as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    // Relative tightness of the fit: 1.0 = perfect fit, 0.0 = item just fits.
    let tightness = if bin_residual > 0 {
        1.0 - (post_residual as f64 / bin_residual as f64)
    } else {
        1.0
    };

    // Reward tight fits strongly (subtract from score).
    score -= 60.0 * tightness * tightness * (0.5 + 0.5 * fill_frac);

    // Lookahead: if the next item exactly fits the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // Partial lookahead credit proportional to how well next item fills leftover.
            let la_fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * la_fill;
        } else {
            // Next item won't fit here; slight penalty for leaving awkward space
            // that is too small for the next item (dead space risk).
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * dead * dead;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Many open bins: discourage spreading items thin; favor consolidating
    // into bins that are already fairly full.
    if open_bins_count > 1 {
        let mean_fill = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 30.0 * mean_fill;
    }

    // Global residual pressure: if mean residual is small, be greedy about
    // using existing space; if mean residual is large, tolerate looser fits.
    let residual_pressure = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 20.0 * residual_pressure * tightness;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, squeeze everything in.
    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };
    score -= 35.0 * progress * fill_frac;

    // New-bin candidate handling: base score is post_residual (capacity - item).
    // Penalize opening a new bin when existing space is ample, but allow it
    // when the item is large and existing residuals are small.
    if bin_residual == bin_capacity {
        let new_bin_bias = 15.0
            + 40.0 * (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
            - 30.0 * fill_frac;
        score += new_bin_bias;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = post;
    score -= 30.0 * x * x * (1.0 - progress);          // reward tight fits early on
    score += 20.0 * x * x * progress;                  // tolerate slack late in the stream
    score -= 15.0 * (1.0 - x) * x * (1.0 - progress);  // extra reward for near-perfect fill early
    score += 8.0 * x * x * x;                          // penalize large dead space smoothly

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - x);
    }

    // Lookahead: if the next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (1.0 - x) * (1.0 - progress);
    }

    // Mean residual coupling: penalize bins far from the fleet mean (smooth quadratic)
    score += 0.5 * (post - mean_residual) * (post - mean_residual) / cap;

    // Mild penalty for spreading across many open bins
    score += 0.3 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
