pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small leftover gaps (1..=12) are nearly unusable
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 4.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tightness reward: prefer bins where item fills a large fraction
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading to new bins
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: penalize unless nothing fits well
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64;
        let new_bin_bonus = if fitting_bins_count == 0 { -20.0 }
            else if spread > item_size as f64 * 0.6 { -5.0 }
            else { 25.0 + open_bins_count as f64 * 2.0 };
        score += new_bin_bonus;
    }

    // Lookahead: if next item could use the post_residual, reward this placement
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual < next_item_size && post_residual < 10 {
            score += 8.0; // blocks next item -> extra penalty
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff); // strong reward when post_residual == next_item_size
        // penalize leaving residual that neither fits next item nor is small
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 8.0; // dead space for the lookahead item
        }
        // bonus if after next item the residual would vanish
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
    } else {
        // last item: prefer tightest fit only
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0 + post_residual as f64 * 0.3;
    }

    // Slight preference for filling bins earlier in the stream
    score += 2.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits: penalize less when post_residual is small.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 40.0;

    // Penalize dead space quadratically when residual becomes unusable (< smallest plausible item).
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Lookahead: if the next item could use this bin's post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating residual too small for the next item is wasted space.
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 70.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Baseline neutral score for a fresh bin.
        score = 45.0 + fit_ratio * 10.0;
        // Early in the stream, opening bins is cheap and keeps options open.
        score -= 30.0 * (1.0 - progress);
        // If many bins are open with slack, discourage spreading.
        score += (open_bins_count as f64) * 3.0;
        // If this is a last-chance situation for other bins, prefer them instead.
        if fitting_bins_count == 1 {
            score += 80.0;
        }
        // If the next item is large, a fresh bin preserves large residual.
        if next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Mild global pressure: when mean residual is high, prefer bins that reduce slack.
    score -= (mean_residual / bin_capacity as f64) * 8.0;

    // Late-stream consolidation: favor filling existing bins over opening new ones.
    score += progress * 12.0 * if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr * norm_pr);

    // Reward tight fits (small post residual) more strongly as stream progresses.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * cap * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot plausibly fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0);
        score += waste * waste / cap * 0.4;
        // Smooth reward if post residual accommodates next item well.
        let fit_quality = if pr >= nxt { 1.0 - (pr - nxt) / cap } else { 0.0 };
        score -= fit_quality * fit_quality * 10.0 * (1.0 - progress);
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.05 * norm_pr;

    // Coupling with mean residual: prefer bins below mean residual early (larger bins),
    // and near mean later, smoothly interpolated.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (0.5 - progress) * 8.0;

    // New-bin candidate: neutral-ish baseline, penalized unless residual is large.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) - norm_item * 20.0;
        if next_item_size > 0 && (next_item_size as f64) > pr * 0.5 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10.
    // Small residues (< 10) are dead space since min item is 1; penalize heavily.
    let residue_class = (post_residual % 10) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable dead space
    } else {
        score -= residue_class * 0.3; // reward leftovers that are "round" (multiples of 10)
    }

    // Integer-division threshold on post_residual: leftovers in [0..=5] are near-perfect fits.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score += 5.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // harmonic class of the chained leftover
            if next_post % 10 == 0 {
                score -= 12.0;
            }
            score += next_post as f64 * 0.15;
        } else {
            // next item won't fit here; slight penalty for wasting the slot
            score += 4.0;
        }
    }

    // Capacity-fraction coupling: prefer filling bins past 50% of capacity.
    let fill_fraction = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_fraction * 10.0;

    // If many bins are open, encourage consolidation into existing bins over new bins.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportionally to open bins and stream progress
        score += 15.0 + open_bins_count as f64 * 2.0 + (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // but allow opening when mean residual is large (existing bins too full/fragmented)
        if mean_residual < item_size as f64 * 0.5 {
            score -= 25.0;
        }
    }

    // Mean-residual harmony: prefer bins whose residual is close to the mean (balanced packing).
    score -= 3.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / (bin_capacity as f64)));

    score
}

