pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact 2-step lookahead match: post_residual ~ next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64 * 0.5)).max(-1.0);
        if post_residual == next_item_size {
            score -= 50.0; // perfect 2-item packing
        }
    } else {
        // Last item: reward tightest fill
        score -= 40.0;
    }

    // Penalize dead space: small post_residual that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare residual to mean residual: prefer bins that keep mean residual balanced
    let post_f = post_residual as f64;
    score += 0.3 * (post_f - mean_residual).abs();

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        let tight_fit_exists = next_item_size > 0
            && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 5;
        if tight_fit_exists {
            score -= 15.0; // fresh bin allows perfect 2-step chain
        } else {
            score += 35.0 + 2.0 * open_bins_count as f64; // discourage opening new bins
        }
    }

    // Mild progression pressure: early stream, be frugal with bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_f / bin_capacity as f64);

    score
}

