pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (dead space is superlinearly bad)
    let cap = bin_capacity as f64;
    let dead = post_residual as f64;
    if dead > 0.0 {
        score += 0.35 * (dead / cap).powf(2.2) * cap;
    }

    // Reward tight fits: small post residual relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 12.0;
            // extra reward if next item exactly fills what's left
            if next_item_size as u32 == post_residual {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize leaving a gap the next item can't use
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }
    // Many fitting bins: mild penalty to preserve flexibility (prefer the tightest naturally)
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Time horizon: early in the stream, be more conservative about fragmenting bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * (dead / cap);

    // Global state coupling: if mean residual is high, prefer bins that reduce dispersion
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: penalize opening a new bin unless current options are poor.
    // Baseline penalty grows with number of open bins that already fit the item.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * fitting_bins_count as f64;
        // but if the item is large relative to capacity, opening fresh may be fine
        score -= 10.0 * (item_size as f64 / cap);
        // late in stream with many open bins, avoid proliferation
        score += 0.5 * open_bins_count as f64 * progress;
    }

    score
}

