pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - norm_post) * (1.0 - norm_post);
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 30.0 * tightness * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit a typical next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (nxt - post) * (1.0 - progress);
        } else {
            score -= 6.0 * (1.0 - (post - nxt) / cap) * progress;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Deviation from mean residual: prefer bins near mean to keep balance
    score += 0.15 * (post - mean_residual).abs();

    // New-bin candidate: penalize slightly unless current fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "dead space classes".
    // Residues 1..9 are awkward dead space; residue 0 is harmonically clean.
    let res_class = (post_residual % 10) as f64;
    if post_residual > 0 {
        score += (10.0 - res_class) * 0.35; // penalize non-multiple-of-10 leftovers
    } else {
        score -= 6.0; // perfect closure strongly rewarded
    }

    // Small dead space (< next item) is unusable for the lookahead item: penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.25;
    }

    // Lookahead harmony: if next item fits exactly or harmonically in post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 10.0;
        } else if gap % 10 == 0 {
            score -= 5.0;
        } else {
            score += (gap % 10) as f64 * 0.2;
        }
    }

    // Integer-division thresholds on post_residual: classify usable zones.
    let zone = post_residual / 25; // 0..4 quartile zones
    score -= zone as f64 * 1.5; // larger usable zones slightly preferred

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: keep it unattractive unless it is genuinely better.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Allow a fresh bin only for big items leaving harmonious residual
        if item_size % 10 == 0 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 6.0; // big next item may justify a fresh bin
        }
    }

    // Fraction of capacity used: reward tight fills.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * 4.0;

    // Late-stream consolidation: prefer closing bins tightly as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score -= 3.0 + progress * 4.0;
    }

    // Coupling with mean residual: avoid bins far below mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: encourage filling existing ones over spreading.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / 100.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 15.0 * (20.0 - post_residual as f64) / 10.0;
        }
    }

    // Reward tight fits (perfect fill gets strong bonus).
    if post_residual == 0 {
        score -= 100.0;
    }

    // If next item can use the post-residual, reward leaving exactly that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // New-bin candidate: penalize mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
    } else {
        // Prefer bins with less residual relative to mean (denser bins first).
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let lookahead_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when next item fits perfectly after this placement.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits but imperfectly: penalize the mismatch quadratically.
            score -= 25.0 * (1.0 - lookahead_diff / (bin_capacity as f64));
            score += 0.35 * lookahead_diff;
        } else {
            // Next item would NOT fit in the leftover space: penalize dead space.
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }
        // Bonus if this bin can chain: residual now AND after next item.
        if post_residual >= next_item_size {
            let chain_left = post_residual - next_item_size;
            if chain_left == 0 {
                score -= 15.0;
            }
        }
    } else {
        // Last item: simply minimize leftover waste.
        score += 0.5 * post_residual as f64;
    }

    // Penalize creating residuals far below the mean (fragmentation) but
    // reward residuals above mean (kept capacity aligned with stream needs).
    let mean_gap = post_residual as f64 - mean_residual;
    if mean_gap < 0.0 {
        score += 0.25 * (-mean_gap);
    } else {
        score -= 0.05 * mean_gap;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // capacity (nothing else would fit well later) or no open bins fit.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 8.0 * fill_ratio; // slightly favors new bins for large items
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // New bin can host the next item too: pair-packing bonus.
            score -= 12.0;
        }
        if fitting_bins_count >= 3 {
            // Plenty of alternatives: discourage opening yet another bin.
            score += 30.0;
        }
    }

    // Mild late-stream pressure to consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item can plausibly fill.
    let t = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - t);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 4.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Global state: many open bins with large mean residual -> prefer consolidation.
    let spread = mean_residual - post_residual as f64;
    score += 0.15 * spread * (open_bins_count as f64).sqrt();

    // Slight preference for fuller bins over emptier ones as stream progresses.
    score += (1.0 - t) * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it mildly unattractive unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 12.0 - 20.0 * (1.0 - fit_ratio);
    }

    score
