        }
    }

    // Mild penalty when many bins are open and this bin deviates from mean residual.
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += 0.15 * dev * (open_bins_count as f64).ln().max(0.0) / (1.0 + progress);

    // New empty bin candidate: prefer only when progress is high or fit is hopeless.
    if bin_residual == bin_capacity {
        score += 3.0 - 2.5 * progress - 0.5 * (1.0 - x);
    }

    score
}

