pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of the dead space: bins whose post_residual lies in
        // "useful" residue classes (small, or commonly recurring sizes) are favored.
        let pr = post_residual;
        let class_bonus = match pr {
            0..=10 => 60.0,
            11..=20 => 30.0,
            21..=30 => 15.0,
            31..=50 => 0.0,
            _ => -20.0, // large dead space is penalized
        };
        score -= class_bonus;

        // Modulo arithmetic: post_residual divisible by small item classes (10/20/25)
        // leaves reusable chunks; reward divisibility.
        if pr % 10 == 0 { score -= 25.0; }
        else if pr % 20 == 0 { score -= 30.0; }
        else if pr % 25 == 0 { score -= 20.0; }
        else if pr % 5 == 0 { score -= 8.0; }

        // Lookahead coupling: reward if next item fits the post_residual exactly or well.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 200.0;
            } else if next_item_size <= pr {
                let slack = (pr - next_item_size) as f64;
                score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            } else {
                // Next item cannot use this space: penalize proportionally
                let over = (next_item_size - pr) as f64;
                score += 10.0 * (over / bin_capacity as f64);
            }
        }

        // Last-chance bin: strongly prefer using it to avoid opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 90.0;
        }

        // New-bin candidate: penalize unless current open bins have poor fits
        // (high mean residual spread) or few bins fit the item.
        if bin_residual == bin_capacity {
            let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.35 };
            let spread = (mean_residual - bin_residual as f64).abs();
            score += 45.0 * pressure + 0.3 * open_bins_count as f64 - spread.min(60.0);
