pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post-residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: strong reward.
            score -= 12.0;
        } else {
            // Dead space smaller than next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 10.0 * waste;
        }
    } else {
        // Last item: just minimize post residual.
        score -= 8.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into fuller bins.
    let pressure = (open_bins_count as f64) / (1.0 + total_items as f64);
    score += 6.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Relative fill compared to mean residual: prefer bins below/at mean residual
    // (fuller than average) when many bins are open.
