        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * dev;
    }

    // Early stream: be more willing to open new bins for very large items
    // (keep flexibility); late stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bonus = (1.0 - progress) * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slight penalty so it only wins on poor fits.
        score += 3.0 - new_bin_bonus;
        if item_size >= 60 {
            score -= 2.0; // large items fine in fresh bins early
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with a non-linear
    // polynomial penalty that grows super-linearly for large dead space.
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth coupling with stream progress: late in the stream, dead space
    // becomes increasingly costly, so amplify the penalty polynomially.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Interaction term: post_residual relative to mean residual across bins.
    // A bin whose post-residual is far below the mean is a good consolidation.
    let mean_term = (pr - mean_residual) / cap;
    score += 20.0 * mean_term * mean_term * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward
    // using it (subtract), scaled smoothly by tightness of the fit.
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this bin (perfect chain); penalize if next item is larger
    // than post residual but this bin's post-residual is small anyway.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            // Smooth reward peaking when next item fills post-residual exactly.
            score -= 15.0 * (-diff / cap * 8.0).abs().exp() * (1.0 - norm_pr);
        } else {
            // Post-residual too small for next item: mild penalty proportional
            // to wasted potential, smoothed.
            score += 5.0 * (pr / nxt) * norm_pr;
        }
    }

    // Mild penalty for spreading across too many open bins relative to stream length.
    score += (open_bins_count as f64) * norm_pr * (0.5 + progress);

    // New-bin candidate handling: an empty bin has norm_pr == 1.0; its raw
    // polynomial score is naturally high, but add a smooth extra penalty so
    // it's only chosen when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 + progress);
    }

