pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space classes
    let pr = post_residual;
    let class = pr / 10; // integer division thresholds
    match class {
        0 => score -= 25.0,                 // near-perfect fit
        1 => score -= 8.0,                  // good
        2 => score += 4.0,
        3 => score += 10.0,
        4 => score += 16.0,
        5 => score += 20.0,
        _ => {}
    }

    // Modulo coupling: residuals divisible by small harmonics pair well
    if pr % 20 == 0 { score -= 6.0; }
    if pr % 10 == 0 { score -= 3.0; }

    // Lookahead: does next item fit exactly / well into post residual?
    if next_item_size > 0 && next_item_size <= pr {
        let gap = (pr - next_item_size) as f64;
        score -= (10.0 - gap.min(10.0)) * 1.5;
    } else if next_item_size > pr && next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        score += 40.0 - 30.0 * crowded;
        if open_bins_count == 0 { score -= 60.0; }
    }

    // Prefer filling bins below mean residual (tighter bins)
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Late stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more aggressively.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item is larger than this bin's residual but fits elsewhere, mild penalty.
    if next_item_size > bin_residual {
        score += 3.0;
    }

    // Mean residual coupling: prefer bins with residual near the mean (avoid outliers).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.2;

    // Mild preference for tighter bins overall.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

