pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, with non-linear penalty on dead space
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item can fit into post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0 * (1.0 - next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // Dead space for the known next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize bins whose residual deviates strongly from mean (keep residual spread tight)
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: opening a fresh bin should only win when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline with mild penalty; tight fits elsewhere easily beat it.
        score = bin_capacity as f64 - 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Late in stream, discourage opening new bins slightly more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins already open and one fits, make new bin less attractive
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Mild global pressure: when many bins are open, prefer consolidation
    score += 0.05 * open_bins_count as f64;

    // Small reward for using larger bins' residual early vs late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
