pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = 1.0 - (post / cap); // how full the bin becomes

    // Reward tight fits with a smooth non-linear coupling to stream progress.
    let tightness = (fit_ratio).powi(3);
    score -= 12.0 * tightness * (0.5 + progress);

    // Penalize leaving dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let waste = (nxt - post) / cap;
            score += 18.0 * waste * waste * (1.0 + progress);
        } else {
            // Smooth reward when next item still fits this residual.
            let compat = 1.0 - (post - nxt) / cap;
            score -= 6.0 * compat * compat * (1.0 - progress);
        }
    } else {
        // Last item: strongly prefer filling existing bins completely.
        score -= 10.0 * tightness;
    }

    // Last-chance bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 9.0 * (1.0 - (bin_residual as f64 / cap));
    }

    // Discard near-empty residual space: prefer bins whose leftover is either
    // tiny (well packed) or still large (usable), penalize the awkward middle.
    let norm_post = post / cap;
    let awkward = 4.0 * norm_post * (1.0 - norm_post);
    score += 3.0 * awkward * (0.5 + 0.5 * progress);

    // Mild penalty for spreading across many open bins when mean residual is low.
    let mr = mean_residual / cap;
    score += 0.05 * open_bins_count as f64 * (1.0 - mr);

    // Prefer opening a new bin only when all open bins would be badly packed.
    if bin_residual == bin_capacity {
        let avg_fit = 1.0 - mr;
        score -= 4.0 * avg_fit * avg_fit * (1.0 - progress);
        score += 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

