        4 => score += 3.0,             // half-full: mildly wasteful
        _ => {}
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
