pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 90.0 * tight * tight;

    // Penalize large dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 55.0;
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't chain here: penalize proportionally to overshoot.
            let over = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 35.0 * over;
        }
    } else {
        // Last item: just fill any bin as fully as possible.
        score -= 120.0 * tight;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }
    // Many fitting bins: mild penalty to encourage spreading load.
    if fitting_bins_count > 2 {
        score += 6.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Time horizon: early in stream, be pickier about residual quality;
    // late in stream, prioritize closing bins out.
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * (1.0 - t);
    score -= 25.0 * t * tight;

    // Global state coupling: high mean residual => waste is less critical;
    // low mean residual => conserve space aggressively.
    let mr = mean_residual / bin_capacity as f64;
    score += 30.0 * (0.5 - mr) * tight;

    // Mild penalty per open bin to discourage bin proliferation.
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate: only attractive when current bin is a poor fit
    // or nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.5 * bin_capacity as f64;
        if poor_fit && fitting_bins_count > 0 {
            score -= 45.0;
        } else {
            score += 30.0;
        }
        // Early stream: opening fresh bins is cheap and flexible.
        score -= 20.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64 / cap;
    let fit = item_size as f64 / cap;

    // Smooth non-linear polynomial coupling: residual quality weighted by progress
    let poly = pr * pr * (1.0 - pr) * (1.0 + 2.0 * progress);
    score -= 30.0 * poly;

    // Penalize dead space that cannot fit next item, smoothly ramped
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let unusable = ((nx - pr).max(0.0) / cap.max(1.0)) * cap;
        score += 0.9 * unusable * (1.0 + progress);
    }

    // Reward tight fits with smooth quadratic term
    score -= 8.0 * fit * (1.0 - pr);

    // Last-chance bonus, smoothly scaled
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - progress * 0.5);
    }

    // Encourage consolidation toward mean residual
    score += 0.15 * (pr * cap - mean_residual).abs() * (1.0 - progress);

    // Mild new-bin penalty early, relaxation late (smooth in progress)
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 4.0 * progress;
    }

    // Penalize fragmenting many open bins
    score += 0.05 * open_bins_count as f64 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity fractions. Leftovers in "dead" classes (very small) are penalized.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // 0..1

    // Dead space classes: leftover < 10 is nearly unusable for items 10..80,
    // leftover in (0,10] or exact tiny slivers get a big penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic class of post_residual via integer division thresholds:
    // class 0: (0,10), class 1: [10,25), class 2: [25,50), class 3: [50,100]
    let class = match post_residual {
        0 => 4u32,
        1..=9 => 0,
        10..=24 => 1,
        25..=49 => 2,
        _ => 3,
    };
    // Reward mid/large classes (usable), penalize tiny classes
    score -= match class {
        4 => 30.0, // perfect fit
        3 => 12.0,
        2 => 6.0,
        1 => 0.0,
        _ => 8.0,
    };

    // Modulo logic: post_residual divisible by common item sizes (10,20,25,50)
    // is a "harmonic" leftover likely to be filled later.
    if post_residual > 0 {
        let harmonics = [(10u32, 6.0f64), (20, 5.0), (25, 5.0), (50, 4.0), (100, 3.0)];
        for &(m, r) in harmonics.iter() {
            if post_residual % m == 0 {
                score -= r;
                break;
            }
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic pairing: item + next leaves another clean class
            let pr2 = post_residual - next_item_size;
            if pr2 == 0 || pr2 >= 10 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover; slight penalty for
            // stranding capacity that next_item could have used elsewhere
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when current bin
    // fits are poor. Give the empty bin a baseline cost plus pressure from
    // stream progress and open-bin count.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = c * 0.55 + 10.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
