        if item_size as f64 > 0.6 * c {
            score -= 10.0;
        }
        // If next item is huge, keep capacity free
        if next_item_size > 0 && next_item_size as f64 > 0.7 * c {
            score -= 12.0;
        }
    }

    // Tight fits are excellent: reward small post_residual generally
    score -= 10.0 * (1.0 - frac) * (1.0 - frac);

    // Mild preference for filling bins when many are open (consolidation)
    score += 0.3 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
