pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Threshold scales with next item size (gap is "dead" if it can't hold it).
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 20 };
    if post_residual < dead_threshold {
        score += 15.0 + (dead_threshold - post_residual) as f64 * 0.8;
    }
    // Zero residual is perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fits are good: reward when item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }
    // Many fitting bins: mild penalty to prefer consolidation.
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + progress * 0.5);

    // Prefer bins with residuals close to item (best-fit flavor).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 6.0;

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Brand-new bin candidate: penalize unless open bins are scarce or residual is huge.
    if bin_residual == bin_capacity {
        let scarcity = if open_bins_count == 0 { 20.0 } else { 0.0 };
        score += 18.0 - scarcity - mean_residual * 0.1;
    }

    // Mean residual coupling: avoid worsening an already-fragmented pool.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 4.0;
    }

    score
}

