pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but heavily reward
    // post_residual that exactly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect 2-step chain: this item leaves exactly room for the next.
        if (post_residual as i64 - next_item_size as i64).abs() == 0 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits: reward proximity of post_residual to nxt.
            let slack = (post - nxt) / bin_capacity as f64;
            score -= 35.0 * (1.0 - slack).max(0.0);
        } else {
            // Dead space: next item cannot use it -> penalize proportionally
            // to how "wasted" the leftover is relative to next item size.
            let waste = (nxt - post) / nxt.max(1.0);
            score += 25.0 * waste.min(1.5);
        }

        // Coupling with mean residual: if this bin is much tighter than the
        // average open bin, filling it is good (consolidation).
        let dev = (mean_residual - post) / bin_capacity as f64;
        score -= 15.0 * dev.clamp(-1.0, 1.0);
    } else {
        // Last item: pure best-fit on post_residual.
        score += 0.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; the lookahead terms above will
        // dominate when an open bin chains nicely with the next item.
        score += 30.0;
        // But if many bins are open and fragmented, a fresh bin can help.
        if open_bins_count > 4 {
            score -= 10.0;
        }
    }

    // Slight stream-progression pressure: late in the stream, prefer
    // closing bins tightly rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

