pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tight * tight;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space that no future item can plausibly use.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item still fits here; mild reward proportional to leftover after that
            let second_residual = post_residual - next_item_size;
            score -= 10.0 - 0.1 * second_residual as f64;
        } else {
            // next item won't fit here; penalize more as bin gets fuller
            score += 0.15 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.05 * open_bins_count as f64 * tight;

    // Relative to mean residual: placing into a below-average-residual bin is good consolidation.
    score -= 0.2 * (mean_residual - bin_residual as f64);

    // Late in the stream, prefer filling existing bins tightly over opening new ones.
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for opening a new bin when existing bins fit, scaled by progress.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = post;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis.
    score += (post / cap).powi(3) * cap * 0.8;

    // Stream progress coupling: early on, keep bins flexible (penalize small residuals mildly);
    // late in the stream, pack tightly.
    let flexibility = (1.0 - progress) * (post / cap).powi(2) * 60.0;
    let tightness = progress * (1.0 - post / cap).powi(2) * 40.0;
    score += flexibility - tightness;

    // Lookahead: reward residual that can host the next item, penalize near-miss dead space.
    if nxt > 0.0 && nxt <= post {
        let snug = 1.0 - (post - nxt) / cap;
        score -= snug * (12.0 + 18.0 * progress);
    } else if nxt > post {
        // wasted potential: penalize proportional to how much the next item overshoots
        let overshoot = ((nxt - post) / cap).min(1.0);
        score += overshoot * overshoot * 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - post / cap);
    }

    // Mean-residual divergence: prefer bins whose residual is below average
    // (i.e., already well-filled) to consolidate waste.
    let dev = (mean_residual - post) / cap;
    score -= dev * 10.0;

    // New-bin candidate handling: only attractive when the item is large relative
    // to capacity or the stream is early and few bins are open.
    if bin_residual == bin_capacity {
        let big_item = (item / cap).powi(2);
        let openness = (1.0 - progress) * (1.0 / (1.0 + open_bins_count as f64));
        let poor_alternatives = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 // default penalty for opening a new bin
            - big_item * 35.0
            - openness * 20.0
            - poor_alternatives * 60.0;
        // if next item also needs fresh space, opening now is fine
        if nxt > 0.0 && nxt <= post {
            score -= 8.0;
        }
    }

    // Mild penalty for very high residual spread across open bins (fragmentation pressure).
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Residuals in "harmonic" classes (multiples of small divisors of capacity) are
    // more likely to be reusable by future items, so reward them (subtract).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual divisible by 10 -> very reusable
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    // Class 2: divisible by 5 but not 10
    else if post_residual % 5 == 0 {
        score -= 3.0;
    }
    // Class 3: divisible by 2
    else if post_residual % 2 == 0 {
        score -= 1.0;
    }
    // Dead-space penalty: small odd residuals are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Integer-division threshold on post_residual: quarter bins
    let quarter = bin_capacity / 4;
    if post_residual <= quarter {
        score += 4.0; // nearly-full bin: good packing but low future utility
    } else if post_residual > bin_capacity / 2 {
        score -= 2.0; // keeps large flexible space
    }

    // Coupling with lookahead item: reward exact or near-exact fit for next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // harmonic check on the leftover after the next placement
            let post2 = post_residual - next_item_size;
            let chain_bonus = if post2 % 10 == 0 { 8.0 } else if post2 % 5 == 0 { 4.0 } else { 0.0 };
            score -= chain_bonus + (gap as f64).min(10.0) * 0.5;
        } else {
            score += 3.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // neutral-ish baseline; penalize slightly so decent fits win
        score += 5.0;
        // but if item is large relative to mean residual spread, new bin is fine
        if (mean_residual - pr).abs() < 1.0 {
            score -= 10.0;
        }
    }

    // Stream progression: late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64 / cap) * 4.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (pr - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if it cannot fit the smallest plausible item (<= 10)
    // or cannot fit the lookahead item that would otherwise chain here.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 50.0; // unusable sliver: strong penalty
    } else {
        // Non-linear penalty growing as residual shrinks toward unusability.
        let r = post_residual as f64;
        score += 8.0 * (dead_threshold / r).powf(2.0);
    }

    // Lookahead coupling: reward leaving a gap that exactly (or nearly) fits next item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0; // perfect chain fit
        } else if gap > 0 && (gap as f64) < dead_threshold {
            score += 20.0; // would create dead sliver for next item
        } else if gap < 0 {
            score += 6.0; // next item cannot reuse this bin anyway
        }
    }

    // Open bins pressure: encourage filling existing bins when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless residual becomes dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bin attractive only when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how fragmented open bins are.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = bin_capacity as f64 + open_bins_count as f64 * 2.0 - fragmentation.min(20.0);
    }

    // Mild preference for bins below mean residual (tighter bins first).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / (total_items.max(1) as f64);

    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: usually undesirable if any open bin fits,
        // but attractive when this is the last chance to place the item.
        score += 30.0 + 15.0 * (fitting_bins_count as f64).min(5.0);
        if fitting_bins_count <= 1 {
            score -= 80.0;
        }
        // Early in the stream, opening bins is cheaper; later it is not.
        score -= 20.0 * (1.0 - t);
    } else {
        if next_item_size > 0 {
            // Aggressive 2-step lookahead: reward bins whose post_residual
            // exactly (or nearly) matches the next item size.
            let diff = (post_residual as f64 - next_item_size as f64).abs();
            score -= 18.0 * (1.0 - (diff / 60.0)).max(0.0);
            if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
                score -= 12.0; // near-perfect chain bonus
            }
            // Penalize dead space that cannot host the next item.
            if post_residual < next_item_size {
                score += 0.6 * (next_item_size - post_residual) as f64;
            }
        }
        // Last-chance bin: avoid opening a new bin if this one fits.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Mild coupling to mean residual: prefer tighter-than-average bins.
        score += 0.25 * (mean_residual - post_residual as f64);
    }

    // Slight time drift to break ties differently across the stream.
    score -= 3.0 * t;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space), superlinear.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // heavily reward this placement (perfect chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: leftover likely becomes dead space.
        score += (post_residual as f64).min(next_item_size as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize placements that leave a residual in the "hard zone" (1..=9),
    // which almost nothing can fill.
    if post_residual >= 1 && post_residual <= 9 {
        score += 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; discourage
    // unless this is early in the stream or many bins are already open and
    // the fit here would be poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > bin_capacity as f64 - item_size as f64; // always true for new bin
        let _ = poor_fit;
        // Base penalty for opening a new bin, reduced early in the stream
        // when keeping bins clean for future large items is valuable.
        let mut new_bin_penalty = 15.0 - 10.0 * (1.0 - progress);
        // If many bins are open with high mean residual, spreading is okay.
        new_bin_penalty -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        new_bin_penalty -= (mean_residual / bin_capacity as f64) * 5.0;
        // If no existing bin can fit (fitting_bins_count counts only open bins,
        // new-bin call included here), the penalty naturally competes.
        score += new_bin_penalty.max(-5.0);
    }

    // Slight preference for bins with below-average residual (keep a spread
    // of residual sizes available for future items).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Late-stream urgency: as the stream ends, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 3.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: prefer small post-residual, amplified late in stream
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (item nearly fills bin), stronger as stream progresses
    score -= 25.0 * fit_norm * fit_norm * (0.3 + progress);

    // Dead-space penalty: residual too small to be useful, smooth quadratic falloff
    let dead = (norm_pr - 0.15).max(0.0).min(0.15) / 0.15;
    score -= 12.0 * dead * dead;

    // Last-chance bonus when few fitting bins
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // Lookahead: penalize if next item won't fit post residual (smooth margin term)
    if next_item_size > 0 {
        let margin = pr - next_item_size as f64;
        if margin < 0.0 {
            score += 8.0 * (-margin / cap);
        } else {
            score -= 4.0 * (margin / cap) * (margin / cap);
        }
    }

    // Spread from mean residual: prefer bins deviating smoothly below mean
    score += 0.3 * (mean_residual - pr).abs() * (0.5 + 0.5 * progress);

    // Mild new-bin preference early when bins are crowded
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo common size buckets
    let post = post_residual as i64;
    let nxt = next_item_size as i64;

    // Reward residuals that fall into "harmonic" classes likely to be filled later
    if nxt > 0 {
        let gap = post - nxt;
        if gap >= 0 {
            // next item fits exactly-ish: strong reward
            score -= 30.0 + (gap as f64).min(10.0) * -0.5;
            if gap == 0 {
                score -= 40.0; // perfect pairing with lookahead
            }
        } else {
            // next item won't fit here; mild penalty scaled by overflow
            score += ((-gap) as f64) * 0.08;
        }
    }

    // Modulo-10 harmonic classes: residuals divisible by common sizes are reusable
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 20 == 0 {
            score -= 4.0;
        }
        if pr % 25 == 0 {
            score -= 3.0;
        }
        if pr % 50 == 0 {
            score -= 5.0;
        }
        // awkward dead space classes
        if pr < 10 && pr > 0 {
            score += 25.0; // unusable sliver
        }
    }

    // Integer division thresholds on post_residual
    let tier = pr / 25; // 0..4
    match tier {
        0 => score += 12.0,   // very tight leftover
        1 => score -= 2.0,    // 25-49: moderate
        2 => score -= 5.0,    // 50-74: good
        _ => score -= 8.0,    // 75+: roomy
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer tight fit relative to capacity fraction
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // New-bin candidate: penalize slightly so we prefer existing bins unless they're bad
    if bin_residual == bin_capacity {
        score += 15.0;
        // but if existing residuals are all tiny, opening fresh is fine
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mean residual coupling: prefer bins below mean (balance avoidance of fragmentation)
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.99;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 10), so penalize gaps in the "dead zone" heavily.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // pure dead space
        } else if post_residual < 25 {
            score += 25.0; // hard-to-fill gap
        } else if post_residual <= 35 {
            score += 8.0;  // moderately awkward gap
        } else {
            score -= 6.0;  // large, still-usable residual is fine
        }
    } else {
        score -= 40.0; // perfect fit: strongly reward exact closure
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow only when it
        // yields a good long-term residual profile.
        score += 55.0 + bin_pressure;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0; // new bin can also host the next item
        }
    } else {
        // Existing bin: slight bonus when it is one of few fitting options.
        if fitting_bins_count == 1 {
            score -= 15.0; // last-chance bin: use it or lose it
        } else if fitting_bins_count <= 3 {
            score -= 5.0;
        }
        // If the next item fits exactly in the post-residual, reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size > 0 && next_item_size > post_residual {
            score += 4.0; // next item won't fit here anyway; mild penalty
        }
        // Penalize bins whose residual deviates far below mean (hoarding space).
        if (bin_residual as f64) < mean_residual - 15.0 {
            score += 6.0;
        }
    }

    // Mild late-stream tightening: near the end, closing bins cleanly
    // matters more than preserving flexibility.
    if progress > 0.8 && post_residual >= 10 {
        score -= 3.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post residual) more aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual
    // matches the next item size exactly (chain of perfect fits).
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) == nxt {
            score -= 500.0;
        } else if post_residual as f64 > nxt {
            let gap = post_residual as f64 - nxt;
            if gap <= 5.0 {
                score -= 150.0;
            } else if gap <= 15.0 {
                score -= 60.0;
            }
            // Bonus proportional to how much of the post residual the next item consumes
            score -= 50.0 * (nxt / post_residual as f64);
        } else {
            // Next item cannot fit here; penalize leaving a residual that
            // invites dead space, scaled by how badly it misses.
            let miss = nxt - post_residual as f64;
            score += 40.0 * (miss / nxt).min(1.0);
        }
    }

    // Penalize large unusable residuals (dead space) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        // tiny slivers are nearly useless
        score += 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    // (placing into a fuller bin consolidates space).
    score -= 25.0 * ((mean_residual - post_residual as f64) / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty
    // if the current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let mut penalty = 250.0;
        if item_size > bin_capacity / 2 {
            penalty -= 80.0;
        }
        if fitting_bins_count == 0 {
            penalty -= 250.0; // no alternative: new bin is fine
        }
        // Late in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 100.0 * progress;
        score += penalty.max(0.0);
    }

    // Mild preference for fuller bins (smaller bin_residual).
    score += 0.3 * (bin_residual as f64 - post_residual as f64) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize leaving residuals that are hard to reuse: residual just below
    // typical item sizes creates dead space. Dead-space penalty grows when
    // post_residual is small but nonzero and awkward.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: reward if the next item fits into the post residual,
    // penalize if it would force a new bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is attractive only when
    // the item is large relative to residual capacity elsewhere, or when the
    // stream is early and we expect many future items to fill it.
    if bin_residual == bin_capacity {
