pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: smaller post_residual is inherently favored by the base term.

    // Dead-space penalty: gaps too small for the minimum item size (1..100 interface,
    // but tiny gaps under ~10 are effectively unusable) are strongly penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Gap unusable for the lookahead item: penalize so we prefer bins whose
    // remainder can still serve the next item, unless the gap is dead anyway.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // gap remains useful
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // blocks the next item's fit
    }

    // Exact fit: perfect closure is highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all
    // open fits are poor. Add pressure proportional to open bins so a new bin
    // is not casually chosen, but relax it when the item leaves a large,
    // flexible residual in a fresh bin.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin with room for the next item is attractive
        }
    }

    // Open-bins pressure: mildly prefer bins that reduce fragmentation, i.e.
    // prefer filling bins whose residual is below the mean (consolidating).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Late-stream conservatism: as the stream progresses, avoid creating
    // medium dead zones since there is less future to use them.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 25 {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match reward: next item fits tightly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize post_residual that next item cannot use (dead space risk)
    if next_item_size > 0 && next_item_size > post_residual {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Favor filling bins nearly to capacity
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Late in the stream, prefer tighter packing more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Slight penalty for hoarding many open bins
    score += 0.05 * open_bins_count as f64;

    score
