    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward residuals that few items can still use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is nearly useless
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 6.0; // moderately awkward zone
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit (high mean residual spread / many bins).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with stream progress to
        // consolidate bins late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 15.0 + 20.0 * progress;

        // If existing bins fit poorly (item barely fits anywhere), new bin is OK.
        if fitting_bins_count == 0 {
            open_cost -= 25.0;
        }
        // If open bins are nearly full on average, a fresh bin is reasonable.
        if mean_residual < item_size as f64 {
            open_cost -= 10.0;
        }
        // Many open bins with slack: discourage opening yet another.
        open_cost += 0.5 * open_bins_count as f64;

        score += open_cost;
    }

    // Mild global pressure: when many bins are open, prefer filling existing ones.
    score += 0.3 * open_bins_count as f64;

    // Slight preference to use bins whose residual deviates from the mean
    // (pair complementary residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer moderate residuals (leave room for future items).
    // Late stream: strongly prefer tight fits (small post_residual).
    let progress_w = 0.5 + 2.5 * progress * progress; // grows quadratically with progress
    let mut score = pr * (1.0 - 0.6 * progress) + progress_w * norm_pr * norm_pr * cap;

    // Smooth non-linear penalty for large dead space, amplified late.
    score += 30.0 * norm_pr * norm_pr * norm_pr * (1.0 + progress);

    // Last-chance bonus: only fitting bin -> subtract to favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_quality = 1.0 - gap / cap;
        if fit_quality > 0.0 {
            score -= 25.0 * fit_quality * fit_quality;
        } else {
            score += 10.0 * (-fit_quality);
        }
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (mean_residual - pr).abs();

    // New-bin candidate: neutral baseline, slightly penalized early, competitive late.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Primary objective: minimize wasted space (tight fit reward).
    score -= 60.0 * (1.0 - post_residual as f64 / cap);

    // Harmonic class logic on post_residual: classify dead space into residue classes.
    let pr = post_residual;
    // Class 0: perfect or near-perfect closure (post_residual <= 5) -> strong reward.
    if pr <= 5 {
        score -= 40.0;
    }
    // Dead-space bands via integer division thresholds: unusable slivers (1..=9)
    // are excellent; mid-range chunks (10..=30) are dangerous (can host small items
    // but often fragment); large leftovers (>30) are reusable.
    if pr >= 10 && pr < 30 {
        // Penalize mid-range fragmentation, modulated by class (pr mod 10).
        let class = (pr % 10) as f64;
        score += 12.0 + 0.5 * class;
    }
    // Harmonic half-capacity class: post_residual near cap/2 is a "harmonic" split
    // point, mildly favorable since it can accept mid-size items.
    let half = cap / 2.0;
    let dev_half = (post_residual as f64 - half).abs();
    score += 0.15 * dev_half;

    // Lookahead coupling (k=2): reward if next item fits exactly or tightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_tight = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - next_tight / cap);
            // Harmonic match: next item exactly closes this bin.
            if post_residual == next_item_size {
                score -= 30.0;
            }
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            score += 8.0 * (1.0 - post_residual as f64 / cap);
        }
    } else {
        // Last item in stream: strongly prefer closing bins as tightly as possible.
        score -= 20.0 * (1.0 - post_residual as f64 / cap);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is usually wasteful unless
    // every existing fit would create severe fragmentation.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0;
        // Early in the stream, opening bins is cheaper (builds options).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // If many bins are already open, discourage more.
        score += 2.0 * open_bins_count as f64;
        // If the item is large relative to capacity, a fresh bin is reasonable.
        score -= 20.0 * (item_size as f64 / cap);
    } else {
        // Slight preference for bins whose residual deviates from the mean
        // (diversity of residuals helps future packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.05 * dev;
        // Prefer bins that are already fairly full.
        score -= 5.0 * (1.0 - bin_residual as f64 / cap);
    }

    // Global pressure: when many bins are open, tighten packing.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // Small-but-usable gaps: moderate penalty scaled by how unusable they are.
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (post_residual near zero but still zero-waste).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Exact fit of the next item into the resulting residual is a jackpot.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Penalize when the residual after placement can no longer fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Open-bin pressure: discourage spreading across many bins when a compact
    // option exists, but relax pressure as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - mean_residual / 10.0) * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless this bin would otherwise
    // waste a lot of space (i.e., current fit is very poor).
    if bin_residual == bin_capacity {
        let waste_here = (bin_capacity - item_size) as f64;
        score += 45.0 - waste_here * 0.3;
    }

    score
}

