    score -= 30.0 * tightness;

    // --- Stream progression: as stream ends, prefer tighter fills more aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * tightness;
    score += 5.0 * progress * (post_f / bin_capacity as f64);

    // Penalize creating tiny unusable residuals (1..=5 dead space).
    if post_residual >= 1 && post_residual <= 5 {
        score += 20.0;
    }

    score
}

