pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (bin_capacity as f64 * 0.35);

    // Penalize dead space: post-residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward for near-perfect two-item packing.
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting space.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 45.0;
        // More attractive late in stream or when open bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        if mean_residual < item_size as f64 {
            score -= 20.0; // existing bins are nearly full
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
        // If a future two-item chain would be perfect here, prefer opening.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Mild penalty proportional to fragmentation of open bins.
    if open_bins_count > 0 {
        score += (mean_residual - post_residual as f64).abs() * 0.05;
    }

    // Prefer filling bins with larger residual relative to mean (balance avoidance).
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize large post_residual mildly);
    // Late: post_residual dead space matters more, amplified polynomially.
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (0.5 + progress) + pr_norm * (1.0 - progress) * 0.5;
    score += coupling * cap * 0.6;

    // Reward near-perfect fits with a smooth saturating term.
    let fit_quality = 1.0 - pr_norm;
    score -= 12.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - diff / cap).max(0.0) * (1.0 - diff / cap).max(0.0);
    }

    // Penalize bins far from mean residual (encourage balanced residual spread),
    // smoothly weighted by progress.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 10.0 * (0.3 + 0.7 * progress);

    // Slight preference for reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes that are hard to fill later
    // (residuals in 1..10 are nearly useless) get a strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Integer-division thresholds: classify post_residual into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else if post_residual <= quarter {
        // Tight but usable residue: mild reward.
        score -= 15.0;
    } else if post_residual <= half {
        // Mid-range residue: neutral-ish, slight penalty to prefer tighter fits.
        score += 10.0;
    } else {
        // Large residue: bad fit, penalize.
        score += 25.0;
    }

    // Modulo arithmetic on post_residual: residues divisible by common item
    // granularities (5, 10) are more likely to be filled by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how snugly.
            score -= 20.0 * (post_residual as f64 - next_item_size as f64).recip().min(2.0);
        } else {
            // Next item does not fit here; if post_residual is small this is fine,
            // if large we waste capacity.
            if post_residual > half {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if many bins are open and mean residual is fragmented, opening
        // fresh is sometimes better; scale with fragmentation.
        let frag = (mean_residual - post_residual as f64).abs();
        if open_bins_count > 3 && mean_residual < quarter as f64 {
            score -= 45.0;
        }
        if frag > half as f64 {
            score += 10.0;
        }
    }

    // Stream progression: late in the stream, be more conservative about
    // opening bins and more eager to close bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 8.0 * progress;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins) to consolidate packing.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals below the minimum item size are pure waste.
    let min_item = 10.0f64.min(cap); // items >= 10 by spec, but guard for 1..100 interface
    if post_residual as f64 > 0.0 && (post_residual as f64) < min_item {
        score += 1000.0; // unusable gap -> heavily penalize
    }

    // Progressive dead-space penalty: small gaps that likely can't fit typical items.
    let pr = post_residual as f64;
    if pr > 0.0 {
        score += 8.0 * (1.0 - (pr / cap)).powi(4); // tiny gaps punished super-linearly
    }

    // Reward near-perfect fits.
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item can't use this gap: gap becomes dead space for the lookahead horizon
        score += 3.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones over new bins.
    let open_pressure = (open_bins_count as f64).sqrt() * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins already exist.
        score += 10.0 + open_pressure;
        // But a new bin is fine if the item is huge and no open bin fits well.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 8.0;
        }
    } else {
        score -= open_pressure.min(10.0);
    }

    // Slight preference for tight residual relative to mean residual of open bins.
    score += (pr - mean_residual).abs() * 0.05;

    score
}

