    let mut score = post_residual as f64;

    // Exact fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Aggressive 2-step lookahead: does next item fit exactly in the leftover?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // perfect chain: this item sets up next item perfectly
