            score += (two_step as f64) * 0.5;
        } else {
            // next item cannot use the leftover: dead space risk
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.8;
        }
    }

    // Penalize residual far below mean residual (creating isolated small gaps)
    let res = post_residual as f64;
    let dev = mean_residual - res;
    if dev > 0.0 {
        score += dev * 0.3;
    } else {
        score += (-dev) * 0.1;
    }

    // Small unusable dead space penalty (residual too small for typical items)
    if res < 10 {
        score += 60.0;
    } else if res < 20 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: open a new bin only if it looks clearly better
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; discourage unless leftovers elsewhere are bad
        score += 80.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 60.0; // fresh bin accommodates the pair comfortably
