    // Time horizon: early in stream, prefer consolidating into fewer bins;
    // late in stream, opening new bins is less costly relative to wasted space
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later; also penalize if many open bins
        score += 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64 * (1.0 - progress);
        // But if the only alternative is a terrible fit, allow new bin
        if fit_ratio < 0.35 && post_residual > 50 {
            score += 15.0;
        }
    } else {
        // Using existing bins: reward more when many open bins (consolidation)
        score -= 1.5 * open_bins_count as f64 * progress;
    }

    // Global residual state: if mean residual is high, prefer bins below mean
    // (fill under-filled bins first to normalize residuals)
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Mild penalty for very large items into nearly-full bins (fragmentation risk)
    if item_size > 60 && bin_residual < 90 && bin_residual >= item_size {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, non-linearly (quartic coupling).
    let mut score = pr * (1.0 + pr_norm * pr_norm);

    // Smooth polynomial interaction with stream progress: later in stream,
    // penalize leftover space more aggressively (waste becomes costlier).
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream
    score += pr_norm * pr_norm * (1.0 - prog_term) * 10.0;
    score -= progress * progress * 2.0;

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 5.0;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + (next_item_size as f64 / cap) * 4.0;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space relative to next item size.
        score += (next_item_size as f64 / cap) * 3.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + progress * 4.0 - (mean_residual / cap) * 6.0;
    }

    // Mean residual coupling: placing into a bin far from mean residual is slightly penalized.
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity quarters:
    // residuals in the lowest quarter are "dead space" -> penalize strongly.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    match class {
        0 => {
            // Tiny leftover: only good if the next item can consume it exactly.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 30.0;
            } else {
                score += 40.0; // dead space penalty
            }
        }
        1 => {
            // Sweet spot: leaves room for medium items (harmonic partner class).
            score -= 25.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 20.0;
            }
        }
        2 => {
            // Decent leftover; mild reward, lookahead-aware.
            score -= 10.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 15.0;
            }
        }
        _ => {
            // Nearly empty bin after placement: wasteful use of an open bin.
            score += 15.0;
        }
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // (better to start fresh than fragment a bin) or no good fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        if large_item > 0.6 {
            score -= 20.0 * (large_item - 0.6) / 0.4;
        } else {
            score += 45.0; // discourage opening bins for small items
        }
        // Late in the stream, fewer new bins help.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer bins with below-mean residual (keep big holes for big future items).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Many open bins: tighten packing; few open bins: be lenient.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < 10 {
            // Dead space below the smallest item: nearly unusable.
            score += (10 - post_residual) as f64 * 6.0;
        }
        // Squared penalty on small residuals to strongly prefer tight fits.
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild spreading pressure when many bins are open.
        score += (open_bins_count as f64) * 0.8;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual blocks the next item: penalize.
        score += 8.0;
    }

    // New-bin candidate handling: keep it slightly unattractive unless
    // open bins would create heavy dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream with few open bins, opening new is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        score -= (open_bins_count as f64) * 0.5;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain: bin becomes exactly full after next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64); // next item fits well
        } else {
            // next item cannot fit here; penalize more when leftover is small/dead
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Compare against mean residual: bins below mean residual are "tight" -> good targets.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev; // if post_residual < mean_residual, dev>0 -> subtract, favor it

    // Last-chance bonus: only one bin fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good existing option.
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            // pairing possibility: keep new bin open for current+next pair
            score -= 5.0;
        } else {
            score += 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is mandatory
        }
    }

    // Late-stream: consolidate, avoid spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
