pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // residual waste is penalized more heavily later in the stream.
    let pr_norm = pr / cap;
    let coupling = pr_norm * pr_norm * (1.0 - progress) * (1.0 - progress);
    score += 12.0 * coupling * cap;

    // Cubic term: strongly penalize mid-range dead space that is hard to fill.
    score += 8.0 * pr_norm * pr_norm * pr_norm * cap * (0.25 + 0.75 * progress);

    // Reward tight fits (small post_residual) more as stream progresses.
    score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.3 + 0.7 * progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            score += 3.0;
        }
    }

    // Penalize bins far from the mean residual (fragmentation avoidance).
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // Many open bins: mild pressure to consolidate into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * pr_norm;

    // New-bin candidate: keep it neutral-ish, slightly penalized unless residual waste
    // of using an open bin would be severe (smooth comparison via quadratic term).
    if bin_residual == bin_capacity {
        score += 4.0 - 0.05 * (pr_norm * cap).powi(2).min(400.0) * 0.0 + 0.0;
        score = cap + 2.0 - 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by modulo classes
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = post / cap;

    // Penalize residuals that fall into "unusable" harmonic classes:
    // residual mod 10 == small nonzero values are hard to fill later (items >= 1..100 though)
    let harmonic = (post_residual % 10) as f64;
    if post_residual > 0 && harmonic <= 3.0 {
        score += (4.0 - harmonic) * 2.0; // awkward small remainder class
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Non-linear waste penalty: quadratic in waste fraction
    score += waste_frac * waste_frac * 20.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - diff / cap);
        } else {
            // next item cannot follow here: penalize proportional to leftover awkwardness
            score += (next_item_size as f64 - post as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win if current fit is bad
    if bin_residual == bin_capacity {
        // neutral base plus mild preference for keeping tight fits in open bins
        score = post_residual as f64 + 10.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing else fits: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big item coming soon, fresh bin useful
        }
    }

    // Stream progression: later in stream, be greedier (prefer tight fits more)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - waste_frac);

    // Open bin pressure: many open bins -> favor consolidating into fuller bins
    if open_bins_count > 3 {
        score += (mean_residual - post) * 0.3;
    }

    // Integer division threshold on post_residual: buckets of 25
    let bucket = post_residual / 25;
    score += match bucket {
        0 => -6.0,  // 0..24: tight, good
        1 => 0.0,   // 25..49: neutral
        2 => 4.0,   // 50..74: roomy, mild penalty
        _ => 8.0,   // 75..99: wasteful
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that nothing can use are heavily penalized.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item.max(next_item_size as f64) {
        score += 60.0; // dead space penalty
    }

    // Penalize gaps too small for the lookahead item when it is small-ish
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) > 0 {
        score += 15.0 + 0.5 * post_residual as f64;
    }

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 80.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * tightness * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: make empty bin attractive only if item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * fill_ratio;
        score += 20.0; // baseline reluctance to open new bins
    }

    // Slight preference for bins whose residual is near mean (keep residuals homogeneous)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward when the next item
    // exactly fills the post residual, or at least fits into it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect 2-chain: item + next item fill bin exactly
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item cannot use the leftover: penalize dead space growth
            let waste = post_residual as f64;
            score += 0.35 * waste;
            // extra penalty if leftover is small and unusable (dead space)
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // last item: just minimize leftover
        score += 0.1 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins that are tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current residual
    // is large (would waste a lot) and next item is big.
    if bin_residual == bin_capacity {
        let waste_threshold = 0.6 * bin_capacity as f64;
        if post_residual as f64 > waste_threshold {
            score -= 25.0;
        } else {
            score += 80.0; // discourage opening new bins when open bins fit decently
        }
    }

    // Prefer reusing bins over proliferating open bins
    score += 0.3 * open_bins_count as f64;

    // Slight time decay: late in stream, pack tighter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space that no future item (min size 1..10) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        // Next item won't fit here; mildly penalize wasting the leftover.
        score += 0.05 * post_residual as f64;
    }

    // Global pressure: many open bins relative to progress -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 2 {
        score += 0.15 * open_bins_count as f64 * (1.0 - progress);
    }

    // Prefer bins whose residual is below the mean (consolidate small residuals).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // New-bin candidate: make it attractive only when the item is large relative
    // to residual (poor fit anywhere) or late in the stream with big mean residual.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) / bin_residual as f64 > 0.7;
        if poor_fit || (fitting_bins_count <= 2 && mean_residual > 0.6 * bin_capacity as f64) {
            score -= 5.0;
        } else {
            score += 20.0; // discourage opening new bins when open bins fit well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial coupling to progress.
    let mut score = pr;

    // Tight-fit reward: quadratic bonus for small post-residual, stronger late in stream.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 40.0 * (0.5 + progress);

    // Penalize dead space: cubic growth of post-residual, amplified with progress.
    score += norm_pr * norm_pr * norm_pr * 60.0 * (0.3 + progress);

    // New-bin candidate penalty (residual == capacity): discourage unless nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 30.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // Lookahead: penalize if next item cannot fit the post-residual.
    if next_item_size > 0 {
        if (next_item_size as f64) > pr {
            score += 8.0 + 10.0 * progress;
        } else {
            score -= 6.0 * (1.0 - (next_item_size as f64) / cap) * (1.0 - progress);
        }
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing), smooth term.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 15.0;

    // Open-bin pressure: with many open bins, discourage spreading; favor consolidation.
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands. Small leftovers are "dead space" -> penalize.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let post_frac = post / cap;

    // Harmonic band index: 0 = tight fit (<=10% left), 1 = small (<=25%),
    // 2 = medium (<=50%), 3 = large (>50%).
    let band = if post_frac <= 0.10 { 0u32 }
        else if post_frac <= 0.25 { 1 }
        else if post_frac <= 0.50 { 2 }
        else { 3 };

    // Reward tight fits strongly, penalize large leftovers mildly.
    score -= match band { 0 => 60.0, 1 => 25.0, 2 => 0.0, _ => 15.0 };

    // Exact-fill bonus: perfect packing is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a harmonic pair -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let rem2 = post_residual - next_item_size;
            // Prefer chains that leave small tertiary residuals.
            score -= (rem2 as f64).min(50.0) * 0.4;
        } else {
            // Next item cannot continue here; if this bin is the only
            // fitting option, we must use it anyway.
            if fitting_bins_count <= 1 {
                score -= 40.0;
            } else {
                score += 10.0;
            }
        }
    }

    // Last-chance logic: if this is the only bin that fits the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // New-bin candidate handling: an empty bin has large residual.
    // Penalize opening a new bin unless current bins are nearly full
    // (mean residual small) or few bins are open.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        // If open bins have plenty of room on average, discourage new bin.
        score += 45.0 + mean_r * 0.3;
        // Early in the stream, having few bins, opening is cheaper.
        if open_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Modulo harmonic classes on post_residual: residuals that are
    // multiples of common small item sizes (10, 20, 25) are reusable.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer-division threshold: residuals below 10 are unusable dead
    // space for typical items -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Mild progression term: later in the stream, consolidation matters
    // more; slightly favor tighter fits as we approach the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 + (10 - post_residual as f64) * 5.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward using bins that are already fairly full (tight packing pressure).
    let fill_ratio = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bins pressure: penalize adding to a bin when many bins are open,
    // encouraging consolidation.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the current item
    // would leave a bad gap AND the next item is large (needs a big residual).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But if placement elsewhere would strand dead space and the next item
        // is big, a fresh bin becomes attractive.
        let dead_risk = post_residual > 0 && post_residual <= 9;
        if dead_risk && next_item_size as f64 >= bin_capacity as f64 * 0.5 {
            score -= 70.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 20.0;
    }

    // Lookahead: if the post residual exactly fits the next item, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // If next item would fit in post residual, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 10.0;
    }
    // If post residual is larger than max possible item but wasted relative to mean, penalize.
    if post_residual as f64 > mean_residual + 30.0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly prefer bins left with zero or near-zero residual.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next == post {
            score -= 60.0;
        } else if next < post {
            // Next item fits: penalize leftover dead space after hypothetical second placement.
            let second_post = post - next;
            if second_post <= 5.0 {
                score -= 40.0;
            } else {
                score += second_post * 0.3;
            }
        } else {
            // Next item cannot fit here: penalize bins that strand large residuals
            // unusable by the lookahead item.
            score += (next - post) * 0.5;
        }
    }

    // Compare post residual against mean residual across open bins:
    // prefer consuming bins with larger-than-average residual (big holes first).
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 30.0 * progress;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Mild penalty for very small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let post = post_residual as f64;
    score -= (bin_capacity as f64 - post) * 0.15; // fuller bin -> lower score

    // Penalize dead space: small but nonzero post_residual is wasteful.
    if post > 0.0 {
        let dead = (post / bin_capacity as f64).powf(1.7);
        score += dead * 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item can also fit here: mild reward proportional to fit quality
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot follow here: slight penalty
            score += 4.0;
        }
    }

    // Global state: many open bins with slack -> prefer consolidating into fuller bins.
    if open_bins_count > 2 {
        let dispersion = (mean_residual - post).abs();
        score += dispersion * 0.05;
        // crowding pressure: reward using existing bins when many are open
        if bin_residual != bin_capacity {
            score -= (open_bins_count as f64).ln() * 3.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive for large items
    // or when no reasonable fit exists (large post_residual would remain in any open bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Large item: new bin gives max flexibility.
        if item_size >= bin_capacity / 2 {
            score -= 10.0 + 10.0 * progress;
        }
        // If item leaves tiny space in any existing bin, new bin is fine.
        let would_leave = bin_residual - item_size;
        if would_leave <= 5 {
            score -= 12.0;
        }
        // Late in stream, avoid proliferating bins.
        if progress > 0.7 {
            score += 15.0 * progress;
        }
        // Many open bins: discourage new bin.
        score += open_bins_count as f64 * 2.0;
    }

    // Early stream: keep bins balanced slightly to preserve options.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 {
        score += (post / bin_capacity as f64) * 6.0 * (1.0 - progress * 3.33);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let r_norm = r / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post residual, non-linearly warped by stream progress.
    let mut score = r * (1.0 + 0.35 * progress * r_norm);

    // Smooth polynomial coupling: prefer moderate residuals early, tight fits late.
    let coupling = r_norm * r_norm - 2.0 * r_norm * item_norm;
    score += 40.0 * coupling * (1.0 - progress) + 55.0 * coupling * progress;

    // Penalize leaving dead space that no future item could plausibly use.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - r).max(0.0);
        score += 1.2 * gap * (1.0 + progress);
        // Reward bins whose post-residual exactly accommodates the next item.
        if (r as u32) == next_item_size {
            score -= 25.0 + 20.0 * progress;
        }
    } else {
        score += 0.8 * r;
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0 + 30.0 * progress;
    }

    // Mild penalty for spreading across many bins; deviation from mean residual.
    score += 0.4 * (r - mean_residual).abs();
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make it attractive only when no open bin is a good fit.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) - 10.0 * item_norm;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class of residual in capacity fractions (C=100): dead-space classes
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residuals that are too small to hold typical items (1..100, min 1)
    if post_residual > 0 {
        let too_small = post_residual < 10;
        if too_small {
            score += 60.0;
        }
    }

    // Modulo arithmetic on post_residual: harmonics of common item sizes
    let pr = post_residual as i64;
    let mut harmonic_bonus = 0.0;
    for &m in &[10i64, 20, 25, 50] {
        if pr % m == 0 && pr > 0 {
            harmonic_bonus += 15.0;
        }
    }
    score -= harmonic_bonus;

    // Next-item lookahead: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // post residual can host next item: mild reward proportional to slack
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item
            score += 8.0;
        }
    } else {
        // last item: strongly prefer exact fill
        score -= 200.0;
    }

    // Last-chance bin: if only this bin fits, avoid opening a new bin unless waste is huge
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 2 {
        score -= 120.0;
    }

    // New-bin candidate handling: neutral-ish score for empty bin, chosen only when fits are bad
    if bin_residual == bin_capacity {
        score = 0.5 * bin_capacity as f64 + 25.0 * (1.0 - frac) - harmonic_bonus;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin good for large incoming flow
        }
    }

    // Stream progression: tighten packing late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * mean_residual / (open_bins_count.max(1) as f64).sqrt();

    // Prefer filling bins below mean residual (larger residuals relative to mean)
    if (bin_residual as f64) > mean_residual {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps: residuals below the minimum item size are dead space
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Strong penalty for small-but-technically-usable gaps that few items can fill
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bins pressure: penalize opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty scaled by open bins pressure
        score += 40.0 + (open_bins_count as f64) * 8.0;
        // But if no existing bin fits well, allow new bin sometimes
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins close to the mean residual (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild early-stream preference for new bins to build diversity
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * (1.0 + 0.01 * (post_residual as f64 / bin_capacity as f64));

    // Lookahead: reward if next item fits exactly into the post residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            let slack = post_residual as f64 - next;
            // Reward exact match strongly
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 40.0; // perfect 2-item packing
            }
        } else {
            // Dead space the next item cannot use
            score += 0.5 * (next - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless it enables a great fit for the next item
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        let mut bonus = 0.0;
        if next_item_size > 0 {
            let slack = bin_capacity as f64 - next_item_size as f64 - item_size as f64;
            if slack == 0.0 {
                bonus = 55.0; // perfect pair in fresh bin
            } else if slack > 0.0 && slack < 20.0 {
                bonus = 20.0;
            }
        }
        // Late in stream, fewer open bins: new bins less costly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += base_penalty - bonus - 10.0 * progress;
    }

    // Penalize many open bins slightly to encourage consolidation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill (items >= 1, but typical >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (post_residual as f64 - next_item_size as f64).ln().max(0.0);
        } else {
            // Next item cannot follow here; mild penalty for creating awkward residual.
            score += 6.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless current item
    // fits poorly everywhere. Penalize the fresh bin mildly, more when open bins exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the item is huge relative to typical residual, a fresh bin is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress; // slight drift: later in stream, prefer consolidation
        if item_size >= 50 {
            score -= 5.0;
        }
    }

    // Global state coupling: if mean residual is high, prefer filling bins with
    // large residuals (consolidation); if low, tight fits dominate anyway.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins with larger residual when item is large.
    score -= 0.02 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Quadratic dead-space penalty, stronger late in the stream
    score += 18.0 * norm_pr * norm_pr * (0.4 + 0.8 * progress);

    // Reward tight fits via smooth saturation of item fill ratio
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill * (1.0 - fill) * 4.0;

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits = (next_item_size as f64) <= pr;
        let gap = ((next_item_size as f64) - pr).abs();
        if fits {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 * (gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bonus: smooth reward when few fitting bins exist
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.5 + 0.5 * progress);
    }

    // Mild dispersion penalty vs mean residual
    score += 0.05 * (pr - mean_residual).abs();

    // Penalize bin proliferation smoothly
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate adjustment: slightly discourage opening new bins early
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 2.0 * norm_pr * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // classes (e.g. multiples of 10) are "reusable" dead space; odd fragments are waste.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let harmonic = if pr == 0 {
        0.0 // perfect fit — best possible
    } else if pr % 10 == 0 {
        0.5
    } else if pr % 5 == 0 {
        1.0
    } else {
        1.8 // awkward fragment
    };
    score += harmonic * (pr as f64 / cap);

    // Reward tight fits (small post-residual relative to item).
    score -= 12.0 / (1.0 + post_residual as f64);

    // Lookahead: if the next item fits the post-residual exactly, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / cap);
        } else {
            // next item can't use this bin's remainder: penalize proportionally
            score += 3.0 * (next_item_size as f64 / cap);
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin when many open bins exist
    // and mean residual is large enough to host the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * progress;
        if mean_residual >= item_size as f64 {
            score += 12.0;
        }
    }

    // Slight preference for bins with below-mean residual (consolidate fullness).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: tight fit reward — lower post_residual is better, with superlinear penalty
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Dead space penalty: residuals too small for typical items are wasted.
    // Penalize gaps in the "unusable" band (roughly below 10 and below 25).
    if pr > 0.0 && pr < 10.0 {
        score += 60.0; // completely dead gap
    } else if pr < 25.0 {
        score += 12.0 * (25.0 - pr) / 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Exact match with lookahead item: keep this gap for next item
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 40.0;
    }
    // If next item fits the post residual, mildly favor preserving usability
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open bins pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score = 180.0 + 8.0 * open_bins_count as f64;
        // allow new bin if all existing fits would leave dead space
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - pr / cap);

    // Prefer bins below mean residual (more filled bins get priority)
    score += 0.15 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
