    // Reward tight fits relative to current residual (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 4.0 * tightness;

    // Penalize bins far from mean residual (prefer balanced or extreme-tight handling).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
