pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already low, but amplify.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Lookahead: if the next item can fit in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact pairing bonus (post_residual - next_item_size small = great)
            let pair_gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 6.0 * (1.0 - pair_gap);
        } else {
            // Next item won't fit here: penalize leaving awkward residual.
            let wasted = post_residual as f64 / bin_capacity as f64;
            score += 4.0 * wasted * wasted;
        }
    } else {
        // Last item: strongly prefer filling existing bins.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many
    // existing bins fit and how much residual is left in the system.
