pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: prefer small post_residual, with a smooth non-linear penalty
    // on mid-range residual (dead space that neither fits small nor large items).
    let mut score = r
        - 25.0 * (1.0 - (2.0 * norm_r - 1.0).powi(2)) * (0.5 + 0.5 * progress)
        + 12.0 * norm_r * norm_r * (1.0 - progress);

    // Perfect fit reward (smooth exponential decay of post-residual)
    score -= 30.0 * (-r / 5.0).exp() * (1.0 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead coupling: reward if next item fits smoothly into post_residual
    if next_item_size > 0 {
        let gap = (r - next_item_size as f64).abs();
        score -= 15.0 * (-gap / 10.0).exp();
        // penalize post_residual that is just barely too small for next item
        if r < next_item_size as f64 {
            score += 5.0 * (1.0 - r / next_item_size as f64);
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress * progress;

    // Coupling with mean residual: prefer bins close to the mean state
    let dev = (r - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quality classes.
    // Class 0: residual <= 10 (nearly perfect) -> strong reward.
    // Class 1: residual <= 20 -> moderate reward.
    // Class 2: residual in awkward band (21..=39) -> penalty (unusable for small items).
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 39 {
        score += 15.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair
    // well with the 10..80 item grid; reward exact decade fits.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Integer-division threshold: post_residual / 10 tiers.
    let tier = post_residual / 10;
    score += tier as f64 * 1.5;

    // Fit ratio coupling: tighter fit relative to residual is better.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 12.0;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space the next item cannot use
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mean-residual coupling: placing into a bin below mean residual
    // (tighter bin) is preferred; into a loose bin is penalized.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: empty bin gets a calibrated default.
    // Prefer opening a new bin only for large items or when it packs tightly.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        // base cost of opening a bin, discounted by how full the item makes it
        score = cap * (1.0 - fill) + 40.0;
        if item_size >= 60 {
            score -= 25.0; // large items justify fresh bins
        }
        if post_residual <= 20 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
