    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; later, tight fits matter more.
    let tightness = (pr / cap).powi(2);
    score += (1.0 + 3.0 * progress) * tightness * cap * 0.5;

    // Reward filling bins nearly exactly (quadratic valley at pr = 0).
