        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        // Next item would have fit before but not after this placement -> penalize.
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // slightly favor filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // New-bin candidate: make opening a new bin costly unless it is genuinely needed.
    if bin_residual == bin_capacity {
        score += 35.0 + 4.0 * open_bins_count as f64;
        // But allow new bin if no open bin gives a decent fit and item is large.
        if fitting_bins_count == 0 && item_size > 50 {
            score -= 50.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate waste).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild preference for placing into fuller bins (smaller bin_residual).
    score += 0.15 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits (dead space penalty is super-linear).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit is valuable: subtract proportional to how well next item fills leftover.
            let leftover2 = post_residual - next_item_size;
            score -= (next_item_size as f64) * 0.5;
            score += (leftover2 as f64) * 0.3;
        } else {
            // Next item won't fit here: penalize wasting residual that could chain.
            score += (next_item_size as f64) * 0.25;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-poor unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 5.0;
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: prefer bins where item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Lookahead: penalize leaving residual that next item cannot use
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // next item exactly fills leftover
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 0.05 * (next_item_size - post_residual) as f64; // dead space for lookahead
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 10.0;
        // Open new bin if current fits are loose (high mean residual) or no alternatives
        let poor_fits = mean_residual - post_residual as f64;
        if poor_fits > 20.0 {
            score -= 12.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // Too many open bins relative to items: discourage new bins
        if open_bins_count as f64 > (step_index.max(1) as f64).sqrt() * 2.0 {
            score += 15.0;
        }
    }

    // Mild preference for bins with residual close to mean (balance load)
    score += 0.03 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) shaping
    let mut score = pr + 60.0 * pr_norm * pr_norm * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is penalized more strongly (quadratic ramp)
    let progress_waste = (0.5 + 2.5 * progress) * (pr_norm * pr_norm) * cap;
    score += progress_waste;

    // Perfect-fit reward, smoothly scaled by progress
    let fit_quality = 1.0 - pr_norm;
    score -= 25.0 * fit_quality * fit_quality * (0.3 + 0.7 * progress);

    // Last-chance bin: strong smooth reward, decaying with progress
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress) * (1.0 - progress) + 6.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let gap_norm = gap / cap;
        score += 10.0 * gap_norm * gap_norm * cap;
        if pr >= next_item_size as f64 {
            score -= 8.0 * (1.0 - gap_norm) * (1.0 - progress);
        }
    }

    // Penalize bins whose residual deviates from mean residual (harmonic coupling)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap * (0.5 + progress);

    // Mild penalty for many open bins to encourage consolidation
    score += 0.4 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize mildly early, more strongly late (prefer reuse)
    if bin_residual == bin_capacity {
        score += 4.0 + 20.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity/8 classes.
    let class = post_residual / (bin_capacity / 8).max(1);
    score += class as f64 * 3.0;

    // Reward near-perfect fits (tiny dead space).
    if post_residual < 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead: does next item fit into post_residual? Strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Harmonic match: next item leaves an even smaller dead space.
        let next_post = post_residual - next_item_size;
        if next_post < 5 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space that next item cannot use: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if existing bins fit poorly.
    if bin_residual == bin_capacity {
        score = 55.0
            - (fitting_bins_count as f64) * 2.0
            + (open_bins_count as f64).sqrt() * 1.5
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can hold the next item too.
            score -= 5.0;
        }
        return score;
    }

    // Penalize bins whose residual is far from mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Tight-fit bonus scaled by how full the bin already is.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * fullness * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (<10) are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: smaller relative waste gets bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Penalize medium dead space that likely becomes unusable for future items
    // (typical items are >=10, so gaps of 1..9 dead; gaps 10..30 partially usable).
    if post_residual >= 10 && post_residual <= 30 {
        // usable but fragile: mild penalty scaled by how close to dead zone
        score += 0.4 * (30 - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item cannot use the leftover: penalize proportional to gap
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins open, filling existing bins is cheap anyway.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins whose residual is below mean (consolidate emptier space).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // New-bin candidate: default moderate score; only chosen if no open bin fits well.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.2 * open_bins_count as f64;
        // If item is large relative to capacity, opening fresh bin is more attractive.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // If it's the last fitting bin situation, a new bin is fallback anyway.
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward if next item fits into post_residual (good lookahead match).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward for tight-but-fitting lookahead.
        let slack = (post_residual - next_item_size) as f64;
        score -= (20.0 / (1.0 + slack)).min(10.0);
    } else if next_item_size > 0 {
        // Penalize creating dead space that the next item cannot use.
        score += 12.0;
    }

    // Penalize large post_residual relative to mean residual (wasteful placement).
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist that fit reasonably.
    if bin_residual == bin_capacity {
        score += 20.0;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 10.0;
        }
        // Early in stream, slightly cheaper to open bins (fewer alternatives).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Small penalty for tiny unusable residues (dead space under min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual already does this); amplify it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize leaving residual that only next_item barely misses,
    // reward residual that next item can still fit into.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual remains usable by the lookahead item
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of a fresh bin
        score += 25.0;
        score += 2.0 * open_bins_count as f64;
        // early in the stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // if mean residual across open bins is large, reusing is attractive -> penalize new bin more
        score += 0.4 * mean_residual;
        // if next item is large, keeping a fresh bin around is valuable
        score -= 0.3 * next_item_size as f64;
    } else {
        // existing bin: penalize more when it deviates from mean residual (fragmentation control)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Mild time-horizon scaling: as stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear penalty on wasted space, smoothed by stream progress
    let waste_frac = post / cap;
    score += 8.0 * waste_frac * waste_frac * cap * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 6.0 * (1.0 - waste_frac) * (1.0 - waste_frac) * progress;

    // Coupling with mean residual: prefer bins deviating from mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= post {
            let gap = post - ns;
            score -= 5.0 * (1.0 - gap / cap);
        } else {
            score += 2.0 * (ns - post) / cap;
        }
    }

    // Last-chance bin: penalize opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - progress);
    }

    // New-bin candidate: make it moderately attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score += 5.0 + 10.0 * (1.0 - crowd) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residual mod 10 dead-space classes
    let pr = post_residual;
    let class = pr % 10;
    // Penalize awkward residual classes that few item sizes (multiples of 10) can use
    score += match class {
        0 => -6.0,                 // perfect class: any multiple-of-10 item fits
        1 | 2 | 3 | 4 => 3.0 + class as f64, // small awkward slivers
        5 => 1.5,                  // half-class, moderately usable
        _ => 2.0 + (9 - class) as f64,
    };

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chain-friendly: reward proportionally to how well next item fills remainder
            let fill = next_item_size as f64 / pr.max(1) as f64;
            score -= 8.0 * fill;
        } else {
            // next item cannot use this bin's remainder: penalize dead space more
            score += 5.0;
        }
    } else {
        // last item: any residual is wasted; strongly prefer tight fit
        score += 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: opening fresh is only good if current fit is terrible
    if bin_residual == bin_capacity {
        // new bin baseline: slight penalty so it's chosen only when open bins are bad
        score = cap * 0.55;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Fractional coupling on how full the bin becomes
    let fill_frac = item_size as f64 / cap;
    score -= 6.0 * fill_frac;

    // Prefer bins with residual close to item size (tight packing)
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += 4.0 * tightness;

    // Stream progression: later in stream, favor closing bins (avoid many tiny residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (pr as f64 / cap);

    // Mean residual context: if open bins already have lots of slack, penalize adding more slack
    score += 0.05 * (mean_residual - pr as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically small gaps) are dead space -> heavy penalty.
    let dead_threshold = 12.0_f64;
    if post_residual > 0 {
        let waste = dead_threshold - post_residual as f64;
        if waste > 0.0 {
            score += 25.0 * waste; // unusable gap penalty
        }
    } else {
        // Perfect fill: strong reward
        score -= 40.0;
    }

    // Reward tight fits (post_residual small relative to bin capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover == 0 {
            score -= 30.0; // chain perfect fit
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual -> dead space risk
        score += 6.0 * (post_residual as f64 / dead_threshold);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, discourage spreading; encourage
    // filling existing bins, and penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow only if it looks clean
        score += 60.0 + pressure;
        // A new bin is attractive only when the item is large and no tight option exists
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    } else {
        // Filling existing bins reduces open-bin pressure slightly
        score -= pressure * 0.05;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item
    // (small leftover) and avoid bins with much larger residuals (waste potential)
    let residual_gap = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.05 * residual_gap.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fills
    // the post-residual, or at least fits into it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step chain: huge reward.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits after this placement.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.3 * slack;
        } else {
            // Next item won't fit here: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.15 * gap;
        }
    }

    // Penalize dead space relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.25 * (pr - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: keep it attractive only when it offers a genuinely
    // better long-term structure than existing bins.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish; lookahead already applied.
        score += 8.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 * progress;
        // If many bins are open, discourage spreading further.
        score += 0.5 * open_bins_count as f64;
    }

    // Mild penalty for very tight fits that leave unusable slivers (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward near-perfect fills of the current bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize large leftover space unless it can host the lookahead item.
    let wasted = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * wasted * wasted;

    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins whose leftover still fits the next item.
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize dead space that cannot host the lookahead item.
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: just minimize waste directly.
        score -= 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist; prefer tightest fit among them.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Tight fits are valuable: reward small post_residual relative to item size.
    score -= 15.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
    score -= crowding * 0.05 * (0.5 + progress);

    // New-bin candidate handling: make an empty bin attractive only when it looks genuinely better.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post residual), non-linearly.
    let mut score = x * x * (2.0 - x); // smooth cubic penalizing large leftover

    // Non-linear coupling of post residual with stream progress:
    // early on, tolerate larger leftovers (keep bins flexible);
    // late in the stream, strongly penalize dead space.
    let tightness = 1.0 + 2.5 * progress * progress;
    score += tightness * x * x;

    // Interaction: post residual vs. next item size — reward bins whose
    // leftover can host the lookahead item; penalize near-miss leftovers.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = ((pr - nxt) as f64).abs() / cap;
        score -= 1.2 * fits_next * (1.0 - gap * gap) / (1.0 + progress);
        score += 0.8 * (1.0 - fits_next) * (1.0 - gap) * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 1.5 * (1.0 - x * x);
    }

    // Mild penalty for many open bins with scattered residuals; encourage consolidation.
    let spread = (mean_residual - pr) / cap;
    score += 0.3 * spread * spread * (open_bins_count as f64).ln1p();

    // Slight preference for using existing bins over a fresh empty bin
    // unless the fit is excellent (x near 0) or the stream is early.
    if bin_residual == bin_capacity {
        score += 0.6 + 1.5 * progress * (1.0 - x * x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (multiples of common small sizes), penalize dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect closure
    } else if pr % 10 == 0 {
        score -= 6.0; // clean class, reusable by 10-multiples
    } else if pr < 10 {
        score += 25.0; // dead space below min item size
    } else {
        // penalize awkward remainders: distance to nearest multiple of 10
        let dist = (pr % 10).min(10 - pr % 10) as f64;
        score += 1.5 * dist;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0 - 0.15 * (next_item_size as f64);
        } else if pr > 0 && next_item_size > pr {
            // next item won't fit here; slight penalty scaled by gap
            let gap = (next_item_size - pr) as f64;
            score += 0.1 * gap.min(40.0);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        score += 15.0
            - 2.0 * crowd
            + (mean_residual - item_size as f64).max(0.0) * 0.3;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0; // next item needs a fresh bin anyway
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual divergence: bins far below mean residual are worth filling.
    score -= 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are "dead".
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space penalty grows as the gap becomes more hopeless.
            let hopelessness = 1.0 - (post_residual as f64 / next_item_size.max(1) as f64);
            score += 12.0 * hopelessness * hopelessness;
        } else {
            // Gap that can still host the next item is valuable: reward it.
            score -= 4.0;
        }
        // Perfect fit for the lookahead item: strong reward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Zero post-residual is a perfect packing: heavily favored.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 0.05 * open_bins_count as f64;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into tight fits.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than average (they are closer to closing).
    if mean_residual > 0.0 {
        let tightness = 1.0 - (bin_residual as f64 / mean_residual);
        if tightness > 0.0 {
            score -= 3.0 * tightness;
        } else {
            score += 3.0 * (-tightness);
        }
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // and no good consolidation exists; otherwise discourage strongly.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 15.0 * big_item;
        // If existing bins can fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Early in stream, new bins are cheap; later, avoid fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly in post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // perfect chain: item + next fill bin completely
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how tightly next item nests in residual
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize large dead space that blocks it
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.6 * overflow;
        }
    }

    // Penalize residual far above mean residual (wasteful large leftover)
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer new bin early (reserve capacity) but discourage when open bins fit well
        score = 200.0 - 100.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin keeps full room for lookahead, mild bonus
            score -= 40.0;
        }
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 60.0; // discourage abandoning tight fits
        }
    }

    // Slight preference to fill bins with less residual overall
    score += 0.3 * (bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize small unusable leftovers (< next_item_size or < min item size ~1).
    if post_residual > 0 {
        let min_next = if next_item_size > 0 { next_item_size } else { 1 };
        if (post_residual as u64) < (min_next as u64) {
            score += 15.0;
        }
        // Dead-space penalty scaled by how much of the bin is wasted.
        score += 0.05 * (post_residual as f64).powf(1.3);
    }

    // Lookahead: reward bins whose post_residual fits the next item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 8.0 * chain_quality;
    } else if next_item_size > 0 {
        // Post-residual can't hold next item: mild penalty, worse late in stream.
        score += 3.0 + 4.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let best_possible_waste = if next_item_size > 0 {
            (bin_capacity - item_size - next_item_size.min(bin_capacity - item_size)) as f64
        } else {
            (bin_capacity - item_size) as f64
        };
        // Base new-bin score: its post_residual is large, already high.
        // Discount slightly when open bins are crowded (mean residual low) or few fit.
        if open_bins_count == 0 || (fitting_bins_count <= 1 && mean_residual < item_size as f64 * 1.5) {
            score -= 12.0 * (1.0 - progress);
        }
        // Penalize opening new bins when plenty of slack exists elsewhere.
        if mean_residual > 2.0 * item_size as f64 {
            score += 10.0;
        }
        let _ = best_possible_waste;
    }

    // Congestion-aware scaling: when many bins are open, prefer consolidating
    // (favor bins with below-mean residual usage).
    if open_bins_count > 1 {
        let residual_gap = mean_residual - bin_residual as f64;
        score -= 0.3 * residual_gap;
    }

    // Late-stream urgency: fill bins tighter as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = 1.0 + t * t * (3.0 - 2.0 * t); // smooth hermite-like blend
    score *= 0.7 + 0.6 * poly;

    // Penalize large dead space more than linearly (quadratic term)
    let frac = pr / c;
    score += 30.0 * frac * frac * (0.5 + t);

    // Reward tight fits (small post_residual)
    if pr <= 5.0 {
        score -= 40.0 * (1.0 - t);
    } else {
        score -= 20.0 * (-pr as f64 / 15.0).exp() * (1.0 - t);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = pr - nx;
            score -= 30.0 * (-gap / 10.0).exp();
        } else {
            score += 8.0 * (nx - pr) / c;
        }
    }

    // Prefer filling bins with low residual relative to fleet mean
    score += 5.0 * (pr - mean_residual) / c;

    // Mild pressure toward consolidating bins when many are open
    score += 0.3 * (open_bins_count as f64).sqrt() * (pr / c);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
