pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // --- Perfect fit: strongest reward ---
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // --- Harmonic class of post_residual (mod 10 buckets) ---
    // Dead space < 10 is unusable for items (min size 1, but small residuals waste capacity).
    let pr = post_residual;
    if pr < 5 {
        score += 25.0; // tiny dead space penalty
    } else if pr < 10 {
        score += 15.0;
    }

    // Modulo arithmetic: residuals that are multiples of 10 pair well with
    // common item sizes; slightly reward harmonic alignment.
    if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // --- Lookahead (k=2): does next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain-friendly: reward proportionally to how snugly next item fits
            let snug = 1.0 - (pr as f64 - next_item_size as f64) / cap;
            score -= 8.0 + 12.0 * snug;
        } else {
            // Next item won't fit here: mild penalty scaled by wasted potential
            score += 4.0 * (next_item_size as f64 / cap);
        }
    }

    // --- Last chance: this is the only bin that fits; avoid opening new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: keep high so we prefer reusing bins.
        score = cap + 20.0;
        // Early in the stream, opening bins is fine (build a portfolio).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
        // Large items relative to residual: new bin is natural.
        score -= 10.0 * (item_size as f64 / cap);
        // If open bins are already crowded on average, new bin less bad.
        score -= 5.0 * (mean_residual / cap).min(1.0);
        // Never open a new bin when a perfect-fit alternative exists is handled
        // by their low scores; but if this is the only fitting option, allow it.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Don't open new bin for a small item late in the stream.
        if item_size < 30 && progress > 0.5 {
            score += 40.0;
        }
    }

    // --- Tightness coupling: prefer bins where item fills a large fraction ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio.min(1.0);

    // --- Open bin count pressure: many open bins -> consolidate ---
    score += 0.5 * open_bins_count as f64;

    // --- Mean residual coupling: prefer bins below mean residual (tighter bins) ---
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
