pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize wasting residual.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global state coupling: when many bins are open, discourage new bins implicitly
    // by favoring existing bins; the new-bin candidate has bin_residual == bin_capacity,
    // so give it a penalty that grows with open_bins_count.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * (open_bins_count as f64);
        // Early in the stream, opening bins is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
    }

    // Favor bins whose residual is below mean (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Time horizon: late in stream, be more greedy about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (item_size as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear penalty on awkward middling residuals
    let mut score = pr;
    score += 40.0 * norm_pr * (1.0 - norm_pr) * (norm_pr - 0.5) * (norm_pr - 0.5) * 4.0;

    // Smooth progress coupling: tighten residual preference as stream advances
    let tight = 1.0 - progress;
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    score += 20.0 * norm_pr * tight;

    // Dead-space coupling with mean residual of open bins
    let dev = (pr as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = if pr >= nx { 1.0 } else { 0.0 };
        score -= 25.0 * fit_next * (nx / cap) * (1.0 - 0.5 * progress);
        // penalize leaving slightly-less-than-next residuals (near-miss waste)
        let miss = (pr - nx) / cap;
        if miss < 0.0 && miss > -0.2 {
            score += 35.0 * (-miss) * (1.0 - (-miss) / 0.2);
        }
    }

    // Mild penalty for bin proliferation late in the stream
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: quarter classes (0-24, 25-49, 50-74, 75-99)
    let class = post_residual / (bin_capacity / 4).max(1);
    let class_penalty = match class {
        0 => -14.0, // near-perfect fit: dead space is minimal
        1 => -4.0,
        2 => 6.0,
        _ => 12.0,  // large dead space
    };
    score += class_penalty;

    // Reward if the lookahead item fits exactly into the post-residual (chaining)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // partial reward scaled by how well it fills
            let fill = nxt / post.max(1.0);
            score -= 10.0 * fill;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 4.0 * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when residual is huge relative to item
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted if item is large
        score = cap * 0.55 - item_size as f64 * 0.45;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
        if open_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
    }

    // Progression: early in stream, tolerate slack slightly more (future items may fit)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (post / cap);

    // Deviation from mean residual: prefer bins whose residual is close to the item need
    let dev = (mean_residual - bin_residual as f64).abs() / cap;
    score += 5.0 * dev;

    // Fine modular nudge: post_residual divisible by 10 pairs well with decimal item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps (1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits: post_residual close to 0 relative to bin capacity.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // over opening a new bin (unless post_residual creates dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 25.0; // next item will perfectly (nearly) fill this bin
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: this residual is likely dead space.
        score += 15.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to number of open bins,
        // and to how much mean residual is being wasted by opening a new bin.
        score += 35.0 + 4.0 * open_bins_count as f64 + 0.3 * mean_residual;
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Using an existing bin reduces open-bin pressure slightly.
        score -= 1.5 * open_bins_count as f64;
    }

    // Mild preference for bins with smaller residuals (fill fuller bins first).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically (wasted capacity grows superlinearly in cost).
    score += 0.02 * (post_residual as f64) * (post_residual as f64);

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            // Exact 2-item match is ideal: residual becomes zero after next item.
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how much dead space remains unusable for the lookahead item.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Reward tight fits relative to the current item (small post_residual vs item).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 8.0 * (1.0 / (1.0 + tightness));

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Relative-to-mean coupling: prefer bins that are already "more filled"
    // than average (smaller residual than the mean).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidate aggressively to avoid leftover bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

