    // open bin gives a decent fit. Penalize the fresh bin (bin_residual == capacity),
    // scaled by how many bins already fit the item.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 45.0 * pressure + 0.5 * open_bins_count as f64;
    }

