    let cap = bin_capacity as f64;
    let pr = post_residual;
    let class = (pr % 10) as f64;
    let decade = (pr / 10) as f64;

    // Reward post-residuals that fall into "usable" harmonic classes.
    // Residuals that are multiples of 10 or match common small item sizes
    // (10..=20) are more likely to be filled later.
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0; // nearly full, tiny dead space
    } else if pr <= 20 {
        score -= 10.0;
    } else {
