            score -= 20.0 - slack * 0.5;
        } else {
            // next item cannot use this residual: mild penalty scaled by gap
            score += ((next_item_size - pr) as f64) * 0.3;
        }
    }

    // Last-chance bin: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Crowding: if many bins are open, prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.15 * (0.5 + progress);

