    // bins are already open; encourage consolidation.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if next item fits the post-residual, reward; if it
    // would be stranded, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 10.0;
        }
    }

    // Mean-residual coupling: placing into a bin whose residual deviates strongly
    // from the mean residual is slightly discouraged (keeps residual profile uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Neutral baseline; last-chance bonus on real bins will usually win.
        score = 45.0 - 12.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: new bin is necessary
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // Mild penalty so existing decent fits are preferred.
            score += 5.0;
