pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 + progress) - pr_norm * progress * progress;
    score += 8.0 * poly;

    // Reward tight fits more strongly later in the stream.
    let tightness = 1.0 - pr_norm;
    score -= (item_size as f64 / bin_capacity as f64) * (1.0 + 2.0 * progress) * (1.0 + tightness);

    // Penalize dead space relative to mean residual across open bins.
    score += 0.5 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving space close to next item size (smooth coupling).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        score += 3.0 * (gap / bin_capacity as f64) * (1.0 + next_norm) - 2.0 * next_norm * (1.0 - progress);
    }

    // Mildly discourage spreading across many open bins early on.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 1.5;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
        score = 40.0 + 30.0 * (1.0 - progress) - 0.3 * pressure + 10.0 * (fitting_bins_count as f64).min(3.0);
    }

    score
