    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, discourage spreading; favor compacting.
    if open_bins_count > 3 {
        score += 2.0 * (open_bins_count as f64).ln();
    }

