    if bin_residual == bin_capacity {
        score += 45.0 + 20.0 * (1.0 - t) - 10.0 * x;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo classes of capacity fractions.
    // Residuals that are "harmonic" with common item sizes (divisible by 10/20/25)
    // are more reusable, so reward (subtract) them.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let harmonic = if pr == 0 { 3.0 }
        else if pr % 25 == 0 { 2.0 }
        else if pr % 20 == 0 { 1.5 }
        else if pr % 10 == 0 { 1.0 }
        else if pr % 5 == 0 { 0.5 }
        else { 0.0 };
    score -= harmonic * (pr as f64 / cap) * 8.0;

    // Integer-division threshold: small dead space (< next_item_size) is unusable
    // for the lookahead item -> penalize proportionally to how close it is.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Perfect fit for the next item is very valuable.
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // Quotient classes: post_residual / next_item_size tells how many
        // lookahead items still fit; reward high quotients.
        let q = post_residual / next_item_size.max(1);
        score -= (q as f64).min(4.0) * 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit here
    // would leave a bad (non-harmonic, large) residual or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // Cheaper to open when many bins are open and mean residual is high (fragmented).
        score -= (open_bins_count as f64).min(10.0) * 0.4;
        score -= (mean_residual / cap).min(1.0) * 5.0;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 8.0;
    } else {
        // Prefer tighter fills among open bins: penalize large pre-residual slack.
        score += (bin_residual as f64 - item_size as f64) * 0.05;
