    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins exist.
        score += open_bins_count as f64 * 8.0;
        // But if no existing bin fits well (this is a last-chance scenario),
        // relax the penalty when fitting bins are scarce.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    } else {
        // Existing bin: slight reward when it's one of few fitting bins.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // Progress-based pressure: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - pr / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - pr) * 0.15;

    score
}

