    if post_residual > 40.0 {
        score += (1.0 - progress) * 5.0;
    }

    // New-bin candidate: only attractive when item is large or current bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        let big_item = item_size as f64 > 0.6 * cap;
        if big_item || fragmentation > 20.0 {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    score
}

