    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to leftover waste.
            score += 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: encourage filling existing bins rather than spreading.
    if open_bins_count > 1 {
        score -= 5.0 * ((open_bins_count as f64).ln());
    }

    // Compare against mean residual: bins with residual near the mean are "normal";
    // prefer placing into bins whose residual is close to item_size (efficient packing).
    let res_diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * res_diff;

    // Time horizon: early in the stream, be more conservative (slight penalty for near-full bins
    // to keep flexibility); later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Prefer it only when no open bin fits well (large residual diff) or stream is early.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = res_diff > 0.0; // always true for empty bin; use mean residual instead
        let _ = poor_fit_elsewhere;
        // Base penalty so new bins are opened only when genuinely better.
        score += 35.0;
        // Early stream: new bins are cheaper (more future items to fill them).
        score -= 25.0 * (1.0 - progress);
        // If many open bins already, avoid opening yet another unless necessary.
        score += 6.0 * (open_bins_count as f64);
        // If mean residual across open bins is large, open bins are underused -> penalize new bin.
        score += 0.5 * mean_residual;
        // If next item is large and this bin would be nearly filled by current item,
        // a fresh bin keeps flexibility.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 10.0;
        }
        // If this is the only option (no fitting open bins), allow the new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Small global-state coupling: if mean residual is high, prefer bins that reduce variance
    // (i.e., residual close to mean after placement).
    let post_dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * post_dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer small post-residual (tight fits), with non-linear sharpening.
    let mut score = post * (1.0 + 0.9 * (post / cap) * (post / cap));

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space; late, punish it harder.
    let progress_weight = 0.35 + 1.15 * progress * progress;
    score += progress_weight * post;

    // Reward tight fits (small post) with a smooth quadratic bonus.
    score -= 45.0 * (1.0 - post / cap).powi(3);

    // Lookahead: reward bins whose post-residual can host the next item,
    // scaled smoothly by how much slack remains.
    if nxt > 0.0 {
        let usable = (post - nxt).max(0.0) / cap;
        let fits_next = if post >= nxt { 1.0 } else { 0.0 };
        score -= 18.0 * fits_next * (0.5 + usable);
        // Penalize post-residual just barely below next item (dead space trap).
        let gap = (nxt - post).max(0.0) / cap;
        score += 14.0 * gap * (1.0 - gap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty for spreading across many bins when alternatives exist.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps bin population balanced), penalize outliers smoothly.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate handling: it is only attractive when no good fit exists.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        // Cost of opening a new bin decays as stream progresses (sunk costs),
        // but grows with the number of already-open bins.
        let open_cost = 55.0 + 6.0 * open_bins_count as f64 - 25.0 * progress;
        // If the item would leave a large unusable hole in an existing bin,
        // opening fresh is relatively better.
        let hole_penalty = 0.6 * post;
        score = open_cost + hole_penalty;
        // If next item fits well in the fresh bin, small discount.
        if nxt > 0.0 && post >= nxt {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it land in?
    let q = post_residual / 10; // coarse class 0..=10
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize dead space that no plausible item can fill.
    // Classes: q==0 perfect fit (reward heavily), small residuals 1..=9 are "wasted slivers"
    // unless a known next item fits.
    match q {
        0 => { score -= 60.0; }
        1 | 2 | 3 => {
            // sliver zone (1..=39): dead space risk
            score += (4 - q) as f64 * 8.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 25.0; // lookahead rescues the sliver
