        4 | 5 | 6 => {
            // mid zone (40..=69): decent for medium items
            score += 5.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 18.0;
            }
        }
        _ => {
            // large residual (70+): bin stays flexible
            score -= 8.0;
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 12.0;
            }
        }
    }

    // Integer-division harmonic coupling: post_residual % 20 bands.
    let rem = post_residual % 20;
    if rem == 0 && post_residual > 0 {
        score -= 6.0; // round residual aligns with common item sizes
    } else if rem > 0 && rem < 10 && post_residual < 40 {
        score += 7.0; // awkward sub-10 leftover in a nearly full bin
    }

    // Last-chance bonus: only this bin fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate logic: opening a new bin is attractive only when the item
    // is large relative to capacity and open-bin residuals are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight = mean_residual < 35.0;
        if item_size >= 50 && tight {
            score -= 15.0;
        } else if item_size >= 70 {
            score -= 10.0;
        } else if fitting_bins_count > 0 {
            score += 25.0; // prefer existing bins for small/medium items
        }
        if progress > 0.9 && open_bins_count > 3 {
            score += 10.0; // late stream: consolidate rather than open
        }
    } else {
        // Prefer filling bins that are already committed (high fill ratio).
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 10.0;
        // Slight preference for bins whose residual is close to mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
        // Too many open bins: push toward consolidating into fuller bins.
        if open_bins_count > 6 {
            score -= 4.0;
        }
    }

    // Perfect-fit harmonic reward via modulo classes of item_size vs capacity.
    if bin_capacity % item_size.max(1) == 0 && post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // --- Strict dead space avoidance ---
    // Small post-residuals (< 15) are likely unusable dead space: penalize heavily,
    // proportional to how close the gap is to the worst dead zone.
    if !is_new_bin {
        if post_residual < 15 {
            score += (15.0 - post_residual as f64) * 5.0;
        } else if post_residual <= 25 {
            // moderate dead zone: mild penalty
            score += 8.0;
        } else {
            // large leftover space is reusable: reward it
            score -= (post_residual as f64 - 25.0).min(50.0) * 0.15;
        }

        // Reward tight fits (item fills most of the bin's current residual)
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 20.0;
    }

    // --- Open bins pressure: consolidate into existing bins when many are open ---
    if !is_new_bin {
        score -= (open_bins_count as f64).min(20.0) * 1.2;
    }

    // --- Last chance bin: strongly favor using it before opening a new one ---
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // Base cost of opening a new bin, growing with the number of already open bins
        let mut new_bin_cost = 25.0 + 2.5 * open_bins_count as f64;
        // If few bins can fit this item, opening a new bin is less bad
        if fitting_bins_count <= 1 {
            new_bin_cost -= 20.0;
        }
        // Late in the stream, prefer consolidation slightly more
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_cost *= 1.0 + 0.3 * progress;
        score += new_bin_cost;
    }

    // --- Lookahead (k=2): does the next item fit in the resulting gap? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item can reuse the leftover: reward
            score -= 10.0;
        } else if !is_new_bin && post_residual < 15 {
            // dead space that even the next item can't use: extra penalty
            score += (next_item_size.min(80) as f64) * 0.2;
        }
    }

    // --- Mean residual coupling: if this bin is far below average residual,
    //     it is the "emptiest" bin; prefer filling emptier bins to keep
    //     tight bins available for small future items. ---
    if !is_new_bin {
        let dev = mean_residual - post_residual as f64;
        score += dev * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize leftover after chain placement
            let chain_left = post_residual as f64 - next_item_size as f64;
            score -= 80.0 * (1.0 - chain_left / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space more strongly
            score += 0.6 * post_residual as f64;
        }
    }

    // Relative to mean residual: prefer bins with residuals close to item (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // Prefer filling bins with larger residuals relative to mean
    if bin_residual as f64 > mean_residual {
        score -= 15.0;
    } else {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let waste_threshold = 0.25 * bin_capacity as f64;
        if post_residual as f64 > waste_threshold {
            score += 400.0; // don't open new bin for a wasteful placement
        } else {
            score += 50.0;
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste-aware, quadratic penalty on post residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
