    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in the stream, be more conservative — favor closing bins
    // out completely rather than leaving slivers.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    // New-bin candidate: make it attractive only when the item is large relative
