    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = 40.0 * item_frac + 20.0 * (1.0 - item_frac);
        // If many bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 12.0;
