pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "wasted" is the leftover space?
    // Residuals in low modulo classes (small leftovers) are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of the bin wasted after placement (non-linear penalty).
    let waste_frac = pr / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Harmonic class via integer division thresholds on post_residual.
    // Class 0: post_residual < 10  -> nearly perfect fit, big reward.
    // Class 1: post_residual < 30  -> small leftover, mild reward.
    // Class 2: post_residual < 60  -> medium leftover, neutral.
    // Class 3: post_residual >= 60 -> large leftover, penalize (bin is being fragmented).
    let class = if post_residual < 10 { 0 } else if post_residual < 30 { 1 } else if post_residual < 60 { 2 } else { 3 };
    match class {
        0 => score -= 25.0,
        1 => score -= 10.0,
        2 => score += 5.0,
        _ => score += 15.0,
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that cannot (creating a stranded bin).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            // Dead bin: leftover too small for anything useful (below min size 1).
            if post_residual < 10 {
                score += 20.0;
            }
        }
        // Harmonic modulo logic: if next item fits with a tiny remainder,
        // this is a near-perfect chain placement.
        let rem = post_residual % next_item_size.max(1);
        if next_item_size > 0 && post_residual >= next_item_size && rem < 10 {
            score -= 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= 30 {
            score -= 15.0;
        }
    }

    // New-bin candidate: only attractive when open bins are crowded or the fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Cheap early in the stream; expensive when many bins are already open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
        score += 2.0 * open_bins_count as f64;
        // If the average residual across open bins is large, prefer existing bins.
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        // If next item is small, a fresh bin can absorb it well later; slight discount.
        if next_item_size > 0 && next_item_size <= 20 {
            score -= 6.0;
        }
    }

    // Mild preference for bins with less residual overall (best-fit flavor),
    // scaled by how many alternatives exist.
    if fitting_bins_count > 1 {
        score += 0.1 * bin_residual as f64;
    }

    // Mean residual coupling: if this bin's residual is far above the mean,
    // it is a good "sponge" bin to fill.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (1..=100) are dead weight. Penalize gaps below a usable
    // threshold with a super-linear blowup.
    let usable_threshold = 30.0f64;
    if (post_residual as f64) < usable_threshold {
        let gap = usable_threshold - post_residual as f64;
        score += gap * gap * 0.9; // quadratic dead-space penalty
    }

    // Reward near-perfect fits (tiny post_residual is excellent, not dead).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // disfavor opening new bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score -= 6.0; // fresh bin has full residual, base already high
        score += pressure * 4.0;
    } else {
        score -= pressure * 1.5;
    }

    // Lookahead (k=2): if the next item fits exactly into the post_residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            // next item can't use this gap anyway; dead space is more tolerable
            score += 2.0;
        }
    }

    // Mean-residual coupling: if open bins are already tight on average,
    // prefer placing into this bin rather than fragmenting further.
    if bin_residual != bin_capacity && (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Slight mid-stream tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins that end exactly full.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 700.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves a further fragment: mild penalty
            // proportional to the double-fragment dead space.
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot fit here: penalize more as the leftover
            // fragment becomes small and hard to reuse.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer placing into bins with more
    // residual than average (larger bins get filled first).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize creating tiny unusable fragments (below minimum item size 1..10
    // heuristic: fragments < 10 are near-dead space).
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }

    // Early in the stream, be more willing to open new bins? No: prefer
    // consolidation early; later, allow new bins since lookahead is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress;

    // Slight penalty for opening a brand-new bin when many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind, especially if it cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            // Dead space for the lookahead item: penalize more when post_residual is small but nonzero.
            let waste = post_residual as f64 / cap;
            score += 8.0 * waste * waste;
        } else {
            // Reward bins that can also host the next item.
            score -= 6.0;
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score += 2.0 * (post_residual as f64 / cap);
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early in the stream
    // or when few bins are open; otherwise prefer packing into existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let time_pressure = progress * progress;
        let crowding = (open_bins_count as f64).ln().max(0.0) / 4.0;
        score += 10.0 + 25.0 * time_pressure + 10.0 * crowding;

