        // Reward using bins with below-average residual (consolidating space).
        let rel = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * rel;
    }

    // Mild preference for filling nearly-full bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

