    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight fit reward: strongly favor small post residuals (quadratic waste penalty)
    let waste_frac = pr / cap;
    score += waste_frac * waste_frac * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item fits in the post residual (keep room usable),
    // reward if this bin can host the next item too.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as u32) >= next_item_size {
            score -= 6.0 * (1.0 - ni / cap);
        } else {
            score += 3.0 * (ni / cap);
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate handling: a fresh empty bin should only win when open bins
    // would leave large unusable waste or are few.
    if bin_residual == bin_capacity {
