        // prefer placing into bins with residual close to item (harmonic packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05 * (0.5 + progress);
    }

    // Smooth stream-progress coupling: later in stream, waste matters more
    score *= 1.0 + 0.5 * progress * (pr / cap);

    score
}

