 if bin_residual == bin_capacity && next_item_size > 0 && next_item_size <= bin_capacity && fitting_bins_count > 0 && open_bins_count > 1 { let nr = bin_capacity - next_item_size ; if nr < 8 { score += 2.2 ; } } // GEN145: reward open bins whose post-residual tightly bounds next item (fine-grained fit) when few alternatives exist
 if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 4 { let slack = post_residual - next_item_size ; if slack <= 3 { score -= 1.6 + 0.4 * (3 - slack) as f64 ; } } // GEN145: penalize mid-sized leftover space that fits neither next item nor mean demand (dead-space ratio)
 if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && (post_residual as f64) < mean_residual * 0.5 && open_bins_count > 5 { score += 0.8 ; } // GEN145: late-stream — strongly prefer filling existing tight residuals over opening bins
 if total_items > 0 && step_index > total_items * 3 / 4 && post_residual > 0 && post_residual < 12 && fitting_bins_count > 1 { score -= 1.3 ; } // GEN145: dead-space ratio compaction — penalize bins whose post-residual is too small for mean demand but nonzero (fragmentation)
 if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size && (post_residual as f64) < mean_residual * 0.7 { score += 0.6 * (1.0 - post_residual as f64 / (mean_residual * 0.7)) ; } // GEN145: lookahead coupling — reward bins where next item leaves room equal to next_item_size (chain fill)
 if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size { score -= 1.0 ; } // GEN145: strong tight-fit bonus for slack <= 1 regardless of competition (reduce dead space)
 if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 1 { score -= 2.0 ; } // GEN145: penalize opening fresh bins when mean residual can host next item
 if bin_residual == bin_capacity && next_item_size > 0 && open_bins_count > 2 && (mean_residual as u32) >= next_item_size { score += 1.0 ; } score }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Define "unusable" relative to the smallest plausible item (1..100 unknown, use 10 as soft floor
    // and next_item_size as a hard lookahead floor when available).
    let soft_floor = 10u32;
    let hard_floor = if next_item_size > 0 { next_item_size.min(soft_floor.max(1)) } else { soft_floor };

    if post_residual > 0 && post_residual < hard_floor {
        // Dead space: gap too small for the next item or any typical item.
        let severity = (hard_floor - post_residual) as f64;
        score += 3.0 * severity + 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin completely.
        score -= 40.0;
    } else if post_residual < soft_floor {
        // Partially dead space: mildly penalize.
        score += 0.5 * (soft_floor - post_residual) as f64;
    } else {
        // Usable residual: reward larger usable gaps slightly (keeps bins flexible),
        // but reward exact matches with the next item even more.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0; // next item fills this bin exactly
        } else if next_item_size > 0 && post_residual > next_item_size {
            score -= 2.0; // next item still fits here: keep this bin attractive
        } else if next_item_size > 0 {
            score += 4.0; // next item cannot use this residual: discourage
        }
    }

    // Reward tight fits generally: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets a large
    // post_residual and thus a naturally high score; reinforce with a penalty term
    // proportional to open bins applied to large residuals).
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += (open_bins_count as f64).sqrt() * 2.0 * residual_frac;

    // Last-chance bonus: if this is the ONLY bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates below the mean
    // (concentrate filling into emptier-tail bins to close them sooner).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Stream progression: late in the stream, be more aggressive about closing bins
    // (favor tight fits, penalize leaving scattered residuals).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0 * residual_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step match: huge reward
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits; reward proportional to tightness of the 2-step fill
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.6;
        } else {
            // Next item won't fit in this bin after placement; penalize
            let overshoot = (next_item_size - post_residual) as f64;
            score += 5.0 + overshoot * 0.3;
        }
    }

    // Penalize large dead space relative to mean residual
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.4;
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Brand-new bin candidate: neutral-ish baseline, only preferred when
    // existing bins would create bad fits
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Late in stream, prefer tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 8.0;

    // Penalize dead space: residuals too small for the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }
    if post_residual > 0 && post_residual < next_item_size as f64 {
        score += 3.0; // creates space the lookahead item can't use
    }

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // perfect chaining
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when fits are poor
    if bin_residual == bin_capacity {
        // Base cost of a new bin
        score += 25.0;
        // Encourage new bin early in stream (plenty of future items to fill it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= (1.0 - progress) * 10.0;
        // Discourage new bins when many bins already open
        score += open_bins_count as f64 * 1.5;
        // If this is the only fitting option, new bin is fine
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Prefer bins whose residual is close to mean (balance exploitation)
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.3;
    }

    // Mild preference for fuller bins overall
    score += (bin_capacity as f64 - bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste penalty: dead space hurts more as stream progresses
    let norm_post = post / cap;
    score += 6.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item)
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fill * fill;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead: bonus if next item fits into post_residual exactly-ish
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 3.0 * (1.0 - gap) * (1.0 - gap);
    } else if next_item_size > 0 {
        // next item won't fit here; penalize leaving awkward residual
        score += 2.0 * norm_post;
    }

    // New-bin candidate: prefer opening a new bin when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).abs() / cap;
        score += 3.0 - 2.5 * progress + 1.5 * fragmentation;
        // early stream: opening bins is cheap
        if open_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Prefer bins with residual below mean (consolidate emptier space)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: reward residuals that are multiples of common item granularity
    let class = post_residual % 10;
    if class == 0 {
        score -= 15.0;
    } else if class <= 3 {
        score += 8.0; // tiny dead space is bad
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space unusable by next item: penalize proportionally
        score += post_residual as f64 * 0.8;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only open new bin when current fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        // penalize new bins moderately; allow opening when mean residual is fragmented
        score += 60.0 - 40.0 * progress;
        if mean_residual > 0.0 && mean_residual < item_size as f64 * 0.5 {
            score -= 30.0;
        }
        if post_residual == bin_capacity && next_item_size > 0 && next_item_size >= 60 {
            score -= 25.0; // big next item: fresh bin useful
        }
    }

    // Fraction-of-capacity penalty for large leftover
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score += 10.0 * frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can never hold the smallest
    // possible item are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Gap too small for the lookahead item: likely dead space, penalize
    // proportionally, but only mildly if the gap still exceeds 10.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Perfect fit reward: strongly favor bins that end completely full.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward placements that leave a gap exactly matching the next item
    // (perfect lookahead fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 * 0.5 {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 6.0 * progress);

    // Prefer bins tighter than the average residual (better consolidation).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // New-bin candidate handling: an empty bin is only attractive when the
    // fit into open bins is poor (large post_residual) or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Late in the stream, new bins are more costly (less time to fill).
        score += 30.0 * progress;
        // If many bins are open, discourage spreading further.
        score += pressure * 3.0;
        // If the item fits the empty bin almost exactly (item near capacity),
        // a fresh bin is actually great.
        if post_residual <= 10 {
            score -= 70.0;
        }
    }

    // Slight nudge: tighter residual fit (smaller post_residual) is better,
    // nonlinear weighting on very tight fits.
    if post_residual <= 20 {
        score -= (20 - post_residual) as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item can't fit here; penalize proportionally to leftover waste
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than the mean.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if lookahead suggests a fresh bin enables a perfect pair, open it.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 400.0;
        }
    }

    // Early in stream, be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small post residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Dead-space penalty: post residual too small for the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste_ratio = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += 60.0 * waste_ratio;
    }
    // Bonus: post residual can still accommodate the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening new bins when decent fits exist
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // But allow new bins when all open residuals are fragmented
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Time-horizon coupling: early in stream, be conservative (keep bins open);
    // late in stream, prioritize tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // Prefer bins whose residual deviates positively from the mean (consolidation)
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: minimize post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // early on, prefer tight fits less aggressively; late, chase tight fits harder
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Reward filling bins deeply: quadratic bonus in item fraction
    score -= 25.0 * norm_item * norm_item;

    // Penalize dead space scaled by mean residual context (smooth cubic)
    let dead = norm_pr.max(0.0);
    score += 10.0 * dead * dead * dead * (mean_residual / cap).max(0.0);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving space that fits the next item (smooth bell)
    if next_item_size > 0 {
        let n = next_item_size as f64 / cap;
        let fit_gap = (pr - next_item_size as f64) / cap;
        let bell = (-8.0 * fit_gap * fit_gap).exp();
        score -= 15.0 * bell * (0.5 + n);
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
        // but allow new bin if post-residual of alternatives would be tiny anyway
        score -= 5.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits; scaled waste
    score += (post_residual as f64 / cap) * 25.0;

    // Harmonic class of post_residual: residuals divisible into common item
    // size bands (e.g. multiples of 10, 25, 50) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // Tiny dead space (unusable for items >= 10 in classic regime) is bad
        if pr < 10 { score += 30.0 + (10 - pr) as f64; }
        // Perfect fit
        if pr == 0 { score -= 40.0; }
    }

    // Lookahead coupling: does post_residual exactly host next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0; // chain fit
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 10.0; // next item won't fit here
        }
        // Harmonic match on next item's class
        if post_residual > 0 && next_item_size % 10 == 0 && post_residual % 10 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the mean residual of existing bins
        score = cap * 0.5 + mean_residual * 0.3;
        // Early in stream, opening bins is fine; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // If many bins can fit, discourage new bin
        score += fitting_bins_count as f64 * 4.0;
        // If the item is large relative to capacity, a fresh bin is natural
        if (item_size as f64) > 0.7 * cap { score -= 20.0; }
        // If next item is large too, fresh bin gives room
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap && (item_size as f64) > 0.5 * cap {
            score -= 12.0;
        }
        // Perfect-fit potential in an existing bin beats a new bin
        if post_residual == 0 { score -= 0.0; } // new bin never gives perfect fit unless item==cap
    } else if post_residual == 0 {
        // perfect fit in existing bin always wins
        score -= 60.0;
    }

    // Mild penalty for spreading across too many open bins when mean residual is high
    if open_bins_count > 3 && mean_residual > 0.5 * cap && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

