pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item fits exactly-ish here
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 250.0;
            }
        } else {
            // dead space relative to lookahead item: penalize small unusable gaps
            let gap = post_residual as f64;
            if gap < nxt {
                score += 0.8 * gap * (gap / nxt);
            }
        }
    }

    // Prefer tighter residual vs mean residual of open bins
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin bonus: avoid opening a new bin when only this one fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 30.0 + 50.0 * (step_index as f64 / total_items.max(1) as f64);
        // but allow new bin if lookahead suggests poor fits everywhere
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Slight preference for filling fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable residuals (< 10, min item size).
    if post_residual < 10 && post_residual > 0 {
        score -= 8.0; // dead space is fine here (bin is "full enough")
    } else if post_residual > 0 {
        score += 3.0 * (post_residual as f64 / bin_capacity as f64).powf(1.5);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - chain / bin_capacity as f64);
        } else {
            score += 4.0; // next item won't fit here, mild penalty
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // a new bin when no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 5.0;
        // Open new bins more eagerly early in the stream (more future to amortize)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * (1.0 - progress);
        // Fewer open bins relative to items processed -> new bin is cheaper
        score -= 2.0 / (open_bins_count as f64 + 1.0);
    } else {
        // Prefer filling existing bins when mean residual is high (fragmentation risk)
        score += 2.0 * (mean_residual / bin_capacity as f64);
        // With many open bins, prioritize consolidation into low-residual bins
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual is close to item size (exactness bonus)
    let slack = (bin_residual - item_size) as f64;
    score -= 5.0 / (1.0 + slack);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mean_r = mean_residual.max(0.0);

    // Base: post residual (larger leftover = better fit preferred)
    let mut score = pr;

    // Smooth non-linear polynomial coupling with stream progress:
    // early on, tolerate larger residuals (bins can still be filled);
    // late, strongly penalize residual waste.
    let progress_weight = t * t * (3.0 - 2.0 * t); // smoothstep in [0,1]
    score += progress_weight * norm_pr * norm_pr * cap * 0.6;

    // Dead-space penalty: residuals too small for typical future items
    let dead = if next_item_size > 0 {
        (next_item_size as f64 - pr).max(0.0)
    } else {
        0.0
    };
    score += dead * (0.5 + 0.5 * progress_weight);

    // Reward nearly-perfect fits with smooth quadratic term
    let perfect = 1.0 - norm_pr;
    score -= perfect * perfect * item_size as f64 * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress_weight);
    }

    // Mild penalty for spreading across too many open bins vs mean residual
    score += (open_bins_count as f64).ln().max(0.0) * (mean_r - pr).abs() * 0.05;

    // New-bin candidate: penalize opening a fresh bin unless residuals are tight
    if bin_residual == bin_capacity {
        let avg_tightness = mean_r / cap;
        score += cap * (0.35 + 0.45 * progress_weight) * (1.0 - avg_tightness).max(0.0);
        if next_item_size > 0 && next_item_size as f64 > mean_r {
            score -= 8.0; // lookahead: new bin useful if next item won't fit mean residual
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" classes (multiples of common size bands) are preferred.
    let pr = post_residual;
    let class = if pr == 0 { 0u32 }
        else if pr <= 10 { 1 }
        else if pr <= 20 { 2 }
        else if pr <= 40 { 3 }
        else if pr <= 60 { 4 }
        else { 5 };
    // Penalize dead space classes non-linearly; zero residual is perfect.
    score += match class {
        0 => -8.0,
        1 => 1.0,
        2 => 2.5,
        3 => 5.0,
        4 => 8.0,
        _ => 12.0,
    };

    // Lookahead: reward bins whose post residual can host the next item exactly
    // or with minimal waste.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;
        } else if next_item_size < pr {
            let w = pr - next_item_size;
            score -= 6.0 * (1.0 - w as f64 / 50.0).max(0.0);
        } else {
            // next item cannot fit here: slight penalty proportional to gap
            score += 0.02 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Modulo / integer-division harmonic coupling on post_residual and next size.
    let n = if next_item_size == 0 { 1u32 } else { next_item_size };
    let harmony = (pr % 10) as f64 + ((pr / 10) % 3) as f64 * 2.0;
    score += 0.3 * harmony;

    // Prefer tighter bins overall: closeness to fullness.
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 4.0 * fill * fill;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * fill;

    // Slight penalty for leaving many open bins when mean residual is high.
    if open_bins_count > 3 && mean_residual > 30.0 && post_residual as f64 > mean_residual {
        score += 2.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let good_fits = if next_item_size > 0 && next_item_size >= item_size { 1 } else { 0 };
        if fitting_bins_count > 0 && (fitting_bins_count > 1 || good_fits == 1 || pr <= 15) {
            score += 25.0;
        } else {
            score += 5.0;
        }
    }

    score
}

