        score -= (pressure * 0.05).min(40.0);
        // Big item that likely won't fit anywhere else anyway.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Open-bins pressure: mildly discourage spreading across many bins.
    score += 0.3 * open_bins_count as f64;

    // Deviation from mean residual: placing into bins far below mean
    // residual (very full bins) is good; near-empty bins are less urgent.
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 200.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 500.0; // perfect 2-chain
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space that next item cannot use
        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // Penalize residual far above mean residual (wasteful bin)
    score += 0.5 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: mildly penalize so we prefer existing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if no good fit exists (post_residual small means tight fit elsewhere is fine)
        if next_item_size > 0 && post_residual >= next_item_size {
            // fresh bin leaves full room for next item too
            score -= 100.0;
        }
    }

    // Late in stream: tighten packing, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space, especially if no future item can use it.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { post_residual as f64 };
        score += 0.35 * dead;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves slack; mild reward scaled by how much remains.
        score -= 8.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.1 * bin_residual as f64;
    }

    // New-bin candidate handling: empty bin gets a base penalty so we prefer
    // reusing open bins, but the penalty shrinks when open bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count > 0 { 1.0 / (1.0 + fitting_bins_count as f64) } else { 1.0 };
        // Early stream: opening bins cheaply builds inventory; late: conserve.
        score += 20.0 * (1.0 - 0.5 * progress) + 10.0 * scarcity;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 60 {
            score -= 6.0;
        }
    }

    // Global state coupling: prefer bins whose residual is near the mean
    // (keeps residual distribution balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for bins with larger residuals when many bins are open
    // (consolidate into emptier bins, keep tight bins for small items).
    if open_bins_count > 4 {
        score -= 0.03 * (bin_residual as f64 - post_residual as f64);
    }

    // Slight time-horizon modulation: as stream progresses, weight tightness more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 + progress) - pr_norm * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * (1.0 + progress * progress);

    // Penalize dead space relative to mean residual
    score += 0.5 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fill is perfect.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Classify post_residual into harmonic classes via integer division thresholds.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.10 {
        score -= 30.0; // tiny dead space, acceptable
    } else if frac < 0.25 {
        score += 10.0; // moderate waste
    } else if frac < 0.50 {
        score += 25.0;
    } else {
        score += 45.0; // large residual, but re-usable
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes are reusable.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 15.0;
    }
    // Odd residuals are harder to fill.
    if pr % 2 == 1 && pr > 0 {
        score += 5.0;
    }

    // Lookahead: does next item fit into post_residual? Reward if yes.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 20.0;
        // Bonus if next item fills bin exactly too.
        if next_item_size == pr {
            score -= 40.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // Next item won't fit here; penalize leaving residual that can't host it.
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: prefer consolidating (avoid spreading).
    if open_bins_count > 4 {
        score -= 3.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin gets neutral baseline plus mild penalty
    // so it only wins when open bins have genuinely bad fits.
    if bin_residual == bin_capacity {
        score = 55.0 + (post_residual as f64 - bin_capacity as f64).abs();
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score += 25.0; // don't abandon the only fitting bin
        }
        if open_bins_count == 0 {
            score -= 60.0; // must open first bin
        }
    }

    // Progress-based mild drift: later in stream, tighten packing (prefer exact fits more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - frac);

    // Mean residual coupling: if mean residual is high, prefer bins below mean (balance).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
