pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100, min size 1)
    // are pure waste; penalize heavily, scaled by how "dead" the gap is.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits: bonus proportional to fill ratio of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // New-bin candidate: baseline cost plus lookahead adjustment. Prefer a fresh bin
    // if the next item is large and this placement would leave a gap the next item
    // cannot use.
    if bin_residual == bin_capacity {
        score = 30.0 + open_bins_count as f64 * 1.5;
        if next_item_size > 0 && post_residual > 0 && next_item_size as f64 > post_residual as f64 {
            score += 10.0;
        }
        // Early in the stream, opening bins is fine; late, be conservative.
        score += 20.0 * (1.0 - progress);
    } else {
        // Penalize placements that leave a gap unusable by the lookahead item.
        if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
            score += 8.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
    }

    // Slight tilt toward bins below mean residual (balancing load across open bins).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
