pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits heavily
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        // Tighter match to next item => lower score
        score -= 120.0 * (1.0 - gap as f64 / bin_capacity as f64);
        // Exact match for the next item is excellent
        if gap == 0 {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit in this bin's remainder: penalize dead space
        score += 40.0;
    }

    // Compare post_residual relative to mean residual: prefer consuming from fuller bins
    if (post_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin unless the item fits poorly in all open bins
    if bin_residual == bin_capacity {
        // New bin candidate: only attractive if post_residual is small relative to item (tight packing start)
        score += 25.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Prefer using existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 520.0;
    }

    // Lookahead: reward bins whose post_residual accommodates the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= 130.0 * (1.0 - gap as f64 / bin_capacity as f64);
        if gap == 0 {
            score -= 220.0;
        } else if gap <= 4 {
            score -= 80.0; // near-exact match bonus for tight chains
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted space
        score += 45.0 + 0.15 * post_residual as f64;
    }

    // Fuller-bin preference relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 35.0;
    } else {
        score += 18.0;
    }

    // Last-chance bin: strongly avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate logic: open only when open bins fit the item poorly
    if bin_residual == bin_capacity {
        // Waste ratio of best alternative approximated by mean_residual vs item
        let poor_fit_everywhere = mean_residual < item_size as f64 * 1.05;
        if poor_fit_everywhere {
            // Starting a fresh bin is fine; keep its post_residual tight
            score += 10.0;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 25.0;
            }
        } else {
            // Some open bin can likely host it: discourage new bin
            score += 60.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 40.0 * (progress - 0.8) * 5.0;
        }
    }

    // Slight preference for reusing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0;

    // Prefer bins whose remaining space after placement stays small but usable
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // sliver remainder is nearly a perfect fit
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fit is heavily favored.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fit_ratio * fit_ratio;
    }

    // Penalize creating small dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: penalize if the next item cannot fit the post-residual
    // (this bin would be closed anyway); reward if it chains nicely.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 6.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins mildly; less penalty late in the stream
        // and for large items that would leave awkward residuals elsewhere.
        score += 35.0 - 20.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // If mean residual across open bins is large, prefer reusing bins.
        score += 0.15 * mean_residual;
    }

    // Mild preference for filling bins with larger residuals when many bins are open.
    score += 0.02 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fill: strongest reward
    if post_residual == 0 {
        score -= 120.0;
    }

    // Core lookahead: reward bins whose post-residual hosts next item, scaled by tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 45.0 * (1.0 - slack / cap);
        if slack == 0.0 {
            score -= 60.0;
        } else if slack <= 4.0 {
            score -= 18.0 + 2.0 * (4.0 - slack);
        } else if slack <= 12.0 {
            score -= 4.0 + 0.8 * (12.0 - slack);
        }
        // two-step lookahead: remaining room still usable by mean-sized demand
        if slack > 0.0 && (slack as f64 - mean_residual).abs() < 4.0 && open_bins_count > 2 {
            score -= 3.0;
        }
        if slack as f64 >= next_item_size as f64 * 0.6 && slack as f64 <= mean_residual * 2.5 {
            score -= 1.5;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item does not fit: dead-space penalty, stronger when residual is tiny relative to next
        let dead = (next_item_size - post_residual) as f64;
        score += 2.0 + 3.0 * dead / cap * cap.sqrt();
        if dead <= 4.0 && fitting_bins_count > 2 {
            score += 1.5 + 0.3 * (4.0 - dead);
        }
        if (post_residual as f64) < mean_residual * 0.5 && open_bins_count > 5 {
            score += 1.0;
        }
        // late-stream dead space is costly
        if step_index > total_items / 2 && dead <= 10 {
            score += 0.6 + 0.12 * (10.0 - dead);
        }
    }

    // Fuller-bin preference relative to mean residual
    if post_residual > 0 {
        if (post_residual as f64) < mean_residual * 0.85 {
            score -= 6.0;
        } else if (post_residual as f64) > mean_residual * 1.4 {
            score += 2.5;
        }
    }

    // Sliver remainder is nearly a perfect fit
    if post_residual > 0 && post_residual <= 2 && fitting_bins_count > 2 {
        score -= 6.0;
    } else if post_residual > 0 && post_residual < 10 {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = mean_residual < item_size as f64 * 1.05;
        if poor_fit_everywhere {
            score += 4.0;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 8.0;
            }
        } else {
            score += 20.0;
        }
        // Late in stream: consolidate, avoid new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 15.0 * (progress - 0.8) * 5.0;
        }
        // mean residual already covers next item: no need for a fresh bin
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && open_bins_count > 2 && fitting_bins_count > 1 {
            score += 5.0;
        }
        // crowded field with small mean residual: fresh bin wasteful
        if open_bins_count > 4 && mean_residual < cap * 0.22 {
            score += 3.0;
        }
        // early stream with room to spare: fresh bin acceptable
        if total_items > 0 && step_index < total_items / 5 && fitting_bins_count > 1 && open_bins_count > 2 {
            score -= 2.0;
        }
    }

    // Slight preference for reusing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Rare-fit deepening: exact next-item match with few alternatives
    if next_item_size > 0 && post_residual == next_item_size && fitting_bins_count <= 3 {
        score -= 8.0;
    }

    // Tight fine-grained fit when alternatives are few
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 4 {
        let slack = post_residual - next_item_size;
        if slack > 0 && slack <= 3 {
            score -= 3.0 + 0.8 * (3 - slack) as f64;
        }
    }

    // Waste from item barely fitting
    if post_residual > 0 && post_residual < item_size {
        score += 1.5 * (item_size - post_residual) as f64 / cap;
    }

    // Many open bins: penalize leaving large unusable residuals
    if post_residual > 0 && open_bins_count > 10 {
        let dead_frac = 1.0 - post_residual as f64 / cap;
        if dead_frac > 0.85 {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalized smoothly by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

