            score += 10.0;
            // extra penalty if residual is small and unusable
            if post_residual < 10 {
                score += 15.0;
            }
        }
        // perfect chain: post_residual exactly equals next item
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

