pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: minimize residual with a convex penalty.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        score += (pr * pr) / 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual matches next item well.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= ni {
            let gap = pr - ni;
            // Strong reward when next item exactly fills leftover space.
            if gap == 0.0 {
                score -= 800.0;
            } else {
                score -= 300.0 - (gap * gap) / 100.0;
            }
        } else {
            // Next item cannot fit in the leftover: penalize wasted pair potential,
            // scaled by how close it came (a near miss is worse than a big miss).
            let miss = ni - pr;
            score += 50.0 + (100.0 - miss.min(100.0)) * 0.5;
        }
    }

    // Compare residual to mean residual: prefer bins tighter than average.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 250.0 + 200.0 * progress;
        // Discourage new bins when good fits exist elsewhere.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score += 500.0;
        }
        score += base;
        // Opening a bin is cheaper when many bins are already open relative to items.
        score -= (open_bins_count as f64).max(1.0).ln() * 30.0;
    }

    // Mild preference for fuller bins overall.
    score -= (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
