    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
    score += 0.02 * pressure;

    // Time horizon: early in the stream, be pickier about tight fits; late, prefer filling.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - t) * 5.0 * fit_ratio + t * 8.0 / (1.0 + post_residual as f64);

    // Discourage opening new bins when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count > 0 && fit_ratio > 0.5 {
            score += 15.0;
        }
