pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);

    // Base: wasted space, mildly non-linear (dead space grows superlinearly in badness).
    let mut score = post + 0.35 * (post * post) / cap;

    // Reward tight fits: quadratic bonus peaking at post_residual == 0.
    let tightness = 1.0 - post / cap;
    score -= 18.0 * tightness * tightness;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, tolerate medium residuals; late, demand tight packing.
    let phase = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let residual_norm = post / cap;
    score += (1.0 - phase) * 8.0 * residual_norm * (1.0 - residual_norm) * 4.0;
    score += phase * 14.0 * residual_norm;

    // Lookahead: reward if next item fits exactly in post_residual; penalize near-miss dead zones.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            let overflow = (nxt - post) / cap;
            score += 6.0 * overflow * overflow;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer only when item barely fits any open bin,
    // or when open-bin residuals are small (fragmented state).
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        let desperation = (mean_gap * mean_gap) * 30.0 + (fitting_bins_count as f64).recip() * 10.0;
        let base_cost = 25.0 + 10.0 * (1.0 - progress);
        score += base_cost - desperation;
        // early stream: opening bins is cheap and often good
        score -= 12.0 * (1.0 - phase);
    }

    // Mild penalty proportional to crowding of open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals divisible into small chunks (mod small divisors) are valuable.
    let pr = post_residual;
    let harmonic_bonus = match pr {
        0 => 12.0,                              // perfect fit is king
        r if r % 10 == 0 => 6.0,                // aligns with standard size classes
        r if r % 5 == 0 => 4.0,
        r if r < 10 => 2.0,                     // small dead space anyway
        r if r % 3 == 0 => 2.5,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Penalize awkward mid-range residuals via integer-division thresholds.
    let dead_zone = ((pr / 10) % 2 == 1) && pr > 15 && pr < 60;
    if dead_zone {
        score += 4.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or within a harmonic class.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 10.0;                      // guaranteed perfect follow-up
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 4.0 - (gap as f64).min(4.0) * 0.5;
            if gap % 10 == 0 {
                score -= 1.5;                   // class-aligned follow-up
            }
        } else {
            // next item cannot fit here: residual becomes dead space
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when open bins are nearly full
    // or mean residual is tiny.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).min(1.0);
        score = 25.0 + 40.0 * pressure;
        if fitting_bins_count == 1 {
            score += 10.0; // don't abandon the sole fitting bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 3.0; // a fresh bin pairs well with a big next item
        }
    }

    // Slight preference for tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (cap - bin_residual as f64) / cap * (2.0 + 3.0 * progress);

    // Tie-break: prefer bins whose residual is close to the item (snug fit).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
