            // leaving a gap smaller than the next item is bad
            score += 15.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading; prefer new bin less.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it's chosen only when fits are poor.
        score += 55.0;
        score -= 10.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 5.0)));
        if fitting_bins_count == 0 { score -= 100.0; }
    } else {
        score += 2.0 * open_bins_count as f64;
        // Prefer bins with lower current residual (fill fuller bins first).
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Late-stream consolidation: prefer existing bins more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity { score -= 10.0 * progress; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
