    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // small unusable-ish gap is fine, bin nearly full
    }
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.15; // wasteful leftover
    }

    // Compare against mean residual across open bins: prefer bins with less residual.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild preference to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    // New-bin candidate: only attractive when it beats poor fits.
    if bin_residual == bin_capacity {
        score += 12.0; // default penalty; tight fits / last-chance placements overcome it
    }

    score
