pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted post-residual relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac * (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Small residuals are dead space; penalize leaving tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a new bin when existing fits are poor,
    // but discourage it when many bins are already open or residuals are high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_res_frac = mean_residual / bin_capacity as f64;
        // Open new bin if mean residual is small (existing bins are full-ish)
        score -= 18.0 * (1.0 - mean_res_frac);
        // Late in the stream, avoid proliferating bins
        score += 10.0 * progress;
        // More open bins -> slight penalty for opening yet another
        score += 1.5 * (open_bins_count as f64).sqrt();
    }

    // Global state: if mean residual across open bins is large, prefer bins
    // that reduce variance (i.e., deviate from the mean).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.5 * dev;

    // Mild time-decay on everything: early items get more aggressive packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
