    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across too many bins early
    score += 0.6 * open_bins_count as f64 * (1.0 - progress);

    // Discard near-empty residual waste late in the stream
    score += 0.15 * pr * p2;

    score
}

