pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common small sizes
    // (10, 20, 25, 50) are "harmonic" and likely reusable.
    let mut harmonic_bonus = 0.0;
    for &d in &[10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            harmonic_bonus += 6.0;
        }
    }
    score -= harmonic_bonus;

    // Dead-space penalty: tiny, non-harmonic residuals are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit is best.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // harmonic class match between next item and post residual
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 12.0;
            }
            score += slack as f64 * 0.15;
        } else {
            // next item won't fit here: penalize more when slack is large
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and many bins are open (consolidation phase).
    if bin_residual == bin_capacity {
        score += 15.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 3 {
            score -= (open_bins_count.min(20) as f64) * 1.5 * (1.0 - progress);
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Prefer tighter bins: tie-break toward low bin_residual relative to mean.
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Slight preference for bins whose residual class matches item size class.
    if bin_residual / 10 == item_size / 10 {
        score -= 3.0;
    }

    score
}

