    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 2.0 * (10 - post_residual) as f64;
    }
    // "Awkward zone": residual just above the minimum item size is hard to
    // fill later; mildly penalize.
    if post_residual >= 10 && post_residual <= 20 {
        score += 0.5 * (post_residual as f64 - 10.0);
    }

    // Reward perfect / near-perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 5 {
        score -= 6.0;
    }
    // Penalize if the leftover gap cannot fit the next item (dead space risk).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Tight fit reward: fraction of the bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_frac;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more expensive.
    let open_pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64 * 10.0);
    score += 0.3 * open_pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the current bin would leave a
