pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 8.0;

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 6.0 + (gap as f64).min(20.0) * 0.4;
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for wasting space next item could use elsewhere
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score -= pressure * 3.0;

    // Deviation from mean residual: prefer bins that are already low (fill fuller bins first).
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Time horizon: early in stream, allow more slack (favor new bins less); late, consolidate hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // New-bin candidate: penalize unless current bin residual is too small for typical items.
    if bin_residual == bin_capacity {
        // Opening new bin is costly; only attractive when item barely fits nowhere else
        // and the stream is young.
        let waste_here = (bin_residual - item_size) as f64;
        score += 10.0 - progress * 8.0 + waste_here * 0.05;
        if fitting_bins_count > 1 {
            score += 20.0; // other bins exist, don't open a new one
        }
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: post residual, weighted by a smooth non-linear function of progress.
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear penalty for mid-range dead space (quartic coupling with progress).
    let dead = norm_pr * (1.0 - norm_pr);
    score += 40.0 * (dead * dead) * (1.0 - progress);

    // Reward tight fits: strongly subtract when post_residual is small.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward if next item fits into post_residual (smooth gate).
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as f64;
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 15.0 * fits_next * (1.0 - gap / cap);
        score += 8.0 * (1.0 - fits_next) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Penalize new bin more as stream progresses (consolidate late).
    if is_new_bin {
        score += 20.0 + 30.0 * progress * progress;
    } else {
        // Slight preference for bins below mean residual (balance load, smooth).
        score += 5.0 * ((pr - mean_residual) / cap);
    }

    // Mild coupling with open bin count: prefer reusing bins when many are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the
    // leftover space fall into? Leftovers near multiples of common item sizes
    // (especially small ones 10..25) are reusable; odd leftovers are dead space.
    let pr = post_residual;
    let small_band = (pr % 25) as f64;         // residue mod 25 (common item quantum)
    let mid_band = (pr % 50) as f64;           // residue mod 50
    let dead = if pr == 0 { 0.0 } else if pr < 10 { 12.0 } else if pr < 20 { 4.0 } else { 0.0 };
    score += dead;

    // Reward post_residuals that are exactly reusable by typical next items
    if next_item_size > 0 && pr >= next_item_size {
        score -= 6.0;
        // Perfect class match: leftover exactly equals next item or a small multiple
        if pr == next_item_size { score -= 8.0; }
        if next_item_size <= 25 && pr % next_item_size == 0 { score -= 4.0; }
    } else if next_item_size > 0 && pr > 0 {
        // leftover cannot host next item -> penalize proportionally
        score += (next_item_size as f64 - pr as f64).min(20.0) * 0.5;
    }

    // Penalize awkward harmonic classes: post_residual in (0..10) is dead space
    // regardless; residue mod 25 near 0 means it aligns with item grid -> good.
    if pr > 0 {
        let align = (small_band / 25.0).abs();
        score += align * 6.0;          // far from grid alignment -> worse
        score -= (1.0 - align) * 2.0;  // near grid alignment -> slight reward
        if mid_band < 5.0 { score -= 3.0; }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current bin would leave a tiny unusable remainder and the item is large.
    if bin_residual == bin_capacity {
        // empty bin baseline: neutral-ish, slightly worse than a decent fit
        score = cap * 0.5 + item_size as f64 * 0.3;
        if next_item_size > 0 && next_item_size >= item_size { score -= 5.0; }
        if fitting_bins_count == 0 { score -= 30.0; } // must open anyway
    } else if pr < 10 && pr > 0 {
        // creating tiny dead space in an existing bin: discourage unless last chance
        if fitting_bins_count > 1 { score += 10.0; }
    }

    // Late in the stream, consolidate: prefer filling existing bins tighter
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (mean_residual - post_residual as f64).abs() * 0.15;

    // Prefer bins whose residual is already below the mean (tighter bins first)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

