    // Lookahead coupling: penalize residuals that cannot host the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            score -= 40.0; // sets up a perfect next placement
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer denser packing when many bins are open.
    score += 0.15 * open_bins_count as f64;

    // Mild alignment with mean residual: bins below mean residual are tighter fits.
    score += 0.1 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when current bin would leave large waste
    // and the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let waste_now = bin_residual - item_size;
        score = (post_residual as f64) + 0.5 * waste_now as f64
            - 0.2 * (item_size as f64)
            + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
