pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1), used as a dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: fraction of the bin consumed by this placement.
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward near-perfect fills strongly (waste minimization is the core signal).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize leftover space super-linearly, scaled by how early we are
        // (dead space early in the stream is more costly).
        let waste_penalty = (post_residual as f64).powf(1.35) * (0.6 + 0.8 * (1.0 - progress));
        score += waste_penalty;
    }

    // Reward tight fits (item fills most of the residual).
    score -= 60.0 * fit_ratio * fit_ratio;

    // Lookahead coupling (k=2): if the next item fits exactly into the post
    // residual, this is a great placement; if next item cannot fit anywhere
    // after this placement, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 15.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre alternative.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 180.0;
    }

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; prefer filling existing fragmented bins rather than
    // opening more bins.
    let fragmentation = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if bin_residual != bin_capacity {
        score -= 25.0 * fragmentation;
    }

    // New-bin candidate handling: only attractive when the current item is
    // large relative to capacity (a fresh bin can host it plus follow-ups),
    // or when there are no fitting alternatives.
    if bin_residual == bin_capacity {
        let size_pressure = item_size as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let late_bonus = 0.5 * progress;
        // Base cost of a new bin, discounted when scarcity/size/lateness justify it.
        score += 220.0 - 150.0 * size_pressure - 300.0 * scarcity - 80.0 * late_bonus;
        // Prefer opening a new bin when existing bins are on average quite full
        // (mean residual small) — less room for future items there.
        score += 100.0 * (mean_residual / bin_capacity as f64);
    }

    // Mild penalty for very small post-residuals that are unlikely to fit
    // typical future items (dead space below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    score
}

