pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item / cap;

    // Base: waste after placement, softly normalized
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, residual waste is cheaper (bins get reused); late, waste is costly.
    let waste_weight = 1.0 + 2.0 * progress * progress;
    score += waste_weight * norm_post * cap * 0.5;

    // Cubic penalty on very small residuals (dead space) — smooth via (1-norm_post)^3
    let dead = (1.0 - norm_post).powi(3);
    score += 30.0 * dead * (0.5 + progress);

    // Reward tight fits: post_residual near zero gets a strong smooth bonus
    let tight = (-norm_post * 6.0).exp() - 1.0;
    score -= 20.0 * tight * (1.0 - progress);

    // Lookahead coupling: if next item fits into post_residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            // next item cannot follow here: mild penalty scaled by overshoot
            let over = (nxt - post) / cap;
            score += 8.0 * over * over;
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this bin is underused relative to mean
    let mean_gap = (mean_residual - post) / cap;
    score += 5.0 * mean_gap * mean_gap * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate handling: empty bin has high intrinsic cost, decreasing with progress
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - 0.5 * progress) + 10.0 * norm_item;
    }

    // Smooth fill-ratio reward: prefer bins that become fuller
    let fill = 1.0 - norm_post;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: divide capacity into 10 classes.
    let class = (post_residual * 10) / bin_capacity.max(1);
    let class_bonus: f64 = match class {
        0 => -12.0,                 // near-perfect fill
        1 => -8.0,
        2 => -4.0,
        3 => -1.0,
        4 => 1.0,
        5 => 2.0,
        6 => 3.0,
        7 => 4.5,
        8 => 6.0,
        _ => 8.0,                   // large residual left = wasteful
    };
    score += class_bonus;

    // Reward exact/near-exact fits via modulo arithmetic.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 2 {
        score -= 15.0;
    }

    // Lookahead: does next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= bin_capacity {
        if next_item_size <= post_residual {
            // Bonus scaled by how well the next item consumes the residual.
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 6.0 * next_fit;
            // Harmonic bonus: next item leaves again a small class.
            let next_post = post_residual - next_item_size;
            let nclass = (next_post * 10) / bin_capacity.max(1);
            if nclass <= 1 {
                score -= 5.0;
            } else if nclass <= 3 {
                score -= 2.0;
            }
        } else {
            // Next item won't fit here; penalize small residuals that strand space.
            if post_residual < 10 {
                score += 4.0;
            }
        }
    } else if next_item_size == 0 {
        // Last item: strongly prefer tightest fill.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless item is large
    // and existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 - 0.25 * item_size as f64 - 3.0 * open_bins_count as f64 * (1.0 - progress);
        if item_size >= 60 {
            score -= 6.0; // large items start fresh bins happily
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 4.0; // existing bins nearly full anyway
        }
    }

    // Mild tie-breaking toward bins with residual close to item size (best-fit core).
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    // Progress-aware micro-adjustment: later in stream, be greedier about fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste -> heavy penalty.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0;
