    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize moderately small leftovers that only fit tiny items.
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage spreading across bins.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item cannot fit anywhere after this placement, penalize.
    if next_item_size > 0 && next_item_size > post_residual && fitting_bins_count <= 1 {
        score += 15.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to the
    // mean (keeps bin loads balanced and predictable).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Slight preference for tighter fits overall.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Early stream: be more conservative about opening new bins (favor reuse).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure that grows with open bins.
        score += 12.0 + 2.0 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    }

    score
}

