    // but discourage wasting a very full bin's remaining space on a tiny item.
    if item_size < 20 && bin_residual >= 70 {
        score += 6.0;
    }

    // Tie-break: prefer filling bins with lower mean residual spread (denser bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

