        // If many open bins, slightly discourage proliferation.
        open_cost += 1.5 * open_bins_count as f64;
        // If item is large, placing in fresh bin is natural.
        if item_size >= bin_capacity / 2 {
            open_cost -= 15.0;
        }
        score += open_cost;
    } else {
        // Reward using existing bins more when many are open.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
