    // Tight-fit reward: item fills a large fraction of the bin
    let fill = item_size as f64 / cap_f;
    score -= 30.0 * fill * fill;

    // Lookahead coupling: can the next item land in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
