        if fill > 0.6 && mean_residual < 30.0 {
            score -= 20.0;
        }
    } else {
        // prefer bins whose residual is below mean (compact bins first)
        let dev = (bin_residual as f64 - mean_residual) / cap_f;
        score += 12.0 * dev;
    }

    // mild preference for fewer open bins when fit is clean
    if post_residual <= 5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
