pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: waste after placement, mildly damped as stream progresses
    let mut score = pr * (1.0 - 0.25 * progress);

    // Non-linear polynomial coupling of post-residual with progress:
    // early stream: prefer tight fits (low post_residual); late stream: tolerate larger residuals
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    score += 20.0 * poly * (1.0 - progress);

    // Penalize residuals that are small but nonzero (dead space)
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (1.0 - pr / 10.0);
    }

    // Reward perfect fits
    if pr == 0 {
        score -= 15.0;
    }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (ni / cap);
            // extra reward if next item fills residual nicely
            let fill = 1.0 - ((pr - ni) / cap);
            score -= 4.0 * fill * fill;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate: bias toward opening a fresh bin when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / cap);
        score = 10.0 + 0.5 * mean_residual - 2.0 * crowded + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small post_residual => tight fit
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits: exact and near-exact placements
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Modulo classes on post_residual: residuals in [1..10] are "dead" if no small item follows
    // Harmonic bucket: post_residual / 10 (integer division thresholds)
    let bucket = post_residual / 10;
    score += bucket as f64 * 2.0;

    // Penalize residuals that no plausible item (1..100) can use well:
    // residual r is "usable" if some item size <= r exists; tiny residuals are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the fit here is terrible
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap - item_size as f64; // post_residual of fresh bin
        score += 12.0; // inherent opening cost
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // If current best open-bin fit would leave large dead space, new bin is fine
        if post_residual as f64 > 0.0 && (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Fraction-of-capacity harmonics: reward using large fractions of the bin
    let fill_fraction = (bin_capacity - post_residual) as f64 / cap;
    score -= 10.0 * fill_fraction * fill_fraction;

    // Slight pressure to consolidate when many bins are open
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64).ln() * 0.5;
    }

    // Progress-based mild adaptation: later in stream, prefer tighter fits more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - fill_fraction);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits into the post residual,
    // this placement is valuable (chains two items into one bin).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // residual can't host next item -> mild penalty scaled by gap
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into a new bin; consolidate instead.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // the item fits badly everywhere (large item, high residual waste).
        score += 30.0 + 10.0 * open_pressure;
        if item_size >= 70 {
            score -= 20.0; // big items justify fresh bins more readily
        }
    } else {
        // Using an existing bin slightly relieves open-bin pressure.
        score -= 2.0 * open_pressure;
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps bin profiles homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early in the stream, be slightly more willing to open bins to build
    // a diverse residual portfolio; late, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    } else {
        score -= 6.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on wasted space (quadratic dead-space pressure).
    score += 0.05 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // chain match: perfect follow-up placement
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder; penalize large leftovers
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap.min(60.0);
        }
        // Bonus if next item also fits tightly relative to mean residual
        if next_item_size > 0 && (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with less residual than average
    // (concentrate waste in few bins), unless it creates a last-chance fit.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.15 * rel;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad,
    // but allow opening early when many bins are open and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit_pressure = if next_item_size > 0 {
            (next_item_size as f64 - post_residual as f64).abs()
        } else { 0.0 };
        let mut new_bin_score = 20.0 + 0.5 * item_size as f64 * progress;
        if fitting_bins_count <= 2 && bad_fit_pressure > 30.0 {
            new_bin_score -= 25.0; // opening is attractive when existing fits are poor
        }
        score = score.max(new_bin_score);
        score = new_bin_score;
    }

    // Slight tie-break noise-free deterministic jitter based on step.
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Reward near-full fills (small post_residual gets a bonus).
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits in post_residual, this is a great pair placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.15 * next_item_size as f64;
    }
    // If next item would NOT fit and post_residual is awkwardly small, mild penalty (dead space).
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many fitting bins: prefer the one with the smallest residual (best fit) — handled by base,
    // but add slight penalty for spreading across too many open bins.
    if open_bins_count > 4 {
        score += 0.4 * open_bins_count as f64;
    }

    // Global state: if mean residual is high, tolerate looser fits to consolidate.
    if mean_residual > 30.0 {
        score -= 0.1 * mean_residual;
    }

    // Time horizon: early in stream, be conservative (avoid fragmenting bins);
    // late in stream, be aggressive about filling bins completely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 10.0;

    // New-bin candidate: opening a new bin should only win when it's genuinely better
    // than a poor fit into an existing bin. Penalize the empty-bin call moderately.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * mean_residual;
        // But if no existing bin fits well (this call is for the new bin and
        // fitting bins are scarce), allow it.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Non-linear base: convex in post_residual (prefer tight fits strongly).
    let mut score = post.powf(1.35) / cap.powf(0.35);

    // Smooth interaction of post_residual with stream progress:
    // late in the stream, tighten packing further (amplify small residuals).
    let progress_coupling = 1.0 + 0.8 * progress * (post / cap);
    score *= progress_coupling;

    // Penalize residuals that are awkwardly large but below next-item size
    // (dead space): smooth sigmoid-like coupling instead of piecewise rules.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (post - nx).max(0.0);
        let usable = if post > 0.0 { (nx / post).min(1.0) } else { 0.0 };
        score += 6.0 * waste / cap * (1.0 - usable);
        // Reward bins whose post_residual still fits the lookahead item.
        score -= 4.0 * usable * usable;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 6.0 * progress;
    }

    // Mild penalty when many bins are open and this one is far from mean residual
    // (encourage balanced closure of bins near the mean).
    let dev = (post - mean_residual).abs() / cap;
    score += 2.0 * dev * (1.0 - progress);

    // New-bin candidate (empty bin): penalize proportionally to how well the
    // item would fit in existing bins, so new bins only win on poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if nx <= post {
                score += 4.0; // empty bin could also serve the next item, but opening is costly
            }
        }
    }

    score
}

