    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.25 * (post_residual as f64);

    // Global residual balance: prefer bins whose residual is below mean (fill emptier-relative bins),
    // keeping high-residual bins flexible for large future items.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in stream, opening new bins is cheap since bins don't need re-filling.
        score -= 12.0 * progress;
        // If next item is large and this item is small, a fresh bin preserves order.
        if next_item_size > item_size && (next_item_size as f64) > 0.6 * (bin_capacity as f64) {
            score -= 8.0;
        }
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Mild penalty per open bin: discourage bin proliferation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer moderate post_residual; late: strongly prefer tight fits.
    let w = 1.0 + 2.0 * progress * progress;
    score += w * (post / cap) * (post / cap) * cap * 0.5;

    // Reward tight fits (small post_residual) with a cubic discount.
    let tight = 1.0 - post / cap;
    score -= 30.0 * tight * tight * tight;

    // Lookahead: penalize if next item could have filled this post_residual exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() < 1.0 {
            score -= 25.0; // perfect pairing
        } else if nxt <= post {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 5.0 * (1.0 - post / cap); // next item can't use leftover
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New empty bin candidate: make it attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = post / cap; // post == cap - item_size
        score = 20.0 + 40.0 * bad_fit * bad_fit - 10.0 * progress;
        if fitting_bins_count == 1 {
            score += 60.0; // never open when a last-chance bin exists
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64 * (mean_residual - post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 residue classes
    let pr = post_residual;
    let class = pr % 10;
    // Residues that pair well with typical small items get a bonus (lower score)
    let harmonic_bonus: f64 = match class {
        0 => 8.0,                 // exact fill / round residual is reusable
        5 => 4.0,                 // half-decade residual still useful
        2 | 8 => 1.5,
        1 | 9 => 0.0,
        _ => 3.0,                 // odd mid residues: mediocre
    };
    score -= harmonic_bonus;

    // Integer-division thresholds: residual in "quarters" of capacity
    let quarter = bin_capacity / 4;
    if pr < quarter / 2 {
        // tiny leftover = near-perfect packing, strongly reward
        score -= 6.0;
    } else if pr > quarter * 3 {
        // large leftover wasted on a nearly-full bin: penalize lightly
        score += 2.0;
    }

    // Lookahead: does next item fit into post_residual? (k=2 lookahead)
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0; // chain placement possible
            // exact chain match is ideal
            if pr == next_item_size {
                score -= 8.0;
            } else {
                let chain_left = pr - next_item_size;
                // harmonic check on the double-placement leftover
                if chain_left % 10 == 0 {
                    score -= 4.0;
                }
                if chain_left < 5 {
                    score -= 5.0; // near-perfect double fill
                }
            }
        } else {
            // next item won't fit here: this bin becomes dead after this placement
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we
    // prefer good fits into open bins, but accept it when fits are bad.
    if bin_residual == bin_capacity {
        score = cap * 0.65 + (item_size as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item: fresh bin useful
        }
        return score;
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 6.0;

    // Waste penalty scaled by how unusable the leftover is relative to mean residual
    if (pr as f64) < mean_residual * 0.3 {
        score += 3.0; // creates a straggler bin
    }

    // Late-stream consolidation: prefer denser packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (pr as f64 / cap) * 3.0;

    // Many open bins: discourage spreading, reward filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful are heavily penalized.
    // Estimate the minimum plausible future item size from observed stream statistics.
    let min_useful = (item_size.min(next_item_size.max(1))).max(1) as f64;
    if (post_residual as f64) < min_useful {
        // Unusable gap: quadratic penalty scaled by how close to zero the gap is.
        let gap = post_residual as f64;
        score += 60.0 + (min_useful - gap) * (min_useful - gap) * 0.5;
    } else {
        // Usable residual: reward tight fits (small post_residual relative to capacity).
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if the next item can still fit into the post_residual gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly-ish: reward chaining.
            let chain_tight = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain_tight / bin_capacity as f64);
        } else {
            // Next item will not fit here: penalize leaving a gap that wastes this bin's tail.
            score += 8.0;
            // Extra penalty if the leftover is small-but-unusable for the next item.
            if (post_residual as f64) < next_item_size as f64 * 0.5 {
                score += 10.0;
            }
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        // Still keep dead-space penalty dominant for awful fits.
        if (post_residual as f64) < min_useful {
            score += 20.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when open-bin
    // pressure is low or all fits would be poor.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 20.0;
        // When many bins are open, prefer consolidating into them.
        score += open_bins_count as f64 * 3.0;
        // Late in the stream, closing out existing bins matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If mean residual across open bins is large, avoid opening new bins.
        score += mean_residual * 0.3;
        // But if this is a large item and fitting bins are scarce, allow new bin:
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 45.0;
        }
    } else {
        // Using an existing bin: mild reward that grows with open bin count.
        score -= open_bins_count as f64 * 1.5;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post residual == next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Leftover after placing next item too: partially good, decays with gap.
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 - gap * 0.35;
        } else {
            // Dead space: next item cannot fit into the residual — penalize.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    }

    // Penalize residuals far below mean (fragmented bin), reward near-mean consolidation.
    score += (post_residual as f64 - mean_residual).abs() * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, prefer tightening packing (small residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // Mild penalty when many bins are already open (discourage opening more).
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate: only attractive if this bin would be a poor fit anyway.
    if bin_residual == bin_capacity {
        score -= 8.0;
        if post_residual > 0 && next_item_size > post_residual {
            score += 15.0; // opening fresh bin creates dead space relative to next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: reward small post_residual non-linearly.
    let tightness = post_residual as f64 / cap;
    score -= 25.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize leaving dead space that likely can't be used by the next item.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Next item fits here: reward slightly for chaining.
            score -= 0.35 * next_item_size as f64;
        }
    }

    // Last-resort bin: strong bonus so we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Many fitting bins: mild penalty to keep selection discriminating.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer fuller bins relative to the fleet average.
    let fullness = (bin_capacity - bin_residual) as f64 / cap;
    score -= 4.0 * fullness;
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // New-bin candidate logic: opening a bin is acceptable early or when the
    // item would leave a very awkward residual in an existing bin.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Empty bin: baseline is its full residual; make it unattractive unless
        // existing placements would be terrible (high post_residual everywhere).
        let awkward = if post_residual > 0 { 0.0 } else { 0.0 };
        score += 10.0 * progress - awkward;
        // Late in the stream, opening new bins is expensive; discourage more.
        score += 12.0 * progress * progress;
    } else if post_residual < 10 && post_residual > 0 {
        // Creating tiny unusable slivers is bad.
        score += 8.0;
    }

    // Mild noise-free coupling with open bin count: avoid bin proliferation.
    score += 0.4 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared normalized post-residual penalty reduction
    let tight = (post_residual as f64 / cap).powi(2);
    score -= 12.0 * (1.0 - tight);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: prefer residuals that can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 3.0 * (1.0 - post_residual as f64 / cap);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins as stream progresses (smooth non-linear ramp)
    let new_bin_penalty = 20.0 * (0.3 + 0.7 * progress) * (1.0 + (open_bins_count as f64 / 50.0).powi(2));
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // New bin acceptable only if no tight fit exists among open bins
        if post_residual as f64 / cap < 0.2 {
            score += 5.0;
        }
    }

    // Smooth coupling of bin residual deficit with stream progress
    score += progress * (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on "nice"
    // capacity fractions (multiples of 25, 20, 10) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, zero waste
    } else if pr % 25 == 0 {
        score -= 18.0;
    } else if pr % 20 == 0 {
        score -= 14.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else if pr < 10 {
        // dead space below minimum item size — unusable
        score += 12.0 * (10 - pr) as f64;
    }

    // Lookahead coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: mild penalty scaled by how much we "wasted" the slot
            score += 6.0;
        }
    }

    // Integer-division thresholds: bins whose residual is in a coarse class
    // matching the item's size class get a preference.
    let item_class = item_size / 20; // 0..4
    let bin_class = bin_residual / 20;
    if bin_class == item_class + 1 {
        score -= 5.0; // tight-ish fit keeps large residuals for large items
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless this is a big item
    // and existing residuals are small (poor fits everywhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64 + 5.0;
        let base = 30.0 + 20.0 * progress;
        if tight && item_size > 50 {
            score -= 35.0; // opening a new bin is justified
        } else {
            score += base;
        }
    }

    // Prefer filling bins with large residual gaps to consolidate.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference for bins that keep mean residual near an even split
    // of capacity (harmonic target residual).
    let target = bin_capacity as f64 / 2.0;
    score += 0.02 * (post_residual as f64 - target).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
