pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already encoded).
    // Normalize dead space relative to capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let tightness = 1.0 - (post / cap); // 1.0 = perfect fill
    score -= 20.0 * tightness;

    // --- 2-step lookahead: does the next item fit into the post-residual? ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // Excellent: next item chains into this bin's leftover space.
        let chain_waste = post - next_item_size as f64;
        // Reward chained fit, stronger when the chain leaves almost nothing.
        score -= 15.0 * (1.0 - chain_waste / cap);
        score -= 10.0; // flat bonus for keeping the stream in one bin
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to how much
        // dead space we strand relative to the next item's size.
        let stranded = post / (next_item_size as f64);
        score += 8.0 * stranded.min(2.0);
    }

    // --- Relative to mean residual across open bins ---
    // Bins with residual far below mean are "precious" near-full bins:
    // filling them further is good; leaving them with odd scraps is bad.
    if mean_residual > 0.0 {
        let rel = post / mean_residual;
        if rel < 1.0 {
            // Post-residual below average: this bin was already tight; reward.
            score -= 6.0 * (1.0 - rel);
        } else {
            // Post-residual above average: we keep an unusually empty bin.
            score += 4.0 * (rel - 1.0).min(2.0);
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits; strongly avoid opening a new bin
        // unless the fit is truly terrible.
        if post_residual <= bin_capacity / 4 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: only attractive if current item is large
        // relative to capacity (poor fit elsewhere) or no open bin fits well.
        let big_item = (item_size as f64 / cap) > 0.6;
        let poor_field = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_capacity - item_size) as f64 > mean_residual);
        if big_item || poor_field {
            score -= 12.0;
        } else {
            // Prefer reusing open bins when fits are decent.
            score += 15.0;
        }
    }

    // --- Stream progression: early on, be conservative with bin count;
    // late in the stream, close out bins aggressively (favor any fit). ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Slight penalty for accumulating many open bins with scattered residuals.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a convex penalty.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 60.0 * tightness * tightness;

    // Penalize leaving dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0 + 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room exactly sized for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (-gap / 12.0).exp();
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discourage opening new bins when many open bins have ample mean residual.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / (bin_capacity as f64);
        score += 30.0 + 40.0 * pressure + (open_bins_count as f64).sqrt() * 4.0;
        // Early in the stream, be slightly more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    } else {
        // Mild bonus for using bins that are already partially filled deeply.
        let fill = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
        score -= 10.0 * fill;
    }

    // Coupling: prefer placements whose post_residual aligns with typical item granularity.
    let align = ((post_residual as f64) % 10.0) / 10.0;
    score += 3.0 * align;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: quadratic dead-space penalty, softened late in stream
    let mut score = norm_pr * norm_pr * cap;

    // Smooth cubic coupling of dead space with stream progress:
    // late in the stream, small residuals matter more (waste is locked in)
    score += 20.0 * norm_pr * norm_pr * norm_pr * (progress * progress * (3.0 - 2.0 * progress));

    // Reward tight fits: subtract a smooth function of item fraction filling the bin
    let fill = item_size as f64 / cap;
    score -= 15.0 * fill * fill * (1.0 - norm_pr);

    // Lookahead: reward bins whose post-residual matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs() / cap;
        score += 8.0 * gap * gap;
        // bonus if next item fits exactly-ish
        score -= 6.0 * (-gap * 10.0).exp() * (nxt / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Penalize bins that are outliers vs mean residual (smooth)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Many open bins: slight penalty to discourage spreading
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: keep it competitive only when residuals are all poor
