    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover is
    // under common item-size classes (mod 10 bands).
    let cap = bin_capacity as f64;
    let fill = (bin_capacity - post_residual) as f64 / cap; // 0..1 fill fraction

    // Reward high fill ratio strongly.
    score -= 30.0 * fill * fill;

