        } else {
            score -= 4.0;
        }
        // Harmonic classes via integer division thresholds
        let class = pr / 10; // 0..10
        match class {
            0 => score += 10.0,          // 1..9: dead space
            1 => score += 3.0,           // 10..19: fits only tiny items
            2 | 3 => score -= 2.0,       // 20..39: decent
            4..=6 => score -= 5.0,       // 40..69: very reusable
            _ => score -= 1.0,           // large leftover: bin was barely used
        }
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
