    if post_residual == 0 {
        score -= 100.0;
    }

    // Gap usability for the lookahead item (k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // gap remains useful
        } else if post_residual > 0 {
            // gap is dead for the next item; penalize proportionally to how close it was
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a decent fit
    // or open-bin pressure is high.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let good_fit_exists = fitting_bins_count >= 1 && (bin_capacity - item_size) as f64 > mean_residual;
        if good_fit_exists && pressure < 8.0 {
            score += 120.0; // keep using existing bins
        } else {
            score -= 10.0; // allow opening when bins are many or fits are bad
