    }

    // Mild pressure: many open bins -> favor consolidating into fuller ones.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins tighter than average (below-mean residual = already dense).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.4;
    } else {
        score += (residual_f - mean_residual) * 0.2;
    }

    // Early in the stream, be slightly conservative about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
