        score -= poor_fits * 0.9;
        // Early in the stream, opening bins is cheaper.
        score -= 20.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mild penalty for very small dead space (<10) that likely goes unused.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
