pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "usable" is the residual?
    // Residuals divisible by common item sizes (10/20/25/50) are valuable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -40.0 // perfect fit is the best outcome
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -7.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Dead-space penalty: small unusable residuals (below the smallest item) are wasted.
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr < 20 {
        score += 8.0;
    }

    // Lookahead coupling: reward if the next item exactly fits the post-residual,
    // penalize if next item cannot fit in the leftover.
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt == pr {
            score -= 22.0;
        } else if pr >= nxt {
            score -= (pr - nxt) as f64 * 0.3;
        } else {
            score += (nxt - pr) as f64 * 0.4;
        }
        // Harmonic class match between leftover and next item
        if pr % nxt == 0 && pr > 0 {
            score -= 9.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins: tighten based on fill fraction.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * 12.0;

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = cap * 0.9 - pressure * cap * 0.85 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // stacking large items together is fine
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item are "dead space". Penalize them super-linearly.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Bonus for near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here after placement; mild penalty.
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few open
    // bins, slightly encourage filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (mean_residual / bin_capacity as f64).max(0.0);

    // New-bin candidate handling: an empty bin has high post_residual; only allow
    // it to win when no open bin fits well (large dead-space risk elsewhere).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; decreases if current open bins are crowded.
        let crowding = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = bin_capacity as f64 * 0.9 - crowding * 30.0 + pressure * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: opening is clearly right
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chaining), penalize near misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            // Next item fits after this placement: reward tight chains.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted residual that's too small to be useful.
            let waste = -diff;
            if waste <= 10.0 {
