        score -= 10.0;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose bins.
    let mean_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit_penalty = if fitting_bins_count == 0 {
            -50.0 // nothing else fits: open a new bin
        } else {
            40.0 + 0.5 * open_bins_count as f64 // discourage fragmentation
        };
        score += poor_fit_penalty;
    }

    // Slight preference for consolidating into fewer bins early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

