    if bin_residual == bin_capacity {
        // opening a new bin is penalized, more so when other bins fit and are tight
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity as u32 - item_size {
            score -= 5.0; // fresh bin can also host next item
        }
    }

    // Prefer bins tighter than the mean residual (good fits concentrate space).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Slight preference to spread load when many bins are open and residuals high.
    if open_bins_count > 4 && post_residual as f64 > mean_residual {
        score += 2.0;
    }

    // Integer-division threshold: reward leaving residuals in the "half-capacity
    // usable" band via floor division classes.
    let half_class = (pr / 25) as f64;
    score -= 1.5 * half_class;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals too small to hold the smallest
    // plausible future item are nearly worthless dead space.
    let dead_threshold = 12u32;
    if post_residual < dead_threshold {
        score -= 40.0 * (dead_threshold - post_residual) as f64;
    } else {
        // Smooth preference for tight fits in the usable range.
        score -= 8.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Penalize unusable gaps that also fail to fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward gaps that exactly or nearly fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 2.0 + 4.0 * progress;
    score += pressure * open_bins_count as f64;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (mean_residual - item_size as f64).abs() < 20.0;
        if good_fit_exists {
            score += 30.0 + 5.0 * open_bins_count as f64;
        } else {
            score += 10.0;
        }
    }

    // Slight tie-break toward bins whose residual is close to the item.
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
