pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: next item exactly fills remaining space.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Next item fits into post_residual: good 2-step chain.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.25 * (post_residual as f64 - next_item_size as f64);
    }
    // Dead space: post_residual too small for any plausible item (min size 1, but
    // penalize unusable slivers relative to typical item sizes).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a bin near the mean residual keeps the fleet balanced.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; prefer tight packing.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual == bin_capacity;
        if good_fit_exists {
            // Penalize opening a new bin when open bins can fit the item,
            // unless the fit would be terrible (post_residual < 15 everywhere).
            let poor_fit = mean_residual < 20.0 && (mean_residual - item_size as f64) < 15.0;
            if poor_fit {
                score -= 10.0;
            } else {
                score += 30.0;
            }
        }
        // Early in stream, allow more bins.
        if step_index * 4 < total_items {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Lookahead: reward if the next item can fit into the post residual (chaining),
    // penalize if the leftover is a "dead" sliver that nothing useful can fill.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 6.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // leftover cannot host the next item: penalize proportionally to wasted space
            score += 3.0 * post_residual as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent fits exist,
    // but allow it when the mean residual of open bins is small (poor global state)
    // or when the fit into any open bin would be very loose.
    if bin_residual == bin_capacity {
        let open_pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a fresh bin, discounted as open bins get crowded.
        let mut new_bin_cost = 30.0 - 22.0 * open_pressure;
        // Late in the stream, slightly discourage spawning extra bins.
        new_bin_cost *= 1.0 + 0.5 * progress;
        // If this item would leave a large unusable gap in any existing bin, opening
        // a fresh bin becomes relatively more attractive.
        if fit_ratio < 0.35 {
            new_bin_cost -= 10.0 * (0.35 - fit_ratio);
        }
        score += new_bin_cost.max(2.0);
    }

    // Mild diversity pressure: with many open bins, prefer consolidating into
    // existing ones rather than spreading residuals.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Small tie-breaker favoring bins whose residual is close to the mean
    // (keeps residuals balanced, preserving future placement options).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Non-linear coupling: squared post-residual penalty grows with stream progress.
    score += 0.8 * pr * pr / cap * (0.3 + 0.7 * progress);

    // Reward leaving residual that could fit the next item (lookahead harmony).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = pr - nx;
            score -= 6.0 * (1.0 - slack / cap) * (1.0 - progress * 0.5);
        } else {
            // Dead space relative to next item penalized smoothly.
            score += 0.35 * (nx - pr) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr * 0.5);
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer bins with residual close to item size.
        let fit_quality = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
        score -= 3.0 * fit_quality * fit_quality;
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Prefer bins whose residual deviates from the mean in a compact direction.
    score += 0.2 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Reward small post_residual (tight fits), with harmonic weighting
    let harmonic = 1.0 / (1.0 + frac * 8.0);
    score -= harmonic * 25.0;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Penalize dead-space classes: leftovers that no item (1..=100, min 10 here) can use
    // Items >= 10, so residual < 10 is pure dead space unless zero.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Modulo logic on post_residual: leftovers that pair with common item sizes
    // (e.g., residual divisible by 10 or 25 can be filled by typical items)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0; // chains nicely
            // extra reward if next item nearly fills it
            let nxt_gap = post_residual - next_item_size;
            if nxt_gap <= 5 {
                score -= 35.0;
            }
        } else {
            // next item won't fit here; penalize waste proportional to overflow class
            let overflow_class = (next_item_size - post_residual) / 10; // integer division threshold
            score += 8.0 * overflow_class as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: opening a new bin costs; only attractive when current bin
    // would leave a large awkward residual or no open bin fits well.
    if bin_residual == bin_capacity {
        // New bin baseline: residual after placing = cap - item_size
        let new_res = cap - item_size as f64;
        // Prefer new bin only if placing here would create tiny dead residue elsewhere
        // i.e., when existing bins are all quite full (low mean residual)
        let pressure = mean_residual / cap;
        score = new_res + 30.0 - pressure * 40.0;
        if next_item_size > 0 && item_size >= 70 {
            score -= 20.0; // big item deserves a fresh bin
        }
        // late in stream, avoid spawning bins for small items
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size < 30 && progress > 0.5 {
            score += 25.0;
        }
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 2.0;

    score
}

